export type UsageIntervalRecord = {
  start_instant?: string | null;
  end_instant?: string | null;
  duration_seconds?: number | null;
  start_status?: (typeof INTERVAL_ENDPOINT_STATUS_VALUES)[number] | null;
  end_status?: (typeof INTERVAL_ENDPOINT_STATUS_VALUES)[number] | null;
};

function parseUsageInterval(value: unknown, path: string): UsageIntervalRecord {
  if (!isRecord(value)) throw new Error(`${path} must be an object`);
  rejectUnknown(value, new Set(["start_instant", "end_instant", "duration_seconds", "start_status", "end_status"]), path);
  for (const field of ["start_instant", "end_instant"]) {
    if (value[field] != null && typeof value[field] !== "string") throw new Error(`${path}.${field} must be a string or null`);
  }
  if (value.duration_seconds != null && (typeof value.duration_seconds !== "number" || !Number.isFinite(value.duration_seconds))) throw new Error(`${path}.duration_seconds must be finite or null`);
  for (const field of ["start_status", "end_status"]) {
    if (Object.hasOwn(value, field) && value[field] !== null && (typeof value[field] !== "string" || !(INTERVAL_ENDPOINT_STATUS_VALUES as readonly string[]).includes(value[field]))) throw new Error(`${path}.${field} is unknown`);
  }
  return value;
}

