function validateOwnedActions(value: unknown, path: string): Set<string> {
  const ids = new Set<string>();
  if (value == null) return ids;
  if (!Array.isArray(value)) throw new Error(`${path} must be an array or null`);
  for (const [index, action] of value.entries()) {
    const itemPath = `${path}[${index}]`;
    if (!isRecord(action)) throw new Error(`${itemPath} must be an object`);
    rejectUnknown(action, new Set(["task_action_id", "app_identifier", "action_label", "assigned_role_labels", "denotes_interval", "action_content_json", "source_locators"]), itemPath);
    const id = requiredString(action, "task_action_id", itemPath);
    if (!id.trim() || ids.has(id)) throw new Error(`${itemPath}.task_action_id is blank or duplicated within its owner`);
    ids.add(id);
    if (!Array.isArray(action.source_locators) || !stringArray(action, "source_locators", itemPath).length
      || stringArray(action, "source_locators", itemPath).some(s => !s.trim())) throw new Error(`${itemPath}.source_locators must be a non-empty string array`);
    if (action.action_label != null && typeof action.action_label !== "string") throw new Error(`${itemPath}.action_label must be a string or null`);
    if (action.app_identifier != null && (typeof action.app_identifier !== "string" || !action.app_identifier.trim())) throw new Error(`${itemPath}.app_identifier must be nonblank or null`);
    if (action.denotes_interval != null) parseUsageInterval(action.denotes_interval, `${itemPath}.denotes_interval`);
    if (action.action_content_json != null) {
      if (typeof action.action_content_json !== "string") throw new Error(`${itemPath}.action_content_json must be a string or null`);
      try { JSON.parse(action.action_content_json); } catch { throw new Error(`${itemPath}.action_content_json must contain valid JSON`); }
    }
    if (action.assigned_role_labels != null && (!Array.isArray(action.assigned_role_labels)
      || stringArray(action, "assigned_role_labels", itemPath).some(s => !s.trim()))) throw new Error(`${itemPath}.assigned_role_labels must be a nonblank string array or null`);
  }
  return ids;
}

