const depressionTrafficTaskKeys = ["diary.phq9_instrument","outcome.clinician_assessment","outcome.depressed_followup","validation.classification_ground_truth"];
function matchesDepressionTrafficTaskDefinition(setting: MethodSettingAssertion | undefined, content: unknown, kind: DisclosedTaskDefinitionKind, work: string): boolean | undefined {
  const key = String(setting?.method_parameter_key);
  if (!depressionTrafficTaskKeys.includes(key)) return undefined;
  const expected = requireDefined(depressionTrafficDefinitions[key], TABLE_ENTRY);
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  return !!setting && setting.source_work_id === depressionTrafficWork && work === depressionTrafficWork
    && (kind === "criterion" || kind === "response" && key === "diary.phq9_instrument")
    && setting.method_setting_role === expected.role && setting.method_target_layer === expected.target
    && sourceDefinitionTupleMatches(content, expected.role, expected.target) && canonicalJson(body) === canonicalJson(expected.body);
}
