function validateDepressionTrafficObservation(row: SampledQuantityObservationRecord, path: string, profiles: StudyMethodProfile[], tasks: TaskOccurrenceRecord[]) {
  if (row.source_work_id !== depressionTrafficWork) return;
  const profile = profiles.find(p => p.method_profile_id === row.method_profile_id);
  const key = String(profile?.method_settings.find(s => s.method_setting_id === row.method_setting_reference)?.method_parameter_key);
  for (const property of ["screen-on duration", "retained screen-on duration", "remaining screen-off duration", "duration"]) {
    const value = nextAppQuantity(row, property);
    if (typeof value === "number" && value < 0) throw new Error(path + " contains a negative supplied duration");
  }
  for (const property of ["payload size bytes", "sum of payload sizes s"]) {
    const value = nextAppQuantity(row, property);
    if (typeof value === "number" && (value < 0 || !Number.isInteger(value))) throw new Error(path + " requires a nonnegative integer supplied payload-byte count");
  }
  if (key === "reconstruction.screen_interval_cap") {
    const retained = nextAppQuantity(row, "retained screen-on duration");
    if (typeof retained === "number" && retained > 60) throw new Error(path + " contradicts the supplied 60-minute screen cap");
  }
  if (row.task_occurrence_reference != null) {
    if (!["aggregation.phq9_feature_window", "features.aggregate_usage", "features.category_usage", "features.volume", "analysis.regression_models", "analysis.classification_model"].includes(key)) throw new Error(path + " cannot assign this traffic observation to a PHQ completion");
    const task = tasks.find(t => t.task_occurrence_id === row.task_occurrence_reference && t.method_profile_id === row.method_profile_id
      && t.source_work_id === row.source_work_id && t.participant_id === row.participant_id && (t.device_id ?? null) === (row.device_id ?? null));
    const instrument = profile?.method_settings.find(s => s.method_parameter_key === "diary.phq9_instrument")?.method_setting_id;
    if (!task || !instrument || !task.task_questionnaire_responses?.some(r => r.questionnaire_setting_reference === instrument)
      && !task.criterion_assessments?.some(a => a.criterion_setting_reference === instrument)) throw new Error(path + " has no supplied PHQ-9 completion");
  }
}
function validateDepressionTrafficResolvedReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string, rows: SampledQuantityObservationRecord[], profiles: StudyMethodProfile[]) {
  const known = (property: string) => nextAppQuantity(row, property);
  const agrees = (property: string, roles: string[]) => {
    const values = [known(property), ...resolved.filter(link => roles.includes(link.role)).map(link => nextAppQuantity(link.target, property))].filter(value => value != null);
    if (values.some(value => value !== values[0])) throw new Error(path + " contradicts a known supplied " + property);
  };
  if (key === "quality.android_screen_traffic_gate" && resolved.some(link => link.role === "raw packet" && nextAppQuantity(link.target, "platform") === "iOS")) throw new Error(path + " cannot apply the Android screen gate to a known iOS packet");
  if (key === "quality.keepalive_removal") {
    const status = known("disposition"), designation = resolved.find(link => link.role === "keep-alive designation");
    const keepalive = designation && nextAppQuantity(designation.target, "identified keep-alive");
    if (keepalive === true && status === "retained" || keepalive === false && status === "removed") throw new Error(path + " contradicts its supplied keep-alive designation");
    const gate = resolved.find(link => link.role === "screen-gated packet");
    if (gate && designation?.target.sampled_observation_references?.some(link => link.relationship_label === "classified packet" && link.sampled_observation_reference != null && link.sampled_observation_reference !== gate.target.sampled_observation_id)) throw new Error(path + " mixes independent packet designations");
  }
  if (key === "schema.aggregated_application_session" && resolved.some(link => nextAppQuantity(link.target, "disposition") === "removed")) throw new Error(path + " contains a known removed packet");
  if (key === "reconstruction.usage_session_gap_rules") {
    const stage = known("aggregation stage");
    if (resolved.some(link => link.role === "minute-bin member") && resolved.some(link => link.role === "within-IP member")) throw new Error(path + " mixes the supplied reconstruction stages");
    if (stage === "within external IP" && resolved.some(link => link.role !== "minute-bin member")
      || stage === "across external IPs" && resolved.some(link => link.role !== "within-IP member")) throw new Error(path + " mixes the supplied reconstruction stages");
    agrees("external IP address a", ["minute-bin member"]);
  }
  if (key === "category.first_match_policy") agrees("external IP address a", ["external-IP usage session", "DBIP response"]);
  if (key === "reconstruction.category_overlap_merge") agrees("category", ["categorized session member"]);
  if (key === "reconstruction.on_off_definition") {
    const period = known("period type");
    if (resolved.some(link => link.role === "merged usage session") && resolved.some(link => link.role !== "merged usage session")) throw new Error(path + " mixes supplied on/off-period memberships");
    if (period === "on-period" && resolved.some(link => link.role !== "merged usage session")
      || period === "off-period" && resolved.some(link => link.role === "merged usage session")) throw new Error(path + " mixes supplied on/off-period memberships");
  }
  if (key.startsWith("features.") || ["analysis.regression_models", "analysis.classification_model"].includes(key)) {
    const completions = [row.task_occurrence_reference, ...resolved.map(link => link.target.task_occurrence_reference)].filter(value => value != null);
    if (["analysis.regression_models", "analysis.classification_model"].includes(key)) {
      const settings = profiles.find(profile => profile.method_profile_id === row.method_profile_id && profile.source_work_id === row.source_work_id)?.method_settings;
      for (const { target: feature } of resolved) {
        for (const link of feature.sampled_observation_references ?? []) {
          if (link.relationship_label !== "PHQ feature window" || link.sampled_observation_reference == null) continue;
          const windows = rows.filter(window => window.sampled_observation_id === link.sampled_observation_reference
            && window.method_profile_id === feature.method_profile_id && window.source_work_id === feature.source_work_id
            && window.participant_id === feature.participant_id
            && (feature.device_id == null || window.device_id == null || window.device_id === feature.device_id));
          const window = windows[0], setting = settings?.find(candidate => candidate.method_setting_id === window?.method_setting_reference);
          if (windows.length !== 1 || window === undefined || window === feature || setting?.method_parameter_key !== "aggregation.phq9_feature_window"
            || setting.source_work_id !== row.source_work_id) throw new Error(path + " must resolve unambiguously to a compatible, distinct sampled observation");
          if (row.device_id != null && window.device_id != null && row.device_id !== window.device_id) throw new Error(path + " contradicts a known PHQ window device");
          if (window.task_occurrence_reference != null) completions.push(window.task_occurrence_reference);
        }
      }
    }
    if (completions.some(value => value !== completions[0])) throw new Error(path + " mixes independent PHQ completions");
  }
  if (["analysis.regression_models", "analysis.classification_model"].includes(key)) {
    const combination = known("feature combination");
    if (typeof combination === "string" && resolved.some(link => !combination.split("+").includes(requireDefined(link.role.split(" ")[0], "String.prototype.split returns at least one part")))) throw new Error(path + " contradicts its supplied feature combination");
  }
  // Supplied identities/supports only: no IP mapping, screen-time conversion, pairing,
  // keep-alive detection, binning, grouping, category lookup/matching, calendar
  // endpoint selection, arithmetic, PHQ scoring or model execution.
}

