function windowFamilyDefinitionMatches(owner: StudyMethodProfile, key: string): boolean {
  const expected = windowFamilyDefinitions[owner.source_work_id]?.[key];
  const locals = owner.method_settings.filter(s => s.method_parameter_key === key), setting = locals[0];
  if (!expected || locals.length !== 1 || setting === undefined || setting.source_work_id !== owner.source_work_id) return false;
  let content: unknown;
  try { content = JSON.parse(String(setting.method_value_json)); } catch { return false; }
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  return setting.method_setting_role === expected.role && setting.method_target_layer === expected.target
    && sourceDefinitionTupleMatches(content, expected.sourceRole, expected.sourceTarget)
    && canonicalJson(body) === canonicalJson(expected.definition);
}
