function changObservationShape(row: Record<string, unknown>, path: string, profiles: StudyMethodProfile[], owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined) {
  const key = String(setting?.method_parameter_key);
  if (!Object.hasOwn(changObservationProperties, key)) return undefined;
  const spec = requireDefined(communicationDefinitionSpecs[key], TABLE_ENTRY);
  // This source's earlier qualified envelopes lack mandatory source-facing fields.
  // The existing qualified matcher accepts that absence, never a declared false tuple.
  validateProfileRecordOwner(row, path, profiles, spec.role, spec.target);
  let content: unknown;
  try { content = JSON.parse(String(setting?.method_value_json)); } catch { /* Unparseable JSON leaves content undefined, which reads as incompatible below. */ }
  const companion = (otherKey: string): boolean => {
    const locals = owner?.method_settings.filter(s => s.method_parameter_key === otherKey) ?? [], local = locals[0];
    return locals.length === 1 && local !== undefined && communicationDefinitionMatches(local, JSON.parse(String(local.method_value_json)), changCommunicationWork);
  };
  const compatible = communicationDefinitionMatches(setting, content, String(owner?.source_work_id))
    && (key !== "acquisition.target_event_snapshot" || (companion("snapshot.context_channels") && companion("snapshot.activity_states")));
  return { compatible, entity: "device", properties: requireDefined(changObservationProperties[key], TABLE_ENTRY), unit: undefined,
    unitsByProperty: undefined, screenTimeQualifiers: undefined, sourceQualifiers: false,
    categoricalValuesByProperty: {
      "attending action": requireDefined(communicationDefinitionSpecs["feature.attending_action_set"], FIXED_KEY).body as string[],
      "semantic locale": ["Home", "Work", "Catch-up", "Social", "Other"],
      "Google activity recognition": ["still", "tilting", "in vehicle", "biking", "on foot"],
      "ringer mode": ["Normal", "Vibrate", "Silent"],
      event: ["incoming SMS", "outgoing SMS", "incoming MMA", "outgoing MMA", "phone call initiation", "phone call receipt", "phone call ending", "VOIP call initiation", "VOIP call receipt", "VOIP call ending", "video call initiation", "video call receipt", "video call ending", "ringer-mode change", "wake", "unlock", "wake/unlock", "notification action"],
    } as Record<string, readonly string[]>,
    percentageProperty: undefined, booleanProperty: key === "outcome.same_contact_sms_response" ? "responded" : undefined,
    numericIntegerRanges: undefined };
}
function validateChangObservationUnit(quantity: Record<string, unknown>, work: string, key: string, path: string): string | undefined {
  if (work !== changCommunicationWork || !Object.hasOwn(changObservationProperties, key)) return undefined;
  const expected = key === "feature.sms_notification_first_action" ? "minutes" : undefined;
  if (quantity.evidence_unit != null && quantity.evidence_unit !== expected) throw new Error(path + " has no compatible Chang quantity unit");
  if (quantity.evidence_value_json != null && (expected || key === "preparation.contact_anonymization")) {
    let value: unknown;
    if (typeof quantity.evidence_value_json !== "string") throw new Error(path + " requires a lexical JSON quantity or null");
    try { value = JSON.parse(quantity.evidence_value_json); } catch { throw new Error(path + " requires valid JSON"); }
    if (typeof value === "number" && value < 0) throw new Error(path + " has a negative supplied attending interval");
    if (key === "preparation.contact_anonymization" && value !== null && typeof value !== "string") throw new Error(path + " requires a supplied contact annotation string or null");
  }
  return quantity.evidence_unit == null ? undefined : expected;
}
