function validateChangResolvedReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string) {
  if (key === "preparation.contact_anonymization") {
    const contact = nextAppQuantity(row, "recorded contact");
    for (const link of resolved) {
      const recorded = nextAppQuantity(link.target, "contact");
      if (contact != null && recorded != null && contact !== recorded) throw new Error(path + " contradicts its known recorded contact");
    }
  }
  const event = (role: string, label: string) => {
    const target = resolved.find(link => link.role === role)?.target;
    const known = target && nextAppQuantity(target, "event");
    if (known != null && known !== label) throw new Error(path + " contradicts its known SMS event direction");
    return target;
  };
  const incoming = event(key === "feature.sms_notification_first_action" ? "incoming SMS notification" : "incoming SMS", "incoming SMS");
  const outgoing = event("outgoing SMS", "outgoing SMS");
  if (incoming && outgoing) {
    const a = nextAppQuantity(incoming, "contact"), b = nextAppQuantity(outgoing, "contact");
    if (a != null && b != null && a !== b) throw new Error(path + " contradicts its known same-contact SMS response");
  }
  const action = resolved.find(link => link.role === "first later attending action")?.target;
  if (incoming && action && nextAppQuantity(action, "attending action") === "composing outgoing messages in the same communication app that generated the notification") {
    const a = nextAppQuantity(incoming, "communication app"), b = nextAppQuantity(action, "communication app");
    if (a != null && b != null && a !== b) throw new Error(path + " contradicts its known same-app attending action");
  }
  // These are supplied proxy supports, not certified chronology, lastness,
  // reading ground truth, contact matching, GPS annotation or arithmetic.
}
function validateRingerOwnedChildren(record: Record<string, unknown>, owner: StudyMethodProfile, path: string) {
  const actionIds = validateOwnedActions(record.session_actions, path + ".session_actions");
  if (!Object.hasOwn(record, "session_actions") && !Object.hasOwn(record, "session_quantities")) return;
  if (owner.source_work_id !== changCommunicationWork) throw new Error(path + " has no compatible Chang occupancy children");
  const matchesLocal = (key: string): boolean => {
    const locals = owner.method_settings.filter(s => s.method_parameter_key === key), local = locals[0];
    return locals.length === 1 && local !== undefined && communicationDefinitionMatches(local, JSON.parse(String(local.method_value_json)), owner.source_work_id);
  };
  if (!matchesLocal("feature.attending_action_set")) throw new Error(path + " has no compatible attending-action definition");
  for (const action of recordsOf(record.session_actions)) {
    if (action.action_label != null && (typeof action.action_label !== "string" || !(requireDefined(communicationDefinitionSpecs["feature.attending_action_set"], FIXED_KEY).body as string[]).includes(action.action_label))) throw new Error(path + " has an unknown attending-action designation");
  }
  if (record.session_quantities == null) return;
  if (!Array.isArray(record.session_quantities)) throw new Error(path + ".session_quantities must be an array or null");
  const ids = new Set<string>();
  for (const [i, quantity] of record.session_quantities.entries()) {
    const itemPath = path + ".session_quantities[" + i + "]";
    if (!isRecord(quantity)) throw new Error(itemPath + " must be an object");
    rejectUnknown(quantity, new Set(["quantity_record_id", "quantity_setting_reference", "quantity_scope", "observed_property", "evidence_value_json", "evidence_unit", "start_action_reference", "end_action_reference", "source_locators"]), itemPath);
    const id = requiredString(quantity, "quantity_record_id", itemPath);
    if (!id.trim() || ids.has(id)) throw new Error(itemPath + " has a blank or duplicate quantity identity");
    ids.add(id);
    const setting = owner.method_settings.find(s => s.method_setting_id === quantity.quantity_setting_reference);
    const key = String(setting?.method_parameter_key);
    const gap = key === "feature.general_attentiveness_gap", mean = key === "feature.within_ringer_interval_attendance", code = key === "feature.attendance_bins";
    const content: unknown = typeof setting?.method_value_json === "string" ? JSON.parse(setting.method_value_json) : null;
    if ((!gap && !mean && !code) || !communicationDefinitionMatches(setting, content, owner.source_work_id)
      || quantity.quantity_scope !== "session"
      || quantity.observed_property !== (gap ? "attending-action interval" : mean ? "mean attending-action interval" : "attendance code")
      || (quantity.evidence_unit != null && quantity.evidence_unit !== (code ? undefined : "minutes"))) throw new Error(itemPath + " has no compatible occupancy quantity definition/property/unit/scope");
    const endpoints: string[] = [];
    for (const field of ["start_action_reference", "end_action_reference"]) {
      if (Object.hasOwn(quantity, field) && !gap && !code) throw new Error(itemPath + " endpoint references belong to a supplied action gap/category, not a mean");
      if (quantity[field] != null) {
        if (typeof quantity[field] !== "string" || !quantity[field].trim() || !actionIds.has(quantity[field])) throw new Error(itemPath + " must resolve each endpoint within its own occupancy actions");
        endpoints.push(quantity[field]);
      }
    }
    if (endpoints.length === 2 && endpoints[0] === endpoints[1]) throw new Error(itemPath + " must retain distinct gap endpoints");
    if (quantity.evidence_value_json != null) {
      if (typeof quantity.evidence_value_json !== "string") throw new Error(itemPath + " requires a lexical JSON quantity or null");
      let value: unknown;
      try { value = JSON.parse(quantity.evidence_value_json); } catch { throw new Error(itemPath + " requires valid JSON"); }
      if (value !== null && typeof value !== "number" && typeof value !== "string") throw new Error(itemPath + " requires a scalar quantity");
      if (typeof value === "number" && (!Number.isFinite(value) || (code ? ![1, 2, 3].includes(value) : value < 0))) throw new Error(itemPath + " has an invalid supplied quantity/code");
    }
    if (!Array.isArray(quantity.source_locators) || !stringArray(quantity, "source_locators", itemPath).length
      || stringArray(quantity, "source_locators", itemPath).some(locator => !locator.trim())) throw new Error(itemPath + " requires source locators");
  }
}

function validateCommunicationCriterion(assessment: Record<string, unknown>, owner: StudyMethodProfile, path: string) {
  if (owner.source_work_id !== smsPersonalityWork) return;
  const key = owner.method_settings.find(s => s.method_setting_id === assessment.criterion_setting_reference)?.method_parameter_key;
  if (key === "outcome.five_traits" && !(requireDefined(communicationDefinitionSpecs[key], FIXED_KEY).body as { traits: string[] }).traits.includes(String(assessment.criterion_label))) throw new Error(path + " has no disclosed BFI trait designation");
  if (key === "outcome.three_class_labels" && assessment.assessment_value_json != null) {
    if (typeof assessment.assessment_value_json !== "string") throw new Error(path + " requires a lexical JSON assessment or null");
    const value: unknown = JSON.parse(assessment.assessment_value_json);
    if (value !== null && (typeof value !== "string" || !(requireDefined(communicationDefinitionSpecs[key], FIXED_KEY).body as { classes: string[] }).classes.includes(value))) throw new Error(path + " has no disclosed low/average/high class label");
  }
}

function validateChangResponseActionSupports(response: Record<string, unknown>, row: Record<string, unknown>,
  owner: StudyMethodProfile, setting: MethodSettingAssertion | undefined, actionIds: Set<string>, path: string) {
  if (!Object.hasOwn(response, "support_task_action_references")) return;
  if (validateDynamicSecurityAnswerSupports(response, row, owner, setting, actionIds, path)) return;
  if (owner.source_work_id !== changCommunicationWork || setting?.source_work_id !== owner.source_work_id
    || setting.method_parameter_key !== "diary.retrospective_event_index") throw new Error(path + " has no compatible retrospective event supports");
  if (response.support_task_action_references == null) return;
  if (!Array.isArray(response.support_task_action_references)) throw new Error(path + ".support_task_action_references must be an array or null");
  const refs = stringArray(response, "support_task_action_references", path);
  if (new Set(refs).size !== refs.length || refs.some(ref => !ref.trim() || !actionIds.has(ref))) throw new Error(path + " has duplicate or missing retrospective actions within task");
  for (const reference of refs) {
    const action = requireDefined(recordsOf(row.task_actions).find(a => a.task_action_id === reference), TASK_ACTION);
    if (action.action_label != null && (typeof action.action_label !== "string" || !["ringer change", "missed call", "unread-notification interval over one hour"].includes(action.action_label))) throw new Error(path + " must retain a retrospective source event, not prompt/answer timing");
  }
  // End-of-day selection refers to the preceding24h as a definition, not an
  // event-relative window, reconstructed clock anchor or original selection.
}

