function dynamicSecurityDefinitionMatches(setting:MethodSettingAssertion|undefined, content:unknown, key:string): boolean {
  const spec=dynamicSecurityDefinitions[key];
  if (!setting || !spec || setting.source_work_id !== dynamicSecurityWork || setting.method_parameter_key !== key) return false;
  const body=isRecord(content) && Object.hasOwn(content,"definition") ? content.definition : content;
  return setting.method_setting_role === spec.role && setting.method_target_layer === spec.target
    && sourceDefinitionTupleMatches(content,spec.sourceRole,spec.sourceTarget)
    && canonicalJson(body) === canonicalJson(spec.body);
}
function dynamicSecurityLocalDefinition(owner:StudyMethodProfile, key:string): boolean {
  const candidates=owner.method_settings.filter(s=>s.method_parameter_key === key), local=candidates[0];
  if (candidates.length !== 1 || local === undefined || owner.source_work_id !== dynamicSecurityWork) return false;
  let content:unknown;
  try { content=JSON.parse(String(local.method_value_json)); } catch { return false; }
  return dynamicSecurityDefinitionMatches(local,content,key);
}
function matchesDynamicSecurityTaskDefinition(setting:MethodSettingAssertion|undefined, content:unknown, kind:DisclosedTaskDefinitionKind, sourceWorkId:string): boolean|undefined {
  const key=String(setting?.method_parameter_key);
  const recognized=dynamicSecurityResponseKeys.some(k=>k===key) || dynamicSecurityCriterionKeys.some(k=>k===key);
  if (!recognized) return undefined;
  const allowed=kind === "response" ? dynamicSecurityResponseKeys.some(k=>k===key) : kind === "criterion" && dynamicSecurityCriterionKeys.some(k=>k===key);
  return sourceWorkId === dynamicSecurityWork && allowed && dynamicSecurityDefinitionMatches(setting,content,key);
}
function isDynamicSecurityCaseResponse(owner:StudyMethodProfile, setting:MethodSettingAssertion|undefined): boolean {
  return owner.source_work_id === dynamicSecurityWork && setting?.source_work_id === dynamicSecurityWork
    && dynamicSecurityCaseKeys.some(key=>key===setting.method_parameter_key)
    && dynamicSecurityLocalDefinition(owner,"field.question_sets")
    && dynamicSecurityLocalDefinition(owner,"field.question_identity");
}
function validateDynamicSecurityResponse(response:Record<string,unknown>, owner:StudyMethodProfile, setting:MethodSettingAssertion|undefined, path:string): void {
  if (owner.source_work_id !== dynamicSecurityWork) return;
  const key=String(setting?.method_parameter_key);
  const properties:Record<string,readonly string[]>={
    "communication.response":["incoming call person","outgoing call person","received SMS person","sent SMS person"],
    "app.answer_format":["applications used"],"music.answer_format":["music listened to"],
    "activity.answer_format":["activities and times"],"battery.answer_format":["charging time and mode"],
    "location.map":["visited location"],"confidence.measure":["answer confidence"],
    "survey.protocol":(requireDefined(dynamicSecurityDefinitions["survey.protocol"], FIXED_KEY).body as {printed_table_10_statement_labels:string[]}).printed_table_10_statement_labels,
    "survey.qualitative":["replacement preference","usability concerns"],
  };
  if (!properties[key]) return;
  if (!properties[key].includes(String(response.observed_property))) throw new Error(path+" does not retain the disclosed DynamicSecurity answer/topic meaning");
  if (key === "survey.protocol" && response.questionnaire_item_label != null
    && !dynamicSecurityQuestionTypes.some(type => type === response.questionnaire_item_label)) throw new Error(path+" has no printed Table10 question-type column");
  if (response.response_value_json == null || !["confidence.measure","survey.protocol"].includes(key)) return;
  const value:unknown=JSON.parse(response.response_value_json as string);
  // Numeric ordinal boundaries only; lexical tokens remain supplied, not parsed or recoded.
  if (value !== null && typeof value !== "string" && typeof value !== "number") throw new Error(path+" requires a supplied ordinal scalar or unknown, not Boolean/structured content");
  if (typeof value === "number" && (!Number.isInteger(value) || value<1 || value>5)) throw new Error(path+" has no supplied ordinal position in the disclosed 1–5 scale");
}
function validateDynamicSecurityAnswerSupports(response:Record<string,unknown>, row:Record<string,unknown>, owner:StudyMethodProfile,
  setting:MethodSettingAssertion|undefined, actionIds:Set<string>, path:string): boolean {
  if (owner.source_work_id !== dynamicSecurityWork) return false;
  if (!isDynamicSecurityCaseResponse(owner,setting)) throw new Error(path+" has no compatible DynamicSecurity answer-local supports");
  if (response.support_task_action_references == null) return true;
  if (!Array.isArray(response.support_task_action_references)) throw new Error(path+".support_task_action_references must be an array or null");
  const refs=stringArray(response,"support_task_action_references",path);
  if (new Set(refs).size!==refs.length || refs.some(ref=>!ref.trim() || !actionIds.has(ref))) throw new Error(path+" has duplicate or missing answer actions within task");
  for (const reference of refs) {
    const action=requireDefined(recordsOf(row.task_actions).find(a=>a.task_action_id===reference), TASK_ACTION);
    const knownRoles=Array.isArray(action.assigned_role_labels) ? action.assigned_role_labels : [];
    if (knownRoles.some(role=>["question presentation","confidence rating"].includes(String(role))) && !knownRoles.includes("answer")) throw new Error(path+" names a known non-answer action for answer-local evidence");
  }
  return true;
}
function validateDynamicSecurityTaskOwner(row:Record<string,unknown>, owner:StudyMethodProfile, path:string): void {
  if (!Object.hasOwn(row,"history_subject_participant_id")) return;
  if (owner.source_work_id !== dynamicSecurityWork || !dynamicSecurityLocalDefinition(owner,"field.question_sets")
    || !dynamicSecurityLocalDefinition(owner,"field.question_identity")) throw new Error(path+".history_subject_participant_id has no compatible source-defined question/history ownership");
  if (row.history_subject_participant_id != null && (typeof row.history_subject_participant_id !== "string" || !row.history_subject_participant_id.trim())) throw new Error(path+".history_subject_participant_id must be nonblank or null");
}
function validateDynamicSecurityTaskRelationships(row:Record<string,unknown>, owner:StudyMethodProfile, path:string): void {
  if (owner.source_work_id !== dynamicSecurityWork) return;
  const roles=new Set<string>();
  if (dynamicSecurityUserTypes.includes(row.task_label as typeof dynamicSecurityUserTypes[number])) roles.add(String(row.task_label));
  for (const action of recordsOf(row.task_actions)) for (const role of Array.isArray(action.assigned_role_labels) ? action.assigned_role_labels : []) {
    if (dynamicSecurityUserTypes.includes(role as typeof dynamicSecurityUserTypes[number])) roles.add(String(role));
  }
  if (roles.size>1) throw new Error(path+" has contradictory known DynamicSecurity answering roles");
  const actionCases=new Map<string,string>();
  for (const response of recordsOf(row.task_questionnaire_responses)) {
    if (response.assessment_case_token == null || !Array.isArray(response.support_task_action_references)) continue;
    if (typeof response.assessment_case_token !== "string") throw new Error(path+" requires a supplied lexical question-case identity");
    for (const action of response.support_task_action_references) {
      if (typeof action !== "string") throw new Error(path+" requires supplied local answer-action identities");
      const previous=actionCases.get(action);
      if (previous!==undefined && previous!==response.assessment_case_token) throw new Error(path+" has contradictory known question cases supporting the same answer action");
      actionCases.set(action,response.assessment_case_token);
    }
  }
  if (row.history_subject_participant_id == null) return;
  const role=[...roles][0], same=row.history_subject_participant_id===row.participant_id;
  if (role === "legitimate" && !same || (role === "strong adversary" || role === "naive adversary") && same) throw new Error(path+" contradicts the supplied answering role/history subject");
}
function validateDynamicSecuritySharedCases(rows:TaskOccurrenceRecord[]): void {
  const knownSubjects=new Map<string,string>();
  for (const row of rows) {
    if (row.source_work_id !== dynamicSecurityWork || row.history_subject_participant_id == null) continue;
    for (const response of row.task_questionnaire_responses ?? []) {
      if (response.assessment_case_token == null) continue;
      const key=canonicalJson([row.method_profile_id,row.source_work_id,response.assessment_case_token]);
      const previous=knownSubjects.get(key);
      if (previous!==undefined && previous!==row.history_subject_participant_id) throw new Error("DynamicSecurity shared question case has contradictory known history subjects");
      knownSubjects.set(key,row.history_subject_participant_id);
    }
  }
  // Questions/options share a supplied identity across responders. Wording can change
  // ('you' / 'your partner' / 'a stranger'); no text equality or recovered join runs.
}
function dynamicSecuritySampleSpec(owner:StudyMethodProfile|undefined, setting:MethodSettingAssertion|undefined) {
  return owner?.source_work_id === dynamicSecurityWork ? dynamicSecuritySampleSpecs[String(setting?.method_parameter_key)] : undefined;
}
function isDynamicSecurityPooledObservation(row:Record<string,unknown>, owner:StudyMethodProfile|undefined, setting:MethodSettingAssertion|undefined): boolean {
  const spec=dynamicSecuritySampleSpec(owner,setting);
  return spec?.entity === "participant_group" && row.observed_entity_kind === "participant_group" && setting?.source_work_id === dynamicSecurityWork;
}
function dynamicSecurityObservationShape(row:Record<string,unknown>, owner:StudyMethodProfile|undefined, setting:MethodSettingAssertion|undefined,
  definitionFor:(role:string,target:string,reference?:unknown,sourceTarget?:string,sourceRole?:string)=>unknown) {
  const spec=dynamicSecuritySampleSpec(owner,setting);
  if (!spec || !owner) return undefined;
  const key=String(setting?.method_parameter_key), expected=requireDefined(dynamicSecurityDefinitions[key], TABLE_ENTRY);
  const body=definitionFor(expected.role,expected.target,undefined,expected.sourceTarget,expected.sourceRole);
  const companions=key === "collection.app_schema" ? ["collection.app_foreground_screen_gate"]
    : key === "collection.activity_schema" ? ["collection.activity_vocabulary_conflict"]
    : key === "ranker.weight_formula" ? ["ranker.probability_event","ranker.probability_time_window","ranker.probability_weekday_window","ranker.duration_total","ranker.duration_weight"] : [];
  if (isDynamicSecurityPooledObservation(row,owner,setting) && (row.participant_id != null || row.device_id != null)) throw new Error("DynamicSecurity pooled outputs cannot acquire an invented person/device owner");
  return {compatible:canonicalJson(body)===canonicalJson(expected.body) && companions.every(k=>dynamicSecurityLocalDefinition(owner,k)),
    entity:spec.entity,properties:Object.keys(spec.units),unit:undefined,
    unitsByProperty:Object.fromEntries(Object.entries(spec.units).map(([property,unit])=>[property,unit??undefined])),
    screenTimeQualifiers:undefined,categoricalValuesByProperty:undefined,percentageProperty:undefined,booleanProperty:undefined,
    sourceQualifiers:true,numericIntegerRanges:undefined};
}
function validateDynamicSecurityQualifier(qualifier:unknown, owner:StudyMethodProfile|undefined, setting:MethodSettingAssertion|undefined, path:string):void {
  const spec=dynamicSecuritySampleSpec(owner,setting);
  if (spec?.entity!=="participant_group" || typeof qualifier!=="string") return;
  const key=String(setting?.method_parameter_key), knownAxes=["question type","user type","statement","n","attack regime"];
  const allowed=key==="survey.result_matrix" ? ["statement","question type"]
    : ["bayes.result_matrix","threshold.metrics"].includes(key) ? ["question type","n","attack regime"] : ["question type","user type"];
  const seen=new Set<string>();
  for (const component of qualifier.split(";")) {
    const match=/^\s*([^:]+):\s*(.*?)\s*$/.exec(component);
    if (!match || !knownAxes.includes(requireDefined(match[1], REGEX_GROUP).trim())) continue; // Opaque/unreported supplied axes are not decoded.
    const axis=requireDefined(match[1], REGEX_GROUP).trim(), value=requireDefined(match[2], REGEX_GROUP);
    if (!allowed.includes(axis) || seen.has(axis)) throw new Error(path+" has an incompatible or duplicate known DynamicSecurity output axis");
    seen.add(axis);
    if (axis==="question type" && !dynamicSecurityQuestionTypes.includes(value as typeof dynamicSecurityQuestionTypes[number])
      || axis==="user type" && !dynamicSecurityUserTypes.includes(value as typeof dynamicSecurityUserTypes[number])
      || axis==="attack regime" && !["strong","naive","strong+naive"].includes(value)
      || axis==="statement" && !(requireDefined(dynamicSecurityDefinitions["survey.protocol"], FIXED_KEY).body as {printed_table_10_statement_labels:string[]}).printed_table_10_statement_labels.includes(value)) {
      throw new Error(path+" contradicts a disclosed DynamicSecurity output scope");
    }
    if (axis==="n" && /^-?\d+(?:\.\d+)?$/.test(value)) {
      const n=Number(value);
      if (!Number.isInteger(n) || n<1 || n>6 || key==="bayes.result_matrix" && ![1,3,6].includes(n)) throw new Error(path+" contradicts the disclosed question-count experiment scope");
    }
  }
}
function validateDynamicSecuritySampleValue(value:unknown, property:string, owner:StudyMethodProfile|undefined, setting:MethodSettingAssertion|undefined, path:string):void {
  if (!dynamicSecuritySampleSpec(owner,setting) || value===null) return;
  const key=String(setting?.method_parameter_key);
  const categories:Record<string,readonly string[]>={
    direction:key === "collection.call_schema" ? ["outgoing","incoming"] : ["sent","received"],
    "activity type":["walking","running","in_vehicle","on_bicycle","no_movement"],"power connection type":["AC","USB"],
  };
  if (categories[property] && (typeof value!=="string" || !categories[property].includes(value))) throw new Error(path+" contradicts the disclosed DynamicSecurity category");
  if (typeof value==="number") {
    if (!Number.isFinite(value)) throw new Error(path+" must preserve a finite supplied value");
    if (key !== "bayes.result_matrix" && ["TPR","FPR","F1","AUC","event probability","time-window event probability","weekday-window event probability"].includes(property)
      && (value<0 || value>1)) throw new Error(path+" contradicts a supplied probability domain");
    if (key==="bayes.result_matrix" && ["TPR","FPR","F1","accuracy"].includes(property) && (value<0 || value>100)) throw new Error(path+" must retain a supplied Table9 percent, not a silently rescaled probability");
    if (property==="order" && key==="confidence.rank_matrix" && (!Number.isInteger(value) || value<1 || value>7)) throw new Error(path+" contradicts the separate supplied Table7 order1–7");
    if (["message length","duration","accuracy expected error bound","total event duration","current event duration","mean answer time","median answer time","answer-time SD","mean rank"].includes(property) && value<0) throw new Error(path+" contradicts a nonnegative measure");
    if (["mode","median"].includes(property) && key==="survey.result_matrix" && (value<1 || value>5 || property==="mode" && !Number.isInteger(value))) throw new Error(path+" contradicts the printed exit-survey scale");
  }
  if (!["string","number"].includes(typeof value)) throw new Error(path+" requires an independent lexical/numeric value or unknown");
  // Mean question accuracy may be negative and question-type scales differ.
}

