  requireTimeKillingDefinition(row,profiles,String(setting?.method_parameter_key),path);
  for (const field of fields) if (row[field] != null && (typeof row[field] !== "string" || !String(row[field]).trim())) throw new Error(path + "." + field + " must be a nonblank supplied token or null");
  if (row.screenshot_record_reference != null && row.screenshot_session_reference == null) throw new Error(path + " cannot resolve a screenshot child without its supplied phone-use parent");
  if (row.screenshot_session_reference == null) return;
  const candidates = sessions.filter(s=>s.screenshot_session_id === row.screenshot_session_reference && s.method_profile_id === row.method_profile_id
    && s.source_work_id === row.source_work_id && s.participant_id === row.participant_id && (row.device_id == null || s.device_id == null || row.device_id === s.device_id)), parent = candidates[0];
  if (candidates.length !== 1 || parent === undefined) throw new Error(path + " must resolve an unambiguous same-owner phone-use screenshot session");
  if (row.screenshot_record_reference != null && !parent.screenshots.some(s=>s.screenshot_record_id === row.screenshot_record_reference)) throw new Error(path + " screenshot does not belong to its supplied parent");
