const tappingSessionWork = "doi:10.2139/ssrn.4768783";
const regretSessionWork = "doi:10.1145/3706598.3713724";
const unlockingSessionWork = "doi:10.1145/2858036.2858267";

function nestedSessionDefinitionMatches(setting: MethodSettingAssertion | undefined, content: unknown, work: unknown): boolean {
  const spec = nestedSessionDefinitions[String(work)]?.[String(setting?.method_parameter_key)];
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  return !!spec && !!setting && setting.source_work_id === work && setting.method_setting_role === spec.role
    && setting.method_target_layer === spec.target && sourceDefinitionTupleMatches(content, spec.role, spec.target)
    && canonicalJson(body) === canonicalJson(spec.body);
}

function requireNestedSessionDefinition(row: Record<string, unknown>, profiles: StudyMethodProfile[], key: string, path: string): MethodSettingAssertion {
  const owner = profiles.find(p => p.method_profile_id === row.method_profile_id && p.source_work_id === row.source_work_id);
  const matches = owner?.method_settings.filter(s => s.method_parameter_key === key) ?? [], match = matches[0];
  if (matches.length !== 1 || match === undefined || !nestedSessionDefinitionMatches(match, JSON.parse(String(match.method_value_json)), row.source_work_id)) {
    throw new Error(path + " has no unique compatible nested-session definition within profile/source");
  }
  return match;
}


function validateNestedSessionChildOwner(row: Record<string, unknown>, child: Record<string, unknown>,
  profiles: StudyMethodProfile[], key: string, referenceField: string, path: string): void {
  const setting = requireNestedSessionDefinition(row, profiles, key, path);
  if (child[referenceField] !== setting.method_setting_id) throw new Error(path + " has no compatible local nested-session evidence definition");
  const spec = requireDefined(requireDefined(nestedSessionDefinitions[String(row.source_work_id)], TABLE_ENTRY)[key], TABLE_ENTRY);
  validateProfileRecordOwner({ ...row, method_setting_reference: setting.method_setting_id, source_locators: child.source_locators },
    path, profiles, spec.role, spec.target);
}

function matchesNestedSessionTaskDefinition(setting: MethodSettingAssertion, content: unknown, kind: DisclosedTaskDefinitionKind, work: string): boolean | undefined {
  const key = String(setting.method_parameter_key);
  const response = work === unlockingSessionWork ? ["survey.instrument"] : work === regretSessionWork ? ["interview.prompts", "recruitment.screening"] : [];
  const criterion = work === unlockingSessionWork
    ? ["fsm.key_entry_begin", "fsm.preparation_interval", "fsm.code_outcomes", "fsm.lockout", "fsm.dismissal_outcomes", "fsm.abort_retry", "fsm.slide_abort", "rq4.successful_unlock_analysis", "rq6.error_frequency", "rq7.error_recovery", "rq8.error_sequences", "rq9.critical_errors", "rq9.prevented_access_upper_bound"] : [];
  if (![...response, ...criterion].includes(key)) return undefined;
  return nestedSessionDefinitionMatches(setting, content, work)
    && (kind === "response" ? response.includes(key) : kind === "criterion" && criterion.includes(key));
}

function validateNestedTaskResponse(response: Record<string, unknown>, owner: StudyMethodProfile, path: string): void {
  if (owner.source_work_id !== unlockingSessionWork) return;
  const setting = owner.method_settings.find(s => s.method_setting_id === response.questionnaire_setting_reference);
  if (setting?.method_parameter_key !== "survey.instrument") return;
  const instrument = requireDefined(requireDefined(nestedSessionDefinitions[unlockingSessionWork], FIXED_KEY)["survey.instrument"], FIXED_KEY).body as {
    code_based_printed_statement_labels: string[]; no_code_printed_statement_labels: string[];
  };
  const property = response.observed_property;
  if (![...instrument.code_based_printed_statement_labels, ...instrument.no_code_printed_statement_labels, "demographics", "happy situations", "annoying situations", "struggle situations"].includes(String(property))) {
    throw new Error(path + " has no disclosed exit-survey statement label or topic");
  }
  if (typeof response.response_value_json === "string" && [...instrument.code_based_printed_statement_labels, ...instrument.no_code_printed_statement_labels].includes(String(property))) {
    const value: unknown = JSON.parse(response.response_value_json);
    if (typeof value === "number" && (!Number.isInteger(value) || value < 1 || value > 7)) throw new Error(path + " contradicts the printed seven-position agreement scale");
    if (value !== null && typeof value !== "number" && typeof value !== "string") throw new Error(path + " must retain an independent supplied ordinal/text answer or JSON null");
  }
}

type NestedSessionChildKind = "sample" | "screenshots" | "task";
function validateNestedSessionReferences(child: Record<string, unknown>, kind: NestedSessionChildKind,
  sessions: DeviceUseSessionRecord[], profiles: StudyMethodProfile[], path: string): void {
  const hasParent = Object.hasOwn(child, "device_use_session_reference"), hasAction = Object.hasOwn(child, "session_action_reference");
  if (!hasParent && !hasAction) return;
  const work = child.source_work_id;
  const valid = kind === "sample" && work === tappingSessionWork || kind === "screenshots" && work === regretSessionWork || kind === "task" && work === unlockingSessionWork;
  if (!valid) throw new Error(path + " has no disclosed cross-carrier session relationship");
  for (const field of ["device_use_session_reference", "session_action_reference"]) {
    if (child[field] != null && (typeof child[field] !== "string" || !String(child[field]).trim())) throw new Error(path + "." + field + " must be a nonblank supplied ID or null");
  }
  if (child.session_action_reference != null && child.device_use_session_reference == null) throw new Error(path + " cannot reference a session action without its supplied parent session");
  if (child.device_use_session_reference == null) return;
  const candidates = sessions.filter(s => s.device_use_session_id === child.device_use_session_reference
    && s.method_profile_id === child.method_profile_id && s.source_work_id === work && s.participant_id === child.participant_id
    && (s.device_id == null || child.device_id == null || s.device_id === child.device_id)), parent = candidates[0];
  if (candidates.length !== 1 || parent === undefined) throw new Error(path + " must resolve one unambiguous parent within profile/source/participant/compatible known device");
  const key = work === tappingSessionWork ? "phone_session.boundary" : work === regretSessionWork ? "screen_session.definition" : "fsm.session_boundary";
  const constructor = requireNestedSessionDefinition(parent, profiles, key, path);
  if (parent.method_setting_reference !== constructor.method_setting_id) throw new Error(path + " references a different disclosed constructor");
  if (child.session_action_reference == null) return;
  const action = parent.session_actions?.find(a => a.task_action_id === child.session_action_reference);
  if (!action) throw new Error(path + " has no action inside its supplied parent session");
  const roles = action.assigned_role_labels ?? [];
  const expected = kind === "task" ? "unlock attempt" : "foreground app period";
  if (roles.some(role => ["unlock attempt", "foreground app period"].includes(role)) && !roles.includes(expected)) throw new Error(path + " contradicts the supplied child-period role");
  const app = kind === "sample" ? child.observed_entity_kind === "application" ? child.observed_entity_token : undefined : child.app_identifier;
  if (app != null && action.app_identifier != null && app !== action.app_identifier) throw new Error(path + " contradicts a known parent app-period identity");
  if (kind !== "task") requireNestedSessionDefinition(parent, profiles, "app_session." + (work === tappingSessionWork ? "boundary" : "definition"), path);
}

function validateNestedScreenshotSession(row: Record<string, unknown>, profiles: StudyMethodProfile[], path: string): void {
  if (row.source_work_id === timeKillingWork) return validateTimeKillingScreenshotSession(row, profiles, path);
  const fields = ["method_setting_reference", "app_identifier"];
  if (fields.some(field => Object.hasOwn(row, field)) && row.source_work_id !== regretSessionWork) throw new Error(path + " cannot transplant app-session screenshot ownership to another source");
  if (row.source_work_id !== regretSessionWork) return;
  const setting = requireNestedSessionDefinition(row, profiles, "app_session.definition", path);
  if (row.method_setting_reference !== setting.method_setting_id) throw new Error(path + " requires its own supplied app-session definition");
  if (row.app_identifier != null && (typeof row.app_identifier !== "string" || !row.app_identifier.trim())) throw new Error(path + ".app_identifier must be a supplied nonblank app token or null");
}

function validateNestedScreenshotAnnotation(annotation: Record<string, unknown>, row: Record<string, unknown>,
  images: Map<string, SessionScreenshotRecord>, profiles: StudyMethodProfile[], path: string): void {
  if (row.source_work_id === timeKillingWork) return validateTimeKillingScreenshotAnnotation(annotation, row, profiles, path);
  const fields = ["method_setting_reference", "assessor_id", "support_screenshot_references"];
  if (!fields.some(field => Object.hasOwn(annotation, field))) return;
  if (row.source_work_id !== regretSessionWork) throw new Error(path + " has no disclosed screenshot-analysis definition");
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const setting = owner.method_settings.find(s => s.method_setting_id === annotation.method_setting_reference);
  const key = setting?.method_parameter_key;
  if (!["gpt.step1_output", "gpt.output", "activity.categories", "validation.consensus"].includes(String(key))
    || !nestedSessionDefinitionMatches(setting, JSON.parse(String(setting?.method_value_json)), row.source_work_id)) throw new Error(path + " has no compatible local screenshot-analysis definition");
  requireNestedSessionDefinition(row, profiles, "activity.categories", path);
  if (annotation.assessor_id != null && (typeof annotation.assessor_id !== "string" || !annotation.assessor_id.trim())) throw new Error(path + ".assessor_id must be a supplied nonblank token or null");
  if (annotation.first_screenshot_reference != null && annotation.last_screenshot_reference != null
    && annotation.first_screenshot_reference !== annotation.last_screenshot_reference) throw new Error(path + " assigns a single-image analysis to a whole range");
  const current = images.get(String(annotation.first_screenshot_reference ?? annotation.last_screenshot_reference));
  if (annotation.support_screenshot_references != null) {
    if (!Array.isArray(annotation.support_screenshot_references)) throw new Error(path + ".support_screenshot_references must be an array or null");
    const refs = stringArray(annotation, "support_screenshot_references", path);
    const cap = key === "gpt.step1_output" ? 1 : 4;
    if (refs.length > cap || new Set(refs).size !== refs.length || refs.some(ref => !ref.trim() || !images.has(ref) || ref === current?.screenshot_record_id)) throw new Error(path + " has duplicate/foreign/self/excess prior screenshot supports");
    for (const ref of refs) {
      const support = requireDefined(images.get(ref), "a reference checked with images.has() resolves");
      const currentPosition = current?.screenshot_sequence_position, supportPosition = support.screenshot_sequence_position;
      if (currentPosition != null && supportPosition != null) {
        if (supportPosition >= currentPosition) throw new Error(path + " contradicts known prior screenshot positions");
        const intervening = [...images.values()].filter(image => image.screenshot_sequence_position != null
          && image.screenshot_sequence_position > supportPosition && image.screenshot_sequence_position < currentPosition).length;
        if (intervening >= cap) throw new Error(path + " contradicts the known prior screenshot context limit");
      }
    }
  }
  requireNestedSessionDefinition(row, profiles, key === "gpt.step1_output" ? "gpt.step1_input" : key === "gpt.output" ? "gpt.step2_context" : "validation.sample", path);
  if (annotation.range_label_values_json == null) return;
  const labels = JSON.parse(annotation.range_label_values_json as string) as Record<string, unknown> | null;
  if (labels === null) return;
  const allowed = key === "gpt.step1_output" ? ["description"] : key === "gpt.output" ? ["activity category", "justification"] : ["activity category"];
  rejectUnknown(labels, new Set(allowed), path + ".range_label_values_json");
  for (const [field, value] of Object.entries(labels)) {
    if (value !== null && typeof value !== "string") throw new Error(path + " must retain supplied textual description/category/justification or null");
    if (field === "activity category" && value !== null) {
      const categories = (requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)["activity.categories"], FIXED_KEY).body as { normalized_labels: string[] }).normalized_labels;
      if (!categories.includes(String(value))) throw new Error(path + " has no disclosed activity category");
    }
  }
  // Explicit local supports preserve supplied context, not recovered previousness,
  // image completeness, GPT execution, coder agreement or propagated labels.
}

