function nestedSampleSpec(owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined) {
  return nestedSampleSpecs[String(owner?.source_work_id)]?.[String(setting?.method_parameter_key)];
}
function nestedSessionObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const spec = nestedSampleSpec(owner, setting);
  if (!spec) return undefined;
  const definition = requireDefined(requireDefined(nestedSessionDefinitions[String(owner?.source_work_id)], TABLE_ENTRY)[String(setting?.method_parameter_key)], TABLE_ENTRY);
  const body = definitionFor(definition.role, definition.target);
  const content: unknown = JSON.parse(String(setting?.method_value_json));
  return { compatible: setting?.source_work_id === row.source_work_id && nestedSessionDefinitionMatches(setting, content, owner?.source_work_id)
    && canonicalJson(body) === canonicalJson(definition.body), entity: spec.entity, properties: Object.keys(spec.units),
    unit: undefined, unitsByProperty: Object.fromEntries(Object.entries(spec.units).map(([key, value]) => [key, value ?? undefined])),
    screenTimeQualifiers: undefined, categoricalValuesByProperty: undefined, percentageProperty: undefined,
    booleanProperty: undefined, numericIntegerRanges: undefined, sourceQualifiers: false };
}
function validateNestedSampleValue(value: unknown, property: string, row: Record<string, unknown>, owner: StudyMethodProfile | undefined,
  setting: MethodSettingAssertion | undefined, path: string) {
  const spec = nestedSampleSpec(owner, setting);
  if (!spec || !owner || value == null) return;
  const states = spec.states?.[property];
  if (states && (typeof value !== "string" || !states.includes(value))) throw new Error(path + " has no disclosed event/state designation");
  if (spec.booleans?.includes(property) && typeof value !== "boolean") throw new Error(path + " requires an independent supplied boolean, not a recovered raw code");
  if (spec.vectors?.includes(property)) {
    if (typeof value === "string") return; // An unrecovered lexical vector encoding remains opaque.
    if (!Array.isArray(value) || value.some(item => item !== null && (typeof item !== "number" || !Number.isFinite(item) || item < 0
      || property === "one-second tap counts" && !Number.isInteger(item)
      || property === "normalized timestamps" && item > 1))) throw new Error(path + " has an invalid independently supplied count/normalized vector");
    return;
  }
  if (typeof value === "number" && (!Number.isFinite(value) || value < 0
    || ["entered-code length", "number of prior attempts"].includes(property) && !Number.isInteger(value))) {
    // Source category -1 is deliberately distinct from unknown field/null.
    if (!(property === "Google Play category" && value === -1)) throw new Error(path + " has an invalid supplied nonnegative count/quantity");
  }
  if (typeof value !== "string" && typeof value !== "number" && !spec.booleans?.includes(property)) throw new Error(path + " requires an independently supplied scalar or JSON null");
  if (row.source_work_id === tappingSessionWork && property === "tap event") {
    requireNestedSessionDefinition(row, [owner], "schema.tap_timestamp_resolution", path);
    requireNestedSessionDefinition(row, [owner], "schema.touch_coordinates", path);
  }
}

function nestedSessionBoundaries(row: Record<string, unknown>, setting: MethodSettingAssertion, definition: unknown,
  profiles: StudyMethodProfile[], path: string): { starts: string[]; ends: string[] } | undefined {
  const key = String(setting.method_parameter_key), work = row.source_work_id;
  const root = work === tappingSessionWork ? "phone_session.boundary" : work === regretSessionWork ? "screen_session.definition"
    : work === unlockingSessionWork ? "fsm.session_boundary" : undefined;
  if (!root || key !== root) return undefined;
  const exact = requireNestedSessionDefinition(row, profiles, root, path);
  if (exact.method_setting_id !== setting.method_setting_id || canonicalJson(definition) !== canonicalJson(requireDefined(requireDefined(nestedSessionDefinitions[String(work)], TABLE_ENTRY)[root], TABLE_ENTRY).body)) throw new Error(path + " has no compatible exact session constructor");
  if (work === tappingSessionWork) {
    for (const companion of ["phone_session.identifier", "phone_session.screen_sleep_termination", "app_session.boundary", "app_session.boundary_timestamp_basis"]) requireNestedSessionDefinition(row, profiles, companion, path);
    return { starts: ["participant unlocks screen"], ends: ["screen locked again"] };
  }
  return { starts: ["SCREEN ON"], ends: ["SCREEN OFF"] };
}

function validateNestedSessionResponse(row: Record<string, unknown>, response: Record<string, unknown>, profiles: StudyMethodProfile[], path: string): boolean {
  if (row.source_work_id !== regretSessionWork) return false;
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const setting = owner.method_settings.find(s => s.method_setting_id === response.questionnaire_setting_reference);
  const key = String(setting?.method_parameter_key);
  if (!["intention.categories", "daily.regret_scale"].includes(key)) return false;
  validateNestedSessionChildOwner(row, response, profiles, key, "questionnaire_setting_reference", path);
  const item = key === "intention.categories" ? "intention.prompt" : "daily.regret_item";
  requireNestedSessionDefinition(row, profiles, item, path);
  if (response.questionnaire_item_label != null && response.questionnaire_item_label !== requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)[item], FIXED_KEY).body) throw new Error(path + " contradicts the printed question");
  if (response.support_task_action_references != null) {
    if (!Array.isArray(response.support_task_action_references)) throw new Error(path + ".support_task_action_references must be an array or null");
    const refs = stringArray(response, "support_task_action_references", path);
    const actions = recordsOf(row.session_actions);
    if (refs.length > 1 || new Set(refs).size !== refs.length || refs.some(ref => !ref.trim() || !actions.some(a => a.task_action_id === ref))) throw new Error(path + " must retain at most one explicitly supplied local app-period support");
    const action = actions.find(a => a.task_action_id === refs[0]);
    if (action && Array.isArray(action.assigned_role_labels)
      && action.assigned_role_labels.includes("unlock attempt")) throw new Error(path + " contradicts known app-period ownership");
  }
  if (response.response_value_json == null) return true;
  if (typeof response.response_value_json !== "string") throw new Error(path + " must retain lexical JSON or field null");
  const value: unknown = JSON.parse(response.response_value_json);
  if (key === "intention.categories") {
    const options = (requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)["intention.categories"], FIXED_KEY).body as { normalized_labels: string[] }).normalized_labels;
    if (value !== null && (typeof value !== "string" || !options.includes(value))) throw new Error(path + " has no disclosed intended-use designation");
  } else if (value !== null && (typeof value !== "number" && typeof value !== "string" || typeof value === "number" && (!Number.isInteger(value) || value < 1 || value > 7))) throw new Error(path + " contradicts the independent seven-position regret scale");
  return true;
}

function validateNestedTaskAssessment(assessment: Record<string, unknown>, owner: StudyMethodProfile, path: string) {
  if (owner.source_work_id !== unlockingSessionWork || assessment.assessment_value_json == null) return;
  const key = owner.method_settings.find(s => s.method_setting_id === assessment.criterion_setting_reference)?.method_parameter_key;
  const choices = key === "fsm.code_outcomes" ? ["correct", "incorrect", "too short"] : key === "fsm.dismissal_outcomes"
    ? requireDefined(requireDefined(nestedSessionDefinitions[unlockingSessionWork], FIXED_KEY)["fsm.dismissal_outcomes"], FIXED_KEY).body as string[] : undefined;
  if (!choices) return;
  const value: unknown = JSON.parse(assessment.assessment_value_json as string);
  if (value !== null && (typeof value !== "string" || !choices.includes(value))) throw new Error(path + " has no disclosed independently supplied unlock outcome");
}

function validateNestedSessionQuantity(row: Record<string, unknown>, quantity: Record<string, unknown>,
  setting: MethodSettingAssertion | undefined, profiles: StudyMethodProfile[], path: string): boolean | undefined {
  const work = row.source_work_id, key = String(setting?.method_parameter_key);
  const tapping = work === tappingSessionWork && ["schema.phone_session_fields", "phone_session.screen_sleep_termination", "analysis.taps_per_second", "clustering.input_sequence", "clustering.timestamp_normalization", "clustering.length_normalization"].includes(key);
  const regret = work === regretSessionWork && ["session_corpus.fields", "predictor.fixed_effects"].includes(key);
  if (!tapping && !regret) return undefined;
  requireNestedSessionDefinition(row, profiles, key, path);
  const property = quantity.observed_property;
  const sleepReset = key === "phone_session.screen_sleep_termination";
  const session = key === "schema.phone_session_fields" || sleepReset;
  const expected = sleepReset ? ["generated session ID"] : session ? ["total tap count", "apps used"] : key === "analysis.taps_per_second" ? ["taps per second"]
    : key === "clustering.input_sequence" ? ["one-second tap counts"] : key === "clustering.timestamp_normalization" ? ["normalized timestamps"]
    : key === "clustering.length_normalization" ? ["length-normalized tap counts"] : key === "session_corpus.fields" ? ["app-session duration"]
    : (requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)["activity.categories"], FIXED_KEY).body as { normalized_labels: string[] }).normalized_labels.map(label => "ratio of " + label);
  if (quantity.quantity_scope !== (session ? "session" : "app") || !expected.includes(String(property)) || quantity.quantity_qualifier != null) throw new Error(path + " has an incompatible nested-session quantity scope/property");
  const unit = key === "analysis.taps_per_second" ? "taps/second" : property === "total tap count" ? "taps" : undefined;
  if (quantity.evidence_unit != null && quantity.evidence_unit !== unit) throw new Error(path + " invents an undisclosed quantity unit");
  const supports = quantity.support_task_action_references;
  if (sleepReset && Array.isArray(supports)) {
    const actions = recordsOf(row.session_actions).filter(action => supports.includes(action.task_action_id));
    if (actions.some(action => ["participant unlocks screen", "screen locked again"].includes(String(action.action_label))
      || (Array.isArray(action.assigned_role_labels) ? action.assigned_role_labels : []).some((role: unknown) => typeof role === "string" && ["foreground app period", "unlock attempt", "screen lock"].includes(role)))) throw new Error(path + " contradicts the supplied screen-sleep ID-generation support");
  }
  if (!session && Array.isArray(supports) && supports.length > 1) throw new Error(path + " cannot merge independently identified foreground visits");
  if (quantity.evidence_value_json == null) return true;
  const value: unknown = JSON.parse(quantity.evidence_value_json as string);
  if (sleepReset) {
    // This supplied ID is not an inferred successor, lock endpoint or numeric duration.
    // Its original serialization is unreported; preserve a scalar ID without conversion.
    if (value !== null && (typeof value === "string" ? !value.trim() : typeof value !== "number" || !Number.isFinite(value))) throw new Error(path + " must retain an independent supplied scalar session ID or JSON null");
    return true;
  }
  if (value === null || typeof value === "string") return true;
  if (property === "apps used") {
    if (!Array.isArray(value) || value.some(v => v !== null && typeof v !== "string")) throw new Error(path + " requires independently supplied app identifiers or unknown members");
    return true;
  }
  if (key.startsWith("clustering.")) {
    if (!Array.isArray(value) || value.some(v => v !== null && (typeof v !== "number" || !Number.isFinite(v) || v < 0
      || key === "clustering.input_sequence" && !Number.isInteger(v)
      || key === "clustering.timestamp_normalization" && v > 1))) throw new Error(path + " has an invalid independently supplied sequence");
    return true;
  }
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0 || property === "total tap count" && !Number.isInteger(value)
    || key === "predictor.fixed_effects" && value > 1) throw new Error(path + " has an invalid independent supplied quantity");
  return true;
}

function validateNestedSessionLabel(row: Record<string, unknown>, label: Record<string, unknown>,
  setting: MethodSettingAssertion | undefined, profiles: StudyMethodProfile[], path: string): boolean {
  const key = String(setting?.method_parameter_key), work = row.source_work_id;
  const active = work === tappingSessionWork && key === "clustering.semantic_labels";
  const prevalent = work === regretSessionWork && key === "rq2.session_activity";
  const deviation = work === regretSessionWork && key === "deviation.groups";
  if (!active && !prevalent && !deviation) return false;
  validateNestedSessionChildOwner(row, label, profiles, key, "label_setting_reference", path);
  if (label.label_value_json != null && typeof label.label_value_json !== "string") throw new Error(path + ".label_value_json must be lexical JSON or null");
  if (label.support_task_action_references != null && Array.isArray(label.support_task_action_references)
    && label.support_task_action_references.length > 1) throw new Error(path + " cannot merge distinct supplied app-period label owners");
  const property = active ? "app-session cluster label" : prevalent ? "most prevalent app-session activity" : "supplied intention/activity deviation group";
  if (label.observed_property !== property) throw new Error(path + " has an incompatible app-session label designation");
  if (label.label_value_json == null) return true;
  const value: unknown = JSON.parse(String(label.label_value_json));
  const options = active ? ["active", "passive"] : prevalent
    ? (requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)["activity.categories"], FIXED_KEY).body as { normalized_labels: string[] }).normalized_labels
    : (requireDefined(requireDefined(nestedSessionDefinitions[regretSessionWork], FIXED_KEY)["deviation.groups"], FIXED_KEY).body as {label:string}[]).map(group => group.label);
  if (value !== null && (typeof value !== "string" || !options.includes(value))) throw new Error(path + " has no disclosed independent app-session label");
  return true;
}

function deviceSessionQuantityTuple(row: Record<string, unknown>, setting: MethodSettingAssertion) {
  if (row.source_work_id === timeKillingWork && setting.method_parameter_key === "clustering.session_features") return requireDefined(timeKillingDefinitions["clustering.session_features"], FIXED_KEY);
  const nested = nestedSessionDefinitions[String(row.source_work_id)]?.[String(setting.method_parameter_key)];
  if (nested) return { role: nested.role, target: nested.target, sourceRole: nested.role, sourceTarget: nested.target };
  const appPeriod = appPeriodDefinitionSpec(row, setting);
  if (appPeriod) return appPeriod;
  const hammer = row.source_work_id === "doi:10.1145/2634317.2634325" ? hammerDefinitions[String(setting.method_parameter_key)] : undefined;
  return { role: hammer?.role ?? "feature_engineering", target: hammer?.target ?? "derived_feature",
    sourceTarget: hammer?.sourceTarget, sourceRole: hammer?.sourceRole };
}

function parseScreenshotSessions(value: unknown, profiles: StudyMethodProfile[], artifacts: ArtifactRef[]): ScreenshotSessionRecord[] {
  if (!Array.isArray(value)) throw new Error("method_profile_library.screenshot_sessions must be an array");
  const ids = new Set<string>();
  const catalog = new Set(artifacts.map((artifact) => artifact.artifact_id));
  const nonblank = (row: Record<string, unknown>, field: string, path: string) => {
    const text = requiredString(row, field, path);
    if (!text.trim()) throw new Error(`${path}.${field} must be nonblank`);
    return text;
  };
  const locators = (row: Record<string, unknown>, path: string) => {
    if (!Array.isArray(row.source_locators) || !stringArray(row, "source_locators", path).length
      || stringArray(row, "source_locators", path).some((s) => !s.trim())) throw new Error(`${path}.source_locators must be a non-empty string array`);
  };
  return value.map((row, index) => {
    const path = `method_profile_library.screenshot_sessions[${index}]`;
    if (!isRecord(row)) throw new Error(`${path} must be an object`);
    rejectUnknown(row, new Set(["screenshot_session_id", "method_profile_id", "source_work_id", "participant_id", "device_id", "session_record_origin", "method_setting_reference", "app_identifier", "device_use_session_reference", "session_action_reference", "denotes_interval", "screenshots", "screenshot_range_annotations", "source_locators"]), path);
    const profileId = nonblank(row, "method_profile_id", path);
    const workId = nonblank(row, "source_work_id", path);
    if (!profiles.some((p) => p.method_profile_id === profileId && p.source_work_id === workId)) throw new Error(`${path} has no matching profile/source owner`);
    if (row.device_id != null) nonblank(row, "device_id", path);
    const id = canonicalJson([profileId, nonblank(row, "participant_id", path), row.device_id ?? null, nonblank(row, "screenshot_session_id", path)]);
    if (ids.has(id)) throw new Error(`${path}.screenshot_session_id is duplicated within profile/participant/device`);
    ids.add(id);
    if (typeof row.session_record_origin !== "string" || !normalizedRecordOrigins.includes(row.session_record_origin)) throw new Error(`${path}.session_record_origin is unknown`);
    locators(row, path);
    if (row.denotes_interval != null) parseUsageInterval(row.denotes_interval, `${path}.denotes_interval`);
    validateNestedScreenshotSession(row, profiles, path);
    if (!Array.isArray(row.screenshots)) throw new Error(`${path}.screenshots must be an array`);
    const screenshots = new Map<string, SessionScreenshotRecord>();
    const positions = new Set<number>();
    for (const [i, screenshot] of row.screenshots.entries()) {
      const imagePath = `${path}.screenshots[${i}]`;
      if (!isRecord(screenshot)) throw new Error(`${imagePath} must be an object`);
      rejectUnknown(screenshot, new Set(["screenshot_record_id", "screenshot_sequence_position", "screenshot_instant", "screenshot_artifact_id", "source_locators"]), imagePath);
      const imageId = nonblank(screenshot, "screenshot_record_id", imagePath);
      if (screenshots.has(imageId)) throw new Error(`${imagePath}.screenshot_record_id is duplicated within session`);
      screenshots.set(imageId, screenshot as SessionScreenshotRecord);
      if (screenshot.screenshot_sequence_position != null) {
        const position = screenshot.screenshot_sequence_position;
        if (!Number.isSafeInteger(position) || Number(position) < 0 || positions.has(Number(position))) throw new Error(`${imagePath}.screenshot_sequence_position must be a unique non-negative integer within session`);
        positions.add(Number(position));
      }
      if (screenshot.screenshot_instant != null && typeof screenshot.screenshot_instant !== "string") throw new Error(`${imagePath}.screenshot_instant must be a string or null`);
      if (screenshot.screenshot_artifact_id != null && !catalog.has(nonblank(screenshot, "screenshot_artifact_id", imagePath))) throw new Error(`${imagePath}.screenshot_artifact_id has no referenced artifact`);
      locators(screenshot, imagePath);
    }
    if (row.screenshot_range_annotations != null) {
      if (!Array.isArray(row.screenshot_range_annotations)) throw new Error(`${path}.screenshot_range_annotations must be an array or null`);
      const annotationIds = new Set<string>();
      for (const [i, annotation] of row.screenshot_range_annotations.entries()) {
        const annotationPath = `${path}.screenshot_range_annotations[${i}]`;
        if (!isRecord(annotation)) throw new Error(`${annotationPath} must be an object`);
        rejectUnknown(annotation, new Set(["range_annotation_id", "method_setting_reference", "assessor_id", "support_screenshot_references", "first_screenshot_reference", "last_screenshot_reference", "range_label_values_json", "source_locators"]), annotationPath);
        const annotationId = nonblank(annotation, "range_annotation_id", annotationPath);
        if (annotationIds.has(annotationId)) throw new Error(`${annotationPath}.range_annotation_id is duplicated within session`);
        annotationIds.add(annotationId);
        for (const field of ["first_screenshot_reference", "last_screenshot_reference"]) {
          if (annotation[field] != null && !screenshots.has(nonblank(annotation, field, annotationPath))) throw new Error(`${annotationPath}.${field} has no screenshot within session`);
        }
        const first = screenshots.get(annotation.first_screenshot_reference as string)?.screenshot_sequence_position;
        const last = screenshots.get(annotation.last_screenshot_reference as string)?.screenshot_sequence_position;
        if (first != null && last != null && first > last) throw new Error(`${annotationPath} has reversed supplied screenshot positions`);
        if (annotation.range_label_values_json != null) {
          if (typeof annotation.range_label_values_json !== "string") throw new Error(`${annotationPath}.range_label_values_json must be a string or null`);
          let labels: unknown;
          try { labels = JSON.parse(annotation.range_label_values_json); }
          catch { throw new Error(`${annotationPath}.range_label_values_json must contain valid JSON`); }
          if (labels !== null && !isRecord(labels)) throw new Error(`${annotationPath}.range_label_values_json must contain an object or JSON null`);
        }
        validateNestedScreenshotAnnotation(annotation, row, screenshots, profiles, annotationPath);
        locators(annotation, annotationPath);
      }
    }
    // Supplied order/positions, partial labels and unknown endpoints stay untouched.
    // Endpoints never expand into inclusive membership or label the whole session.
    return row as ScreenshotSessionRecord;
  });
}

// Day-named transport keys remain compatible; the explicit token selects period ownership.
export type CrossPeriodAggregateReference = Record<string, unknown> & {
  day_observation_id: string;
  referenced_day_token?: string;
  referenced_hour_token?: string;
  referenced_night_token?: string;
  relationship_label: string;
  source_locators: string[];
};
export type ParticipantDayObservationRecord = Record<string, unknown> & {
  day_observation_id: string;
  method_profile_id: string;
  source_work_id: string;
  participant_id: string;
  device_id?: string | null;
  referenced_day_token?: string;
  referenced_hour_token?: string;
  referenced_night_token?: string;
  referenced_run_token?: string;
  method_setting_reference?: string | null;
  day_record_origin: "analyst_constructed_example" | "supplied_normalized_records";
  day_observation_kind: (typeof PARTICIPANT_DAY_OBSERVATION_KIND_VALUES)[number];
  observed_property: string;
  observation_category?: string | null;
  app_package_name?: string | null;
  day_observation_value_json?: string | null;
  evidence_unit?: string | null;
  questionnaire_item_label?: string | null;
  aggregate_observation_references?: string[] | null;
  cross_period_aggregate_references?: CrossPeriodAggregateReference[] | null;
  source_locators: string[];
};

function parseParticipantDayObservations(value: unknown, profiles: StudyMethodProfile[]): ParticipantDayObservationRecord[] {
  if (!Array.isArray(value)) throw new Error("method_profile_library.participant_day_observations must be an array");
  const periodFields = ["referenced_day_token", "referenced_hour_token", "referenced_night_token"] as const;
  const ownerFields = [...periodFields, "referenced_run_token"] as const;
  const periodField = (row: Record<string, unknown>) => requireDefined(ownerFields.find(field => Object.hasOwn(row, field)), "validatePeriod() accepted exactly one period field on this row");
  const validatePeriod = (row: Record<string, unknown>, path: string) => {
    if (ownerFields.filter(field => Object.hasOwn(row, field)).length !== 1
      || !requiredString(row, periodField(row), path).trim()) throw new Error(`${path} must identify exactly one referenced day, hour or night, or run with a nonblank token`);
  };
  const scope = (row: Record<string, unknown>, id: unknown) => canonicalJson([row.method_profile_id, row.participant_id, row.device_id ?? null, periodField(row), row[periodField(row)], id]);
  const byId = new Map<string, ParticipantDayObservationRecord>();
  const observations = value.map((row, index) => {
    const path = `method_profile_library.participant_day_observations[${index}]`;
    if (!isRecord(row)) throw new Error(`${path} must be an object`);
    rejectUnknown(row, new Set(["day_observation_id", "method_profile_id", "source_work_id", "participant_id", "device_id", ...ownerFields, "method_setting_reference", "day_record_origin", "day_observation_kind", "observed_property", "observation_category", "app_package_name", "day_observation_value_json", "evidence_unit", "questionnaire_item_label", "aggregate_observation_references", "cross_period_aggregate_references", "source_locators"]), path);
    const profileId = requiredString(row, "method_profile_id", path);
    const owner = profiles.find(p => p.method_profile_id === profileId);
    if (!owner || owner.source_work_id !== requiredString(row, "source_work_id", path)) throw new Error(`${path} has no matching profile/source owner`);
    if (row.device_id != null && (typeof row.device_id !== "string" || !row.device_id.trim())) throw new Error(`${path}.device_id must be nonblank or null`);
    validatePeriod(row, path);
    for (const field of ["day_observation_id", "participant_id", periodField(row), "observed_property"]) {
      if (!requiredString(row, field, path).trim()) throw new Error(`${path}.${field} must be non-blank`);
    }
    const key = scope(row, row.day_observation_id);
    if (byId.has(key)) throw new Error(`${path}.day_observation_id is duplicated within profile/participant/referenced period`);
    if (typeof row.day_record_origin !== "string" || !normalizedRecordOrigins.includes(row.day_record_origin)) throw new Error(`${path}.day_record_origin is unknown`);
    if (typeof row.day_observation_kind !== "string" || !(PARTICIPANT_DAY_OBSERVATION_KIND_VALUES as readonly string[]).includes(row.day_observation_kind)) throw new Error(`${path}.day_observation_kind is unknown`);
    if (row.app_package_name != null && (typeof row.app_package_name !== "string" || !row.app_package_name.trim())) throw new Error(`${path}.app_package_name must be nonblank or null`);
    for (const field of ["observation_category", "day_observation_value_json", "evidence_unit", "questionnaire_item_label"]) {
      if (row[field] != null && typeof row[field] !== "string") throw new Error(`${path}.${field} must be a string or null`);
    }
    let observationValue: unknown;
    if (row.day_observation_value_json != null) {
      try { observationValue = JSON.parse(row.day_observation_value_json as string); }
      catch { throw new Error(`${path}.day_observation_value_json must contain valid JSON`); }
    }
    const isRun = periodField(row) === "referenced_run_token";
    if (isRun !== (row.day_observation_kind === "modality_availability")) throw new Error(`${path} has an incompatible participant observation kind/owner`);
    if (!isRun && Object.hasOwn(row, "method_setting_reference")) throw new Error(`${path}.method_setting_reference is run-availability-only`);
    if (isRun) {
      const setting = owner.method_settings.find(s => s.method_setting_id === requiredString(row, "method_setting_reference", path));
      const content: unknown = setting && JSON.parse(String(setting.method_value_json));
      const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
      if (owner.source_work_id !== "doi:10.1016/j.smhl.2020.100118" || setting?.method_parameter_key !== "modality.missingness"
        || setting.method_setting_role !== "quality_control" || setting.method_target_layer !== "study_window"
        || !sourceDefinitionTupleMatches(content, "quality_control", "participant_modality")
        || body !== "each participant may supply any subset; modality-specific models use only participants who contributed that modality") throw new Error(`${path} has no compatible modality-availability definition`);
      if (!["contacts", "Twitter", "text messages", "GPS", "call logs", "Instagram", "voice"].includes(row.observed_property as string)) throw new Error(`${path}.observed_property has no disclosed modality`);
      if (row.evidence_unit != null) throw new Error(`${path}.evidence_unit must be omitted or null for modality availability`);
      if (row.day_observation_value_json != null && observationValue !== null && observationValue !== "provided" && observationValue !== "unavailable") throw new Error(`${path}.day_observation_value_json must contain a supplied provided/unavailable string or JSON null`);
    }
    if (row.day_observation_kind !== "subjective_response" && ["aggregate_observation_references", "cross_period_aggregate_references", "questionnaire_item_label"].some((field) => Object.hasOwn(row, field))) throw new Error(`${path} has subjective-only fields on a non-subjective observation`);
    if (!Array.isArray(row.source_locators) || !stringArray(row, "source_locators", path).length || stringArray(row, "source_locators", path).some((s) => !s.trim())) throw new Error(`${path}.source_locators must be a non-empty string array`);
    byId.set(key, row as ParticipantDayObservationRecord);
    return row as ParticipantDayObservationRecord;
  });
  for (const row of observations) {
    if (row.cross_period_aggregate_references != null) {
      if (!Array.isArray(row.cross_period_aggregate_references)) throw new Error("cross_period_aggregate_references must be an array or null");
      const seen = new Set<string>();
      for (const reference of row.cross_period_aggregate_references) {
        const path = "cross_period_aggregate_references";
        if (!isRecord(reference)) throw new Error(`${path} member must be an object`);
        rejectUnknown(reference, new Set(["day_observation_id", ...periodFields, "relationship_label", "source_locators"]), path);
        validatePeriod(reference, path);
        for (const field of ["day_observation_id", "relationship_label"]) if (!requiredString(reference, field, path).trim()) throw new Error(`${path}.${field} must be nonblank`);
        if (!Array.isArray(reference.source_locators) || !reference.source_locators.length
          || stringArray(reference, "source_locators", path).some(s => !s.trim())) throw new Error(`${path}.source_locators must be a non-empty string array`);
        const field = periodField(reference);
        const targetKey = scope({ method_profile_id: row.method_profile_id, participant_id: row.participant_id, device_id: row.device_id ?? null, [field]: reference[field] }, reference.day_observation_id);
        const target = byId.get(targetKey);
        if (seen.has(targetKey) || !target || target.source_work_id !== row.source_work_id || target.day_observation_kind !== "objective_aggregate"
          || (field === periodField(row) && reference[field] === row[field])) throw new Error(`${path} requires distinct objective targets in a different supplied period within profile/source/participant`);
        seen.add(targetKey);
      }
    }
    if (row.aggregate_observation_references == null) continue;
    if (!Array.isArray(row.aggregate_observation_references)) throw new Error("aggregate_observation_references must be an array or null");
    const refs = stringArray(row, "aggregate_observation_references", "participant-period observation");
    if (new Set(refs).size !== refs.length || refs.some((id) => byId.get(scope(row, id))?.day_observation_kind !== "objective_aggregate")) throw new Error("aggregate_observation_references has duplicate or missing objective records within profile/participant/referenced period");
  }
  return observations;
}

export type NotificationTitleAnnotationRecord = Record<string, unknown> & {
  title_annotation_id: string;
  method_profile_id: string;
  source_work_id: string;
  participant_id: string;
  annotation_record_origin: "analyst_constructed_example" | "supplied_normalized_records";
  notification_title?: string | null;
  sender_relationship_labels: string[];
  source_locators: string[];
};

function parseNotificationTitleAnnotations(value: unknown, profiles: StudyMethodProfile[]): NotificationTitleAnnotationRecord[] {
  if (!Array.isArray(value)) throw new Error("method_profile_library.notification_title_annotations must be an array");
  const ids = new Set<string>();
  return value.map((record, index) => {
    const path = `method_profile_library.notification_title_annotations[${index}]`;
    if (!isRecord(record)) throw new Error(`${path} must be an object`);
    rejectUnknown(record, new Set(["title_annotation_id", "method_profile_id", "source_work_id", "participant_id", "annotation_record_origin", "notification_title", "sender_relationship_labels", "source_locators"]), path);
    const profile = requiredString(record, "method_profile_id", path);
    if (!profiles.some((p) => p.method_profile_id === profile && p.source_work_id === requiredString(record, "source_work_id", path))) throw new Error(`${path} has no matching profile/source owner`);
    const key = canonicalJson([profile, requiredString(record, "participant_id", path), requiredString(record, "title_annotation_id", path)]);
    if (ids.has(key)) throw new Error(`${path}.title_annotation_id is duplicated within profile/participant`);
    ids.add(key);
    if (typeof record.annotation_record_origin !== "string" || !normalizedRecordOrigins.includes(record.annotation_record_origin)) throw new Error(`${path}.annotation_record_origin is unknown`);
    if (record.notification_title != null && typeof record.notification_title !== "string") throw new Error(`${path}.notification_title must be a string or null`);
    for (const field of ["sender_relationship_labels", "source_locators"]) {
      if (!Array.isArray(record[field])) throw new Error(`${path}.${field} must be an array`);
      const values = stringArray(record, field, path);
      if (!values.length || values.some((s) => !s.trim()) || (field === "sender_relationship_labels" && new Set(values).size !== values.length)) throw new Error(`${path}.${field} must contain non-empty distinct labels or source locators`);
    }
    return record as NotificationTitleAnnotationRecord;
  });
}

