const apnomsIntervalKeys = ["reconstruction.network_session_scope", "reconstruction.battery_interval_definition", "reconstruction.battery_change_interval"];

function apnomsObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined, definitionFor: (role: string, target: string, reference?: unknown) => unknown) {
  let entity: string, properties: string[], unit: string | undefined, compatible: boolean;
  let unitsByProperty: Record<string, string> | undefined, screenTimeQualifiers: Record<string, string[]> | undefined;
  let categoricalValuesByProperty: Record<string, readonly string[]> | undefined, percentageProperty: string | undefined;
  switch (setting?.method_parameter_key) {
      case "reconstruction.time_spent_by_state": case "reconstruction.battery_spent_by_state":
      case "analysis.individual_five_state_time": case "analysis.individual_five_state_battery":
      case "analysis.communication_three_state_time": case "analysis.communication_three_state_battery":
      case "analysis.power_source_time_share": {
        const key = setting.method_parameter_key, summary = key.startsWith("analysis.");
        const definition = definitionFor(summary ? "analysis" : "aggregation", summary ? "outcome" : "derived_feature");
        compatible = matchesApnomsDefinition(row, setting, definition);
        const power = key === "analysis.power_source_time_share", battery = key.includes("battery");
        const property = power ? "power-source time share" : summary ? battery ? "battery-consumption share" : "time share" : battery ? "battery spent" : "time spent";
        entity = "participant"; properties = [property]; unit = summary ? "percent" : undefined;
        percentageProperty = summary ? property : undefined;
        screenTimeQualifiers = { [property]: power ? ["battery", "USB", "AC"] : key.includes("three_state") ? ["voice call", "Wi-Fi", "3G"] : ["waiting", "voice call", "Wi-Fi", "3G", "other"] };
        break;
      }
      case "collector.periodic_sampling": {
        const definition = definitionFor("acquisition", "collector");
        const specs = [
          ["schema.call_status_vocabulary", "voice call status", ["Ringing", "Waiting", "Calling"]],
          ["schema.screen_status_vocabulary", "screen status", ["On", "Off"]],
          ["schema.three_g_data_status_vocabulary", "3G data communication status", ["In", "Out", "InOut"]],
          ["schema.active_network_vocabulary", "active network", ["3G", "WiFi"]],
          ["schema.wifi_status_vocabulary", "WiFi status", ["On", "Off"]],
          ["schema.battery_level_range", "battery level", { minimum: 0, maximum: 100, unit: "percent" }],
          ["schema.battery_status_vocabulary", "battery status", ["Charing", "Discharging", "Full"]],
          ["schema.battery_plugged_vocabulary", "battery plugged status", ["Battery", "AC", "USB"]],
        ] as const;
        const profile = requireDefined(owner, OWNER_OF_SETTING);
        compatible = profile.source_work_id === "doi:10.1109/apnoms.2011.6077030" && setting.source_work_id === profile.source_work_id
          && profile.method_settings.filter(s => s.method_parameter_key === setting.method_parameter_key).length === 1
          && canonicalJson(definition) === canonicalJson({ action: "Android application periodically writes monitored state to a log file", deployed_interval: "not reported" });
        categoricalValuesByProperty = {};
        for (const [key, property, expected] of specs) {
          const matches = profile.method_settings.filter(s => s.method_parameter_key === key), match = matches[0];
          const actual = matches.length === 1 && match !== undefined ? definitionFor("event_schema", "raw_record", match.method_setting_id) : undefined;
          compatible = compatible && matches[0]?.source_work_id === profile.source_work_id && canonicalJson(actual) === canonicalJson(expected);
          if (Array.isArray(expected)) categoricalValuesByProperty[property] = expected;
        }
        entity = "device"; properties = specs.map(([, property]) => property);
        unit = undefined; unitsByProperty = { "battery level": "percent" }; percentageProperty = "battery level";
        break;
      }
    default: return undefined;
  }
  return { compatible, entity, properties, unit, unitsByProperty, screenTimeQualifiers, categoricalValuesByProperty, percentageProperty, booleanProperty: undefined, sourceQualifiers: false, numericIntegerRanges: undefined };
}

