function matchesBoredomRawDefinition(setting: MethodSettingAssertion, content: unknown, owner: StudyMethodProfile): boolean {
  const spec = requireDefined(boredomRawDefinitions[String(setting.method_parameter_key)], TABLE_ENTRY);
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  const gates = owner.method_settings.filter(s => s.method_parameter_key === "borapp.acquisition.screen_on_and_unlocked_gate"), gate = gates[0];
  if (owner.source_work_id !== "doi:10.1145/2750858.2804252" || setting.source_work_id !== owner.source_work_id
    || setting.method_setting_role !== "event_schema" || setting.method_target_layer !== spec.target
    || owner.method_settings.filter(s => s.method_parameter_key === setting.method_parameter_key).length !== 1
    || !sourceDefinitionTupleMatches(content, "event_schema", spec.target)
    || canonicalJson(body) !== canonicalJson(spec.body) || gates.length !== 1 || gate === undefined) return false;
  let gateContent: unknown;
  try { gateContent = JSON.parse(String(gate.method_value_json)); } catch { return false; }
  const gateBody = isRecord(gateContent) && Object.hasOwn(gateContent, "definition") ? gateContent.definition : gateContent;
  return gate.source_work_id === owner.source_work_id && gate.method_setting_role === "acquisition" && gate.method_target_layer === "collector"
    && sourceDefinitionTupleMatches(gateContent, "acquisition", "collector")
    && canonicalJson(gateBody) === canonicalJson({ always_collected: "Table 1 channels", conditional_collected: "Table 2 channels",
      conditional_state: { screen_on: true, unlocked: true } });
}


