function boredomObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown) => unknown) {
  const key = setting?.method_parameter_key;
  if (typeof key !== "string" || !setting) return undefined;
  const feature = Object.hasOwn(boredomFeatureDefinitions, key);
  const ratio = Object.hasOwn(boredomRatioDefinitions, key);
  if (Object.hasOwn(boredomRawDefinitions, key)) {
    const spec = requireDefined(boredomRawDefinitions[key], TABLE_ENTRY);
    const definition = definitionFor("event_schema", spec.target);
    const content: unknown = JSON.parse(String(setting.method_value_json));
    // Events retain their own occurrence definition and explicit event label,
    // not a screen-state snapshot, task/session grouping or derived predictor.
    const compatible = !!spec.properties && matchesBoredomRawDefinition(setting, content, requireDefined(owner, OWNER_OF_SETTING))
      && canonicalJson(definition) === canonicalJson(spec.body);
    return { compatible, entity: "device", properties: spec.properties ?? [], unit: spec.unit,
      categoricalValuesByProperty: spec.labels ? { [requireDefined(requireDefined(spec.properties, "a labelled boredom raw definition lists its properties")[0], "a labelled boredom raw definition names its labelled property")]: spec.labels } : undefined,
      booleanProperty: spec.booleanProperty, percentageProperty: spec.percentageProperty, unitsByProperty: undefined,
      screenTimeQualifiers: undefined, numericIntegerRanges: undefined, sourceQualifiers: false };
  }
  if (!feature && !ratio) return undefined;
  const definition = definitionFor(feature ? "feature_engineering" : "analysis", feature ? "derived_feature" : "outcome");
  const profile = requireDefined(owner, OWNER_OF_SETTING);
  let compatible = profile.source_work_id === "doi:10.1145/2750858.2804252" && setting.source_work_id === profile.source_work_id
    && profile.method_settings.filter(s => s.method_parameter_key === key).length === 1
    && canonicalJson(definition) === canonicalJson((feature ? boredomFeatureDefinitions : boredomRatioDefinitions)[key]);
  const property = feature ? key.slice("borapp.feature.".length) : key.slice("borapp2.outcome.".length);
  let screenTimeQualifiers: Record<string, string[]> | undefined;
  if (ratio) {
    const conditions = profile.method_settings.filter(s => s.method_parameter_key === "borapp2.validation.repeated_measures_design"), condition = conditions[0];
    const actual = conditions.length === 1 && condition !== undefined ? definitionFor("validation", "outcome", condition.method_setting_id) : undefined;
    compatible = compatible && conditions[0]?.source_work_id === profile.source_work_id
      && canonicalJson(actual) === canonicalJson({ conditions: ["inferred bored", "inferred normal"], design: "repeated-measures quasi-experiment", state_randomized: false });
    screenTimeQualifiers = { [property]: ["inferred bored", "inferred normal"] };
  }
  const unit = ratio ? "percent" : isRecord(definition) && typeof definition.unit === "string" ? definition.unit
    : ["bytes_received", "bytes_transmitted"].includes(property) ? "bytes" : undefined;
  const categories = Array.isArray(definition) ? definition
    : isRecord(definition) && Array.isArray(definition.categories) ? definition.categories : undefined;
  const categoricalValuesByProperty: Record<string, readonly string[]> | undefined = categories ? { [property]: categories as string[] } : undefined;
  const booleanProperty = feature && ["charging", "audio", "proximity", "screen_orient_changes"].includes(property) ? property : undefined;
  const numericIntegerRanges: Record<string, readonly [number, number]> | undefined = ["hour_of_day", "day_of_week"].includes(property)
    ? { [property]: (boredomFeatureDefinitions[key] as { range: [number, number] }).range } : undefined;
  return { compatible, entity: "participant", properties: [property], unit, screenTimeQualifiers, categoricalValuesByProperty, numericIntegerRanges,
    percentageProperty: ratio ? property : undefined, booleanProperty, unitsByProperty: undefined, sourceQualifiers: true };
}

function validateSampledTaskReference(row: Record<string, unknown>, path: string, tasks: TaskOccurrenceRecord[]) {
  if (row.task_occurrence_reference == null) return;
  if (typeof row.task_occurrence_reference !== "string" || !row.task_occurrence_reference.trim()) throw new Error(`${path}.task_occurrence_reference must be nonblank or null`);
  const matches = tasks.filter(task => task.task_occurrence_id === row.task_occurrence_reference
    && task.method_profile_id === row.method_profile_id && task.source_work_id === row.source_work_id
    && task.participant_id === row.participant_id && (task.device_id ?? null) === (row.device_id ?? null));
  if (matches.length !== 1) throw new Error(`${path}.task_occurrence_reference has no matching task within profile/source/participant/device`);
}

