const falakiTrendCompanions: Record<string, { role: string; target: string; definition: unknown }> = {"analysis.trend_table_history_cardinality":{"role":"analysis","target":"model","definition":{"n":3,"history":"adjacent immediately preceding chunks"}},"feature.trend_table_chunk_width":{"role":"feature_engineering","target":"derived_feature","definition":{"delta_minutes":10,"quantity":"battery energy usage reading per chunk"}},"analysis.energy_prediction_horizons":{"role":"analysis","target":"model","definition":{"w_hours":[1,2],"tables":"separate trend table for each predicted window size","scope":"two evaluated future windows"}}};
function falakiObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const key = String(setting?.method_parameter_key);
  if (!setting || !Object.hasOwn(falakiSampledSpecs, key)) return undefined;
  const spec = requireDefined(falakiSampledSpecs[key], TABLE_ENTRY);
  const definition = definitionFor(spec.role, spec.target, row.method_setting_reference, spec.target,
    key === "reporting.fitted_parameter_distributions" ? "reported_result" : spec.role);
  let compatible = owner?.source_work_id === "doi:10.1145/1814433.1814453" && setting.source_work_id === owner.source_work_id
    && owner.method_settings.filter(s => s.method_parameter_key === key).length === 1
    && canonicalJson(definition) === canonicalJson(spec.definition);
  if (key === "feature.trend_table_quantization_and_statistics") {
    const profile = requireDefined(owner, OWNER_OF_SETTING);
    for (const [companion, expected] of Object.entries(falakiTrendCompanions)) {
      const locals = profile.method_settings.filter(s => s.method_parameter_key === companion), local = locals[0];
      compatible = locals.length === 1 && local !== undefined && local.source_work_id === profile.source_work_id
        && canonicalJson(definitionFor(expected.role, expected.target, local.method_setting_id)) === canonicalJson(expected.definition) && compatible;
    }
    const knownHorizons = new Set(recordsOf(row.quantities).filter(q => ["following-window mean", "following-window standard deviation"].includes(String(q.observed_property)))
      .map(q => q.quantity_qualifier).filter(value => typeof value === "string"));
    if (knownHorizons.size > 1) throw new Error("Falaki trend-table statistics must belong to one supplied following-window horizon");
  }
  if (spec.entity === "application_category" && typeof row.observed_entity_token === "string"
    && !Object.hasOwn(requireDefined(falakiSampledSpecs["feature.application_category_vocabulary"], FIXED_KEY).definition as Record<string, unknown>, row.observed_entity_token)) {
    throw new Error("Falaki observed_entity_token must identify a disclosed application category");
  }
  return { compatible, entity: spec.entity, properties: Object.keys(spec.units), unit: undefined, unitsByProperty: spec.units,
    categoricalValuesByProperty: spec.states, screenTimeQualifiers: spec.qualifiers,
    percentageProperty: key === "feature.battery_indicator_drain" ? "remaining battery indicator" : undefined,
    booleanProperty: undefined, sourceQualifiers: !!spec.sourceQualifiers, numericIntegerRanges: undefined };
}

