function matchesHammerDefinition(row: Record<string, unknown>, setting: MethodSettingAssertion | undefined, body: unknown): boolean {
  const spec = hammerDefinitions[String(setting?.method_parameter_key)];
  return !!spec && row.source_work_id === "doi:10.1145/2634317.2634325" && setting?.source_work_id === row.source_work_id
    && setting.method_setting_role === spec.role && setting.method_target_layer === spec.target
    && sourceDefinitionTupleMatches(JSON.parse(String(setting.method_value_json)), spec.sourceRole, spec.sourceTarget)
    && canonicalJson(body) === canonicalJson(spec.body);
}

const hammerStatuses = ["isBusy", "isAlone", "isHappy", "isStressful"];
const hammerFrameProperties = ["forward-filled human label", "human confidence", "secondary classifier label", "secondary classifier confidence", "predicted logical status",
  "unique application count", "categorical mode", "minimum", "maximum", "average", "top-k dominant app categories", "time of day", "day of week", "logical location"];

function hammerObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const key = String(setting?.method_parameter_key);
  if (!["collector.foreground_app", "collector.screen_state_events", "collector.network_events", "collector.labels", "segmentation.frame_width"].includes(key)) return undefined;
  const frame = key === "segmentation.frame_width", labels = key === "collector.labels";
  const companions = frame ? ["aggregation.unique_count", "aggregation.categorical_mode", "aggregation.numeric", "feature.app_category",
    "feature.time_of_day", "feature.day_of_week", "feature.logical_location_inputs", "feature.logical_location",
    "label.forward_fill", "label.human_confidence", "label.human_confidence_prior", "label.secondary_source", "outcomes"] : labels ? ["outcomes"] : [];
  let compatible = true;
  for (const localKey of [key, ...companions]) {
    const locals = owner?.method_settings.filter(s => s.method_parameter_key === localKey) ?? [], spec = requireDefined(hammerDefinitions[localKey], TABLE_ENTRY), local = locals[0];
    const body = locals.length === 1 && local !== undefined ? definitionFor(spec.role, spec.target, local.method_setting_id, spec.sourceTarget, spec.sourceRole) : undefined;
    compatible = locals.length === 1 && matchesHammerDefinition(row, locals[0], body) && compatible;
  }
  // A frame is not a task window or a screen interval. Its exact local definition
  // carries the fixed width; no anchor, stride, endpoints or raw contributor join.
  if (frame && ["task_occurrence_reference", "source_event_time_token", "app_interruption_session_reference"].some(field => Object.hasOwn(row, field))) {
    throw new Error("Hammer frame has no source-declared task/event-time/session anchor");
  }
  const properties = frame ? hammerFrameProperties : labels ? hammerStatuses : key === "collector.screen_state_events" ? ["screen event"]
    : key === "collector.network_events" ? ["BSSID", "cellular tower ID", "network-status change"] : [];
  return { compatible, entity: frame || labels ? "participant" : key === "collector.foreground_app" ? "application" : "device",
    properties, unit: undefined, sourceQualifiers: frame, memberKind: frame ? "application" as const : undefined,
    memberProperties: frame ? ["histogram bin value", "application category"] : undefined, frame, labels };
}

function validateHammerQuantity(value: unknown, property: string, qualifier: unknown, shape: { frame: boolean; labels: boolean } | undefined, path: string) {
  if (!shape) return;
  if (shape.frame && ["forward-filled human label", "human confidence", "secondary classifier label", "secondary classifier confidence", "predicted logical status"].includes(property)
    && qualifier != null && (typeof qualifier !== "string" || !hammerStatuses.includes(qualifier))) throw new Error(path + " has no disclosed logical-status qualifier");
  if (value == null) return;
  const label = shape.labels || ["forward-filled human label", "secondary classifier label", "predicted logical status"].includes(property);
  if (label) {
    if (typeof value !== "boolean" && typeof value !== "string") throw new Error(path + " must contain a supplied normalized binary label, uninterpreted lexical label or JSON null");
    return; // No original binary coding or raw-text conversion is claimed.
  }
  if (property === "human confidence" || property === "secondary classifier confidence") {
    if (typeof value !== "number" && typeof value !== "string") throw new Error(path + " must contain a supplied confidence scalar or JSON null");
    if (typeof value === "number" && (!Number.isFinite(value) || value < 0 || value > 1)) throw new Error(path + " numeric confidence must be between zero and one, not percent");
  } else if (property === "top-k dominant app categories") {
    if (!Array.isArray(value) || value.some(cell => cell !== null && typeof cell !== "string")) throw new Error(path + " must contain a supplied category vector or JSON null");
  } else if (property === "logical location") {
    if (typeof value !== "string" || !["home", "work", "other", "null"].includes(value)) throw new Error(path + " has no disclosed logical-location state");
  } else if (property === "screen event") {
    if (value !== "screen ON" && value !== "screen OFF") throw new Error(path + " has no disclosed screen-event label");
  } else if (typeof value !== "number" && typeof value !== "string") throw new Error(path + " must contain a supplied scalar or JSON null");
  if (property === "unique application count" && typeof value === "number" && (!Number.isInteger(value) || value < 0)) throw new Error(path + " numeric unique-application count must be a nonnegative integer");
  if (typeof value === "number" && !Number.isFinite(value)) throw new Error(path + " must contain a finite numeric value");
}

const hammerSessionQuantityProperties: Record<string, string[]> = {
  "session.duration": ["elapsed session time"], "session.unique_app_count": ["unique application count"],
  "session.inter_session_time": ["time between consecutive sessions"], "feature.trigger_app": ["trigger app"],
  "feature.trigger_type": ["trigger type"], "feature.app_category": ["application category", "app histogram bin", "top-k dominant app categories"],
  "feature.time_of_day": ["time of day"], "feature.day_of_week": ["day of week"], "feature.logical_location": ["logical location"],
  "aggregation.unique_count": ["unique application count"], "aggregation.categorical_mode": ["categorical mode"],
  "aggregation.numeric": ["minimum", "maximum", "average"],
  "label.forward_fill": ["forward-filled human label"], "label.human_confidence": ["human confidence"],
  "label.secondary_source": ["secondary classifier label", "secondary classifier confidence"], "outcomes": ["predicted logical status"],
};

function validateHammerSessionQuantity(row: Record<string, unknown>, quantity: Record<string, unknown>, setting: MethodSettingAssertion | undefined, body: unknown, path: string): boolean | undefined {
  const key = String(setting?.method_parameter_key);
  if (row.source_work_id !== "doi:10.1145/2634317.2634325" || !Object.hasOwn(hammerSessionQuantityProperties, key)) return undefined;
  if (!matchesHammerDefinition(row, setting, body) || !requireDefined(hammerSessionQuantityProperties[key], TABLE_ENTRY).includes(String(quantity.observed_property))) return false;
  const app = quantity.observed_property === "application category" || quantity.observed_property === "app histogram bin";
  const label = key.startsWith("label.") || key === "outcomes";
  if (quantity.quantity_scope !== (app ? "app" : "session") || quantity.evidence_unit != null || quantity.quantity_qualifier != null && !label && key !== "aggregation.numeric" && key !== "aggregation.categorical_mode") return false;
  validateHammerQuantity(undefined, String(quantity.observed_property), quantity.quantity_qualifier, { frame: label, labels: false }, path);
  if (quantity.evidence_value_json != null) {
    const value: unknown = JSON.parse(quantity.evidence_value_json as string);
    const shape = { frame: label, labels: false };
    validateHammerQuantity(value, String(quantity.observed_property), quantity.quantity_qualifier, shape, path + ".evidence_value_json");
    if (quantity.observed_property === "trigger type" && value !== null && (typeof value !== "string" || !["active wake/use", "passive notification-or-call attraction"].includes(value))) return false;
  }
  return true;
}

