function appMembershipObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const key = setting?.method_parameter_key;
  const running = key === "dataset.fields", vector = key === "preprocess.app_vector", installed = key === "probe.static_device";
  const recent = key === "collector.key_family";
  const raw = typeof key === "string" && ["probe.battery", "probe.network", "probe.screen_activation", "probe.foreground_app", "probe.sms"].includes(key);
  if (!running && !vector && !installed && !raw && !recent) return undefined;
  const work = recent ? "doi:10.1145/2638728.2641700" : installed || raw ? "doi:10.4000/questionsdecommunication.9851" : "doi:10.1007/s42486-020-00045-z";
  const keys = recent ? ["collector.key_family", "collector.rank_orientation", "collector.component_value", "collector.record_clock", "collector.snapshot_capacity"]
    : installed ? ["probe.static_device", "aggregation.app_inventory"] : raw ? [String(key)]
    : ["dataset.fields", "dataset.snapshot_kind", "preprocess.simultaneous_apps", ...(vector
      ? ["preprocess.app_vocabulary", "preprocess.app_vector", "preprocess.context_append", "preprocess.location_discretization", "time.day_bins", "time.bin_encoding"] : [])];
  let compatible = owner?.source_work_id === work && row.source_work_id === work && setting?.source_work_id === work;
  for (const localKey of keys) {
    const locals = owner?.method_settings.filter(s => s.method_parameter_key === localKey) ?? [], local = locals[0];
    const spec = requireDefined(appMembershipDefinitions[localKey], TABLE_ENTRY);
    const body = locals.length === 1 && local !== undefined ? definitionFor(spec.role, spec.target, local.method_setting_id, spec.sourceTarget, spec.sourceRole) : undefined;
    compatible = compatible && locals.length === 1 && locals[0]?.source_work_id === work && canonicalJson(body) === canonicalJson(spec.body);
  }
  if (typeof row.device_id !== "string" || !row.device_id.trim()) throw new Error("Source-bound device/app observations require a supplied device owner");
  const rawProperties: Record<string, string[]> = {
    "probe.battery": ["battery level"], "probe.network": ["network detection", "network performance"],
    "probe.screen_activation": [], "probe.foreground_app": [], "probe.sms": ["SMS direction"],
  };
  const categoricalValuesByProperty: Record<string, readonly string[]> | undefined = installed
    ? { "installation origin": ["native/operator/manufacturer/Android", "user-installed"] }
    : key === "probe.sms" ? { "SMS direction": ["received", "sent"] } : undefined;
  return {
    compatible, entity: key === "probe.foreground_app" ? "application" : "device",
    properties: recent ? [] : installed ? ["device type", "operator", "Android version"] : vector ? ["time-bin vector", "location vector"] : raw ? requireDefined(rawProperties[String(key)], TABLE_ENTRY) : ["smartphone location"],
    unit: undefined, memberKind: running || vector || installed || recent ? "application" as const : undefined,
    memberProperties: recent ? ["source row token", "source key", "source rank", "boot-elapsed logging time", "component string", "source value"] : installed ? ["installation origin"] : vector ? ["app used"] : [],
    rankedRecent: recent,
    categoricalValuesByProperty, binaryProperty: vector ? "app used" : undefined,
    vectorProperties: vector ? ["time-bin vector", "location vector"] : [],
    booleanProperty: key === "probe.network" ? "network detection" : undefined,
  };
}

function validateAppMembershipQuantity(value: unknown, property: string, shape: ReturnType<typeof appMembershipObservationShape>, path: string) {
  if (shape?.rankedRecent && value !== null) {
    if (property === "source rank") {
      if (typeof value !== "number" || !Number.isInteger(value) || value < 0 || value > 9) throw new Error(`${path} must contain a supplied zero-based recent-task rank from 0 to 9 or JSON null`);
    } else if (typeof value !== "string" || (property === "source key" && !/^app\|recent\|[0-9]$/.test(value))) {
      throw new Error(`${path} must preserve a supplied recent-task lexical cell or JSON null`);
    }
  }
  if (shape?.binaryProperty === property && value !== null && value !== 0 && value !== 1) {
    throw new Error(`${path} must contain a supplied binary app-use value or JSON null`);
  }
  if (!shape?.vectorProperties.includes(property) || value === null) return;
  if (!Array.isArray(value) || !value.length || (property === "time-bin vector" && value.length !== 4)
    || value.some(cell => cell !== 0 && cell !== 1 && cell !== null)) throw new Error(`${path} must contain a supplied binary context vector with its declared extent or JSON null`);
  // Do not calculate one-hot positions, coordinates, binning or an app/context join.
}

function validateRecentTaskMembers(value: unknown, shape: ReturnType<typeof appMembershipObservationShape>, path: string) {
  if (!shape?.rankedRecent || !Array.isArray(value)) return;
  if (value.length > 10) throw new Error(`${path} exceeds the source-declared recent-task capacity of ten`);
  const ranks = new Set<number>(), keys = new Set<string>();
  for (const [index, item] of value.entries()) {
    const member = item as SampledEntityMemberRecord; // Individual members and lexical JSON were validated before this call.
    const known = (property: string): unknown => {
      const token = member.quantities?.find(q => q.observed_property === property)?.evidence_value_json;
      return token == null ? undefined : JSON.parse(token);
    };
    const rank = known("source rank"), key = known("source key");
    if (typeof rank === "number") {
      if (ranks.has(rank)) throw new Error(`${path}[${index}] duplicates a supplied recent-task rank`);
      ranks.add(rank);
    }
    if (typeof key === "string") {
      if (keys.has(key)) throw new Error(`${path}[${index}] duplicates a supplied recent-task source key`);
      keys.add(key);
      if (typeof rank === "number" && Number(key.slice("app|recent|".length)) !== rank) throw new Error(`${path}[${index}] has contradictory supplied source key and rank`);
    }
  }
  // Never derive omitted ranks, order members, group polls, compare clocks or construct launches.
}

function appInterruptionObservationShape(row: Record<string, unknown>, path: string, profiles: StudyMethodProfile[], owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown) => unknown) {
  let entity: string, properties: string[], unit: string | undefined, compatible: boolean;
  let unitsByProperty: Record<string, string> | undefined;
  let categoricalValuesByProperty: Record<string, readonly string[]> | undefined, percentageProperty: string | undefined;
  switch (setting?.method_parameter_key) {
    case "aggregation.statistic": {
      const body = definitionFor("aggregation", "derived_feature");
      const minima = requireDefined(owner, OWNER_OF_SETTING).method_settings.filter(s => s.method_parameter_key === "aggregation.minimum_samples_per_app"), minimum = minima[0];
      compatible = owner?.source_work_id === "doi:10.1145/3191754" && setting.source_work_id === owner.source_work_id
        && body === "within-app percentage share by U&G type and each app's largest share"
        && minima.length === 1 && minimum !== undefined && minimum.source_work_id === owner.source_work_id
        && definitionFor("aggregation", "derived_feature", minimum.method_setting_id) === 20;
      entity = "application"; unit = "percent"; unitsByProperty = { "sample count": "count" };
      properties = ["productivity share", "information share", "communication share", "entertainment share", "social-media share", "largest share", "sample count"];
      break;
    }
    case "movement.source_and_filter": {
      const body = validateProfileRecordOwner(row, path, profiles, "acquisition", "raw_record");
      const content: unknown = JSON.parse(String(setting.method_value_json));
      compatible = owner?.source_work_id === "doi:10.1145/3473856.3473881" && setting.source_work_id === owner.source_work_id
        && sourceDefinitionTupleMatches(content, "acquisition", "context_record")
        && canonicalJson(body) === canonicalJson({ api: "Google Activity Recognition", classes: ["IN_VEHICLE", "ON_BICYCLE", "ON_FOOT", "RUNNING", "WALKING", "STILL", "UNKNOWN"], minimum_confidence: 90, comparator: ">=", state_persists_until_switch: true });
      entity = "device"; properties = ["movement type", "movement confidence"]; unit = undefined;
      unitsByProperty = { "movement confidence": "percent" };
      categoricalValuesByProperty = { "movement type": ["IN_VEHICLE", "ON_BICYCLE", "ON_FOOT", "RUNNING", "WALKING", "STILL", "UNKNOWN"] };
      percentageProperty = "movement confidence";
      break;
    }
    case "communication.collector": {
      validateProfileRecordOwner(row, path, profiles, "acquisition", "collector");
      compatible = matchesAppInterruptionDefinition(setting, JSON.parse(String(setting.method_value_json)), "app_session_context", requireDefined(owner, OWNER_OF_SETTING).source_work_id) === true;
      entity = "device"; properties = ["communication event"]; unit = undefined;
      categoricalValuesByProperty = { "communication event": ["android.intent.action.PHONE_STATE with RINGING", "android.provider.Telephony.SMS_RECEIVED"] };
      break;
    }
    default: return undefined;
  }
  return { compatible, entity, properties, unit, unitsByProperty, screenTimeQualifiers: undefined, categoricalValuesByProperty, percentageProperty, booleanProperty: undefined, sourceQualifiers: false, numericIntegerRanges: undefined };
}

function validateSampledAppSessionReference(row: Record<string, unknown>, setting: MethodSettingAssertion | undefined, path: string, appSessions: AppInterruptionSessionRecord[]) {
  if (Object.hasOwn(row, "app_interruption_session_reference") && !["movement.source_and_filter", "communication.collector"].includes(String(setting?.method_parameter_key))) {
    throw new Error(path + ".app_interruption_session_reference is incompatible with this observation definition");
  }
  if (row.app_interruption_session_reference != null) {
    const reference = row.app_interruption_session_reference;
    const candidates = appSessions.filter(session => session.app_interruption_session_id === reference
      && session.method_profile_id === row.method_profile_id && session.source_work_id === row.source_work_id
      && session.participant_id === row.participant_id
      && (row.device_id == null || session.device_id == null || row.device_id === session.device_id));
    if (typeof reference !== "string" || !reference.trim() || candidates.length !== 1) {
      throw new Error(path + ".app_interruption_session_reference must resolve unambiguously within profile/source/participant and compatible known device");
    }
  }
}

function validateSampledObservationIdentity(row: Record<string, unknown>, id: string, entity: string, ids: Set<string>, path: string) {
  const key = canonicalJson([row.method_profile_id, row.participant_id, row.device_id ?? null, id]);
  if (!id.trim() || ids.has(key)) throw new Error(`${path}.sampled_observation_id is blank or duplicated within profile/participant/device`);
  ids.add(key);
  if (row.observed_entity_kind !== entity) throw new Error(`${path}.observed_entity_kind must be ${entity}`);
  for (const field of ["observed_entity_token", "observation_instant", "source_event_time_token"]) {
    if (row[field] != null && typeof row[field] !== "string") throw new Error(`${path}.${field} must be a string or null`);
  }
}

