  const key = String(profiles.find(profile => profile.method_profile_id === row.method_profile_id)?.method_settings.find(setting => setting.method_setting_id === row.method_setting_reference)?.method_parameter_key);
  for (const quantity of row.quantities ?? []) {
    const value: unknown = quantity.evidence_value_json == null ? null : JSON.parse(quantity.evidence_value_json);
    const booleanProperty = signalPowerSpecs[key]?.booleanProperty;
    if (quantity.observed_property === booleanProperty && value !== null && typeof value !== "boolean") throw new Error(path + " requires a supplied boolean designation or unknown");
    if (typeof value !== "number") continue; // No lexical coercion or unknown-value defaults.
    const property = quantity.observed_property;
    const physical = ["bytes transferred", "network usage", "allocated bytes", "frame size", "radiotap rate", "frame duration", "scan duration",
      "reported current", "frequency", "packet size", "transfer size", "end-to-end RTT", "TCP-window count", "TCP-window size", "window duration", "effective rate",
      "tail duration", "overlap current", "supplied offset", "server RTT", "synthetic flow size", "synthetic RTT", "maximum delay hours", "supplied delay"];
    if ((physical.includes(property) || quantity.evidence_unit === "µAh") && value < 0) throw new Error(path + " contains a negative supplied physical quantity");
    if (["bytes transferred", "network usage", "frame size", "packet size", "transfer size", "TCP-window count", "TCP-window size"].includes(property)
      && !Number.isInteger(value)) throw new Error(path + " requires an integer supplied count");
    if (key === "trace.location_cycle" && property === "hour of day" && (!Number.isInteger(value) || value < 0 || value > 23)) throw new Error(path + " requires a supplied hour from 0 through 23");
    if (property === "synthetic RTT" && (key === "whatif.rtt.wifi" && (value < 5 || value > 100)
      || key === "whatif.rtt.3g" && (value < 100 || value > 700))) throw new Error(path + " contradicts the disclosed synthetic RTT range");
    if (property === "maximum delay hours" && ![2, 12].includes(value)) throw new Error(path + " contradicts the two disclosed maximum-delay configurations");
  }
  const maximum = nextAppQuantity(row, "maximum delay hours"), delay = nextAppQuantity(row, "supplied delay");
  if (key === "whatif.delay_rule" && typeof maximum === "number" && typeof delay === "number" && delay > maximum) throw new Error(path + " exceeds its supplied maximum delay");
