  const matches = (name: string) => {
    const expected = requireDefined(s3Definitions[name], TABLE_ENTRY), locals = owner?.method_settings.filter(s => s.method_parameter_key === name) ?? [], local = locals[0];
    if (owner?.source_work_id !== s3Work || locals.length !== 1 || local === undefined || local.source_work_id !== s3Work) return false;
    const content: unknown = JSON.parse(String(local.method_value_json));
    const body = definitionFor(expected.role, expected.target, local.method_setting_id, expected.sourceTarget, expected.sourceRole);
    return sourceDefinitionTupleMatches(content, expected.sourceRole, expected.sourceTarget)
      && canonicalJson(body) === canonicalJson(expected.definition);
  };
  const compatible = matches(key) && (spec.companions ?? []).every(matches);
  return { compatible, entity: spec.entity ?? "device", properties: spec.properties, unit: undefined, spec, key };
