    "Location Update": ["latitude", "longitude", "payload position 3", "payload position 4"],
    "Context Trigger": ["Aviate context"], "Context Pulled": ["Aviate context"],
    "Charge Cable": ["cable plugged"], "Audio Cable": ["cable plugged"],
