  if (quantities?.some(q => !["action family", "rendered event token", ...fields[family] ?? []].includes(q.observed_property))) throw new Error(path + " has payload fields incompatible with its known action family");
  const literal: Record<string, string> = { "App Open": "App_Opened", "Location Update": "Location_Update", "Context Trigger": "Context_Triggered" };
  const token = quantities?.find(q => q.observed_property === "rendered event token")?.evidence_value_json;
  const rendered: unknown = token == null ? undefined : JSON.parse(token);
  if (literal[family] && typeof rendered === "string" && rendered !== literal[family]) throw new Error(path + " contradicts its printed event token");
