  if (work === smsPersonalityWork && key === "feature.place_center") return smsFeatureReferenceRule;
  if (work === changCommunicationWork && Object.hasOwn(changReferenceRules, key)) return changReferenceRule;
  if (work === stddWork && Object.hasOwn(stddReferenceRules, key)) return stddReferenceRule;
  if (work === anxietyWork && (Object.hasOwn(anxietyReferenceRules, key) || anxietyPatternKeys.includes(key))) return anxietyReferenceRule;
  if (work === predictorWork && predictorReferenceKeys.includes(key)) return predictorReferenceRule;
  if (work === nextAppWork && ["features.event_training_rows", "features.action_context_sampling", "features.embedding_mapreduce", "cold_app.installation_partition", "cold_user.most_similar", "cold_user.pseudo_inventory", "cold_user.pseudo_history", "model.prediction_rule"].includes(key)) return nextAppReferenceRule;
  if (work === trafficWork && trafficReferenceKeys.includes(key)) return trafficReferenceRule;
  if (work === s3Work && s3ReferenceRoots.includes(key)) return s3ReferenceRule;
  if (work === autosenWork && autosenReferenceKeys.includes(key)) return autosenReferenceRule;
  if (work === moodscopeWork && key === "api.mood_correction") return moodscopeReferenceRule;
  if (work === wearableMoodWork && Object.hasOwn(wearableMoodReferenceRules, key)) return wearableMoodReferenceRule;
  if (work === depressionTrafficWork && Object.hasOwn(depressionTrafficReferenceRules, key)) return depressionTrafficReferenceRule;
  if (work === signalPowerWork && Object.hasOwn(signalPowerReferenceRules, key)) return signalPowerReferenceRule;
  if (work === prefminerWork && Object.hasOwn(prefminerReferenceRules, key)) return prefminerReferenceRule;
