function classroomReferenceRuleFor(work: string, key: string): ((key: string, role: string) => SampledObservationReferenceRule | undefined) | undefined {
  if (!Object.hasOwn(classroomReferenceTargets[work] ?? {}, key)) return undefined;
  return (_key, role) => {
    const targetKey = requireDefined(requireDefined(classroomReferenceTargets[work], TABLE_ENTRY)[key], TABLE_ENTRY)[role];
    return targetKey ? { targetKey, multiple: true } : undefined;
  };
}
function validateClassroomResolvedReferences(row: SampledQuantityObservationRecord, resolved: ResolvedSampledObservationReference[], path: string) {
  if (row.observed_entity_kind !== "course") return;
  for (const link of resolved) {
    if (link.target.observed_entity_kind === "course" && typeof link.target.observed_entity_token === "string"
      && link.target.observed_entity_token !== row.observed_entity_token) throw new Error(path + " contradicts the supplied course owner");
  }
  // Reference order is not chronology; unknown supports remain unknown. Course
  // tokens do not manufacture class clocks, denominators or raw-event joins.
}

function validateClassroomResponse(response: Record<string, unknown>, setting: MethodSettingAssertion | undefined, sourceWorkId: string, path: string) {
  const spec = setting && classroomTaskDefinitions[String(setting.method_parameter_key)];
  if (!spec || sourceWorkId !== classroomKimWork) return;
  const declared = Array.isArray(spec.body) ? spec.body
    : isRecord(spec.body) ? spec.body.items ?? spec.body.topics : undefined;
  const items = isRecord(declared) ? Object.keys(declared) : declared;
  if (!Array.isArray(items) || !items.includes(response.observed_property)) throw new Error(path + ".observed_property is not a disclosed classroom questionnaire topic");
}

function classroomSessionBoundaries(row: Record<string, unknown>, setting: MethodSettingAssertion, profiles: StudyMethodProfile[], path: string): { starts: string[]; ends: string[] } | undefined {
  const key = String(setting.method_parameter_key);
  if (!["session.screen_on_start", "reconstruction.screen_on_to_off_session"].includes(key)) return undefined;
  const kim = key === "session.screen_on_start", work = kim ? classroomKimWork : classroomBjerreWork;
  const target = kim ? "device_session" : "screen_bout";
  const expected = kim
    ? "start at Screen On; power/home button and reacting to a notification are examples, not an exhaustive trigger list"
    : { start: "screen on", end: "subsequent screen off", unpaired_event_policy: "not disclosed" };
  if (row.source_work_id !== work || setting.source_work_id !== work
    || canonicalJson(validateProfileRecordOwner(row, path, profiles, "reconstruction", target)) !== canonicalJson(expected)
    || !sourceDefinitionTupleMatches(JSON.parse(String(setting.method_value_json)) as unknown, "reconstruction", target)) throw new Error(path + " has no compatible classroom session definition");
  if (kim) {
    const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
    const ends = owner.method_settings.filter(s => s.method_parameter_key === "session.screen_off_end"), end = ends[0];
    if (ends.length !== 1 || end === undefined || end.source_work_id !== work
      || validateProfileRecordOwner({ ...row, method_setting_reference: end.method_setting_id }, path, profiles, "reconstruction", target) !== "end at Screen Off"
      || !sourceDefinitionTupleMatches(JSON.parse(String(end.method_value_json)) as unknown, "reconstruction", target)) throw new Error(path + " has no compatible classroom session end definition");
  }
  return { starts: [kim ? "Screen On" : "screen on"], ends: [kim ? "Screen Off" : "subsequent screen off"] };
}

