function isCohortAppSummaryObservation(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined): boolean {
  const spec = owner && setting && cohortAppSummarySpecs[owner.source_work_id]?.[String(setting.method_parameter_key)];
  return !!spec && setting.source_work_id === owner.source_work_id && spec.entity.includes(String(row.observed_entity_kind))
    && nextAppQuantity(row as SampledQuantityObservationRecord, "population scope") === "all participants";
}
function cohortAppSummaryObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const key = String(setting?.method_parameter_key), spec = owner && cohortAppSummarySpecs[owner.source_work_id]?.[key];
  if (!spec || !setting || key === "apps.within_user_normalization" && nextAppQuantity(row as SampledQuantityObservationRecord, "population scope") !== "all participants") return undefined;
  const locals = owner.method_settings.filter(s => s.method_parameter_key === key);
  let compatible = locals.length === 1 && setting.source_work_id === owner.source_work_id
    && canonicalJson(definitionFor(spec.role, spec.target, undefined, spec.sourceTarget, spec.sourceRole)) === canonicalJson(spec.body);
  for (const companionKey of spec.companions ?? []) {
    const expected = cohortAppSummaryCompanions[companionKey as keyof typeof cohortAppSummaryCompanions], references = owner.method_settings.filter(s => s.method_parameter_key === companionKey), reference = references[0];
    compatible = references.length === 1 && reference !== undefined && reference.source_work_id === owner.source_work_id
      && canonicalJson(definitionFor(expected.role, expected.target, reference.method_setting_id, expected.sourceTarget, expected.sourceRole)) === canonicalJson(expected.body) && compatible;
  }
  const entity = spec.entity.includes(String(row.observed_entity_kind)) ? String(row.observed_entity_kind) : requireDefined(spec.entity[0], "a cohort app-summary spec lists at least one entity kind");
  return { compatible, entity, properties: ["population scope", ...Object.keys(spec.units)], unit: undefined,
    unitsByProperty: Object.fromEntries(Object.entries(spec.units).map(([property,unit]) => [property,unit ?? undefined])),
    sourceQualifiers: true, screenTimeQualifiers: undefined, categoricalValuesByProperty: undefined,
    percentageProperty: undefined, booleanProperty: undefined, numericIntegerRanges: undefined, spec, key };
}
function validateCohortAppSummaryQuantity(value: unknown, property: string, shape: ReturnType<typeof cohortAppSummaryObservationShape>, path: string): void {
  if (!shape || value == null) return;
  const text = ["population scope", "destination category", "comparison scope", "reference scope", "pair first app", "pair second app", "comparison basis"].includes(property);
  const choices = property === "population scope" ? ["all participants"] : shape.spec.choices?.[property];
  if (text ? typeof value !== "string" || !value.trim() || choices && !choices.includes(value)
    : shape.spec.booleans?.includes(property) ? typeof value !== "boolean" : typeof value !== "number" && typeof value !== "string") throw new Error(path + " has an incompatible supplied cohort/app summary value");
  if (typeof value !== "number") return; // Quoted lexical tokens remain opaque, never coerced.
  const count = ["application launch count", "app occurrences per chain", "distinct apps per chain", "chain count", "supporting participants", "participants below class-use fraction 0.80"].includes(property);
  if (!Number.isFinite(value) || value < 0 && !shape.spec.signedProperties?.includes(property) || count && !Number.isInteger(value)
    || shape.spec.units[property] === "percent" && value > 100 || (property === "selected-app duration fraction" || property.endsWith(" class-use fraction")) && value > 1
    || property === "hour of day" && (!Number.isInteger(value) || value > 23)) throw new Error(path + " has an invalid supplied numeric cohort/app summary");
}
function validateCohortAppSummaryObservation(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, shape: ReturnType<typeof cohortAppSummaryObservationShape>, path: string): void {
  if (!shape) return;
  if (!isCohortAppSummaryObservation(row, owner, owner?.method_settings.find(s => s.method_setting_id === row.method_setting_reference))) throw new Error(path + " requires an explicit supplied all-participants aggregate scope");
  const scopes = Array.isArray(row.quantities) ? row.quantities.filter(q => isRecord(q) && q.observed_property === "population scope") : [];
  if (scopes.length !== 1 || (scopes[0] as Record<string, unknown>).quantity_qualifier != null) throw new Error(path + " requires one unqualified population-scope value");
  for (const quantity of Array.isArray(row.quantities) ? row.quantities : []) {
    if (isRecord(quantity) && quantity.observed_property !== "population scope" && shape.spec.qualifierChoices
      && quantity.quantity_qualifier != null && (typeof quantity.quantity_qualifier !== "string" || !shape.spec.qualifierChoices.includes(quantity.quantity_qualifier))) throw new Error(path + " has an incompatible supplied summary basis");
  }
  if (row.participant_id != null || row.device_id != null) throw new Error(path + " cannot assign a cohort/app aggregate to a known individual participant/device");
  if (typeof row.observed_entity_token !== "string" || !row.observed_entity_token.trim()) throw new Error(path + " requires a supplied group/app/category identity");
  const value = (property: string) => nextAppQuantity(row as SampledQuantityObservationRecord, property);
  if (shape.key === "apps.top_five" && value("selected top-five membership") === true
    && !(shape.spec.body as string[]).includes(String(row.observed_entity_token))) throw new Error(path + " contradicts the disclosed selected app set");
  if (shape.key === "apps.lms_comparator" && value("selected top-five membership") === true) throw new Error(path + " contradicts the separately added LMS comparison app");
  if (shape.key === "analysis.location_region_comparison" && typeof value("comparison scope") === "string"
    && value("comparison scope") === value("reference scope")) throw new Error(path + " requires distinct supplied US/Europe comparison sides");
}

