  if (shape.work === clinicalEpisodesWork && shape.key === "acceleration.resample_hz" && nextAppQuantity(row, "stage") === "raw signal"
    && Object.hasOwn(row, "sampled_observation_references")) throw new Error(path + " must not assign resampling supports to a supplied raw signal");
