function assessmentTrioReferenceRuleFor(work: string, key: string): ((key: string, role: string) => SampledObservationReferenceRule | undefined) | undefined {
  if (work === caughtMomentWork && caughtMomentFeatureKeys.includes(key)) return (_key, role) => role === "between-completion interval" ? { targetKey: "main.preprocess.interval_between_completed_surveys" } : undefined;
  const rules = work === caughtMomentWork ? caughtMomentReferenceRules : work === phqMarkersWork ? phqMarkersReferenceRules : work === clinicalEpisodesWork ? clinicalEpisodesReferenceRules : undefined;
  return rules && Object.hasOwn(rules, key) ? (_key, role) => rules[key]?.[role] : undefined;
}
function assessmentTrioRelated(row: SampledQuantityObservationRecord, role: string, keys: string[], profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[]) {
  const settingKey = (target: SampledQuantityObservationRecord) => profiles.find(profile => profile.method_profile_id === target.method_profile_id && profile.source_work_id === target.source_work_id)?.method_settings.find(setting => setting.method_setting_id === target.method_setting_reference)?.method_parameter_key;
  return (row.sampled_observation_references ?? []).filter(reference => reference.relationship_label === role && reference.sampled_observation_reference != null).flatMap(reference => {
    const matches = rows.filter(target => target.sampled_observation_id === reference.sampled_observation_reference && target.method_profile_id === row.method_profile_id
      && target.source_work_id === row.source_work_id && target.participant_id === row.participant_id && (row.device_id == null || target.device_id == null || row.device_id === target.device_id)
      && keys.includes(String(settingKey(target))));
    return matches.length === 1 ? matches : [];
  });
}
function assessmentTrioKnownEqual(a: unknown, b: unknown, path: string, meaning: string) {
  if (a != null && b != null && canonicalJson(a) !== canonicalJson(b)) throw new Error(path + " contradicts its supplied " + meaning);
}
function validateCaughtMomentReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string, profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[]) {
  const target = (role: string) => resolved.find(link => link.role === role)?.target;
  if (key === "main.preprocess.interval_between_completed_surveys") {
    const previous = target("previous completed survey"), next = target("next completed survey");
    if (previous && next && (previous.sampled_observation_id === next.sampled_observation_id
      || previous.task_occurrence_reference != null && previous.task_occurrence_reference === next.task_occurrence_reference)) throw new Error(path + " requires distinct supplied completed surveys, not two aliases of one completion");
  }
  if (key === "main.preprocess.normalize_per_hour") {
    const feature = target("unscaled feature"), family = nextAppQuantity(row, "predictor family");
    const featureKey = feature && profiles.find(profile => profile.method_profile_id === feature.method_profile_id)?.method_settings.find(setting => setting.method_setting_id === feature.method_setting_reference)?.method_parameter_key;
    if (typeof featureKey === "string" && family != null && (typeof family !== "string" || caughtMomentFeatureKeys.indexOf(featureKey) !== caughtMomentPredictors.indexOf(family))) throw new Error(path + " contradicts the supplied predictor family");
  }
  if (key.startsWith("pilot.preprocess.per_person_")) for (const link of resolved) assessmentTrioKnownEqual(nextAppQuantity(row, "column number"), nextAppQuantity(link.target, "column number"), path, "pilot item identity");
  if (key !== "main.preprocess.analysis_csv_schema") return;
  const feature = target("interval feature"), outcome = target("completed outcome");
  if (!feature) return;
  assessmentTrioKnownEqual(nextAppQuantity(row, "predictor family"), nextAppQuantity(feature, "predictor family"), path, "analysis predictor identity");
  assessmentTrioKnownEqual(nextAppQuantity(row, "s"), nextAppQuantity(feature, "supplied per-hour feature"), path, "explicit analysis predictor value");
  if (!outcome) return;
  assessmentTrioKnownEqual(nextAppQuantity(row, "p"), nextAppQuantity(outcome, "GPS-ESM mean"), path, "explicit analysis outcome value");
  for (const unscaled of assessmentTrioRelated(feature, "unscaled feature", caughtMomentFeatureKeys, profiles, rows))
    for (const interval of assessmentTrioRelated(unscaled, "between-completion interval", ["main.preprocess.interval_between_completed_surveys"], profiles, rows))
      for (const completion of assessmentTrioRelated(interval, "next completed survey", ["main.outcome.aggregate"], profiles, rows)) {
        assessmentTrioKnownEqual(completion.task_occurrence_reference, outcome.task_occurrence_reference, path, "interval-ending completion and analysis outcome");
      }
}
function validatePhqMarkersReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string, profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[]) {
  const day = nextAppQuantity(row, "day token");
  if (["preprocess.participant_day_merge", "qc.day_exclusion_rule"].includes(key)) for (const link of resolved) {
    if (link.role !== "day-pair regularity") assessmentTrioKnownEqual(day, nextAppQuantity(link.target, "day token"), path, "particular day owner");
    else {
      const first = nextAppQuantity(link.target, "first day token"), second = nextAppQuantity(link.target, "second day token");
      if (day != null && first != null && second != null && day !== first && day !== second) throw new Error(path + " names a daily regularity result outside its supplied day pair");
    }
  }
  if (key === "feature.regularity_pair") {
    const first = nextAppQuantity(row, "first day token"), second = nextAppQuantity(row, "second day token");
    if (first != null && first === second) throw new Error(path + " must retain two distinct supplied days");
    for (const link of resolved) assessmentTrioKnownEqual(link.role === "first-day hour" ? first : second, nextAppQuantity(link.target, "day token"), path, "regularity-pair day membership");
  }
  if (key === "analysis.lmm_standardization") for (const link of resolved) assessmentTrioKnownEqual(nextAppQuantity(row, "feature identity"), nextAppQuantity(link.target, "feature identity"), path, "standardized feature identity");
  if (!["analysis.ml.predictor_set_features", "analysis.ml.predictor_set_demographics"].includes(key)) return;
  const windows = new Set<string>();
  for (const link of resolved) {
    if (link.role === "PHQ8 assessment window") windows.add(link.target.sampled_observation_id);
    if (link.role === "pooled mean" || link.role === "pooled SD") for (const window of assessmentTrioRelated(link.target, "PHQ8 assessment window", ["analysis.pooling_window"], profiles, rows)) windows.add(window.sampled_observation_id);
  }
  if (windows.size > 1) throw new Error(path + " combines features from different known PHQ8 assessment windows");
}
function clinicalEpisodesKey(row: SampledQuantityObservationRecord, profiles: StudyMethodProfile[]) {
  return profiles.find(profile => profile.method_profile_id === row.method_profile_id && profile.source_work_id === row.source_work_id)?.method_settings.find(setting => setting.method_setting_id === row.method_setting_reference)?.method_parameter_key;
}
function clinicalEpisodesFeatureModality(row: SampledQuantityObservationRecord, profiles: StudyMethodProfile[]) {
  const key = clinicalEpisodesKey(row, profiles);
  return key === "acceleration.daily_aggregation" ? "accelerometer" : key === "gps.daily_feature_count" ? "GPS" : nextAppQuantity(row, "modality");
}
function clinicalEpisodesKnownState(window: SampledQuantityObservationRecord, profiles: StudyMethodProfile[], tasks: TaskOccurrenceRecord[]) {
  if (window.task_occurrence_reference == null) return undefined;
  const owner = profiles.find(profile => profile.method_profile_id === window.method_profile_id && profile.source_work_id === window.source_work_id);
  const task = tasks.find(task => task.task_occurrence_id === window.task_occurrence_reference && task.method_profile_id === window.method_profile_id
    && task.source_work_id === window.source_work_id && task.participant_id === window.participant_id
    && (task.device_id == null || window.device_id == null || task.device_id === window.device_id));
  const assessments = task?.criterion_assessments?.filter(assessment => owner?.method_settings.find(setting => setting.method_setting_id === assessment.criterion_setting_reference)?.method_parameter_key === "ground_truth.state_scale") ?? [];
  const assessment = assessments.length === 1 ? assessments[0] : undefined;
  return assessment?.assessment_value_json == null ? undefined : JSON.parse(assessment.assessment_value_json) as unknown;
}
function validateClinicalAssignmentReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string,
  profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[], tasks: TaskOccurrenceRecord[]) {
  for (const link of resolved) {
    if (link.role === "default clinical window") assessmentTrioKnownEqual(row.task_occurrence_reference, link.target.task_occurrence_reference, path, "modified/default clinical assessment owner");
    if (key === "ground_truth.unstable_self_assessment_exclusion" && link.role === "clinical assignment window") {
      assessmentTrioKnownEqual(nextAppQuantity(row, "supplied assigned clinical state"), clinicalEpisodesKnownState(link.target, profiles, tasks), path, "clinical state assignment");
      for (const original of assessmentTrioRelated(link.target, "default clinical window", ["ground_truth.default_alignment_window_days"], profiles, rows))
        assessmentTrioKnownEqual(nextAppQuantity(row, "supplied assigned clinical state"), clinicalEpisodesKnownState(original, profiles, tasks), path, "default clinical state assignment");
    }
    if (["clinical day assignment", "clinical day comparison", "outdoor stay", "feature day", "test day"].includes(link.role)) assessmentTrioKnownEqual(nextAppQuantity(row, "day token"), nextAppQuantity(link.target, "day token"), path, "clinical/feature day owner");
  }
}
function validateClinicalModelReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string,
  profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[]) {
  const modality = nextAppQuantity(row, "modality");
  for (const link of resolved) {
    if (["training day", "patient model", "feature day"].includes(link.role)) assessmentTrioKnownEqual(modality, clinicalEpisodesFeatureModality(link.target, profiles), path, "model modality");
    if (key === "change_detection.density" && link.role === "training day")
      for (const assignment of assessmentTrioRelated(link.target, "clinical day assignment", ["ground_truth.unstable_self_assessment_exclusion"], profiles, rows))
        assessmentTrioKnownEqual(nextAppQuantity(row, "default state"), nextAppQuantity(assignment, "supplied assigned clinical state"), path, "default-state training label");
    if (["accelerometer prediction", "GPS prediction", "accelerometer decision", "GPS decision"].includes(link.role)) {
      assessmentTrioKnownEqual(link.role.startsWith("GPS") ? "GPS" : "accelerometer", nextAppQuantity(link.target, "modality"), path, "fusion modality");
      assessmentTrioKnownEqual(nextAppQuantity(row, "day token"), nextAppQuantity(link.target, "day token"), path, "fusion day");
    }
  }
  if (key === "change_detection.distance") {
    const model = resolved.find(link => link.role === "default-state model")?.target, day = resolved.find(link => link.role === "test day")?.target;
    if (model && day) assessmentTrioKnownEqual(nextAppQuantity(model, "modality"), clinicalEpisodesFeatureModality(day, profiles), path, "distance model/test modality");
  }
  if (key === "change_detection.decision") for (const link of resolved)
    for (const distance of assessmentTrioRelated(link.target, "distance", ["change_detection.distance"], profiles, rows)) {
      assessmentTrioKnownEqual(nextAppQuantity(row, "day token"), nextAppQuantity(distance, "day token"), path, "change-decision day");
      for (const model of assessmentTrioRelated(distance, "default-state model", ["change_detection.density"], profiles, rows))
        assessmentTrioKnownEqual(modality, nextAppQuantity(model, "modality"), path, "change-decision modality");
    }
  if (key === "change_detection.variant.weighted") for (const link of resolved)
    for (const distance of assessmentTrioRelated(link.target, "distance", ["change_detection.distance"], profiles, rows)) {
      assessmentTrioKnownEqual(nextAppQuantity(row, "day token"), nextAppQuantity(distance, "day token"), path, "weighted-distance day");
      for (const model of assessmentTrioRelated(distance, "default-state model", ["change_detection.density"], profiles, rows))
        assessmentTrioKnownEqual(link.role.startsWith("GPS") ? "GPS" : "accelerometer", nextAppQuantity(model, "modality"), path, "weighted-distance modality");
    }
}
function validateClinicalEpisodesReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string,
  profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[], tasks: TaskOccurrenceRecord[]) {
  if (key === "acceleration.resample_hz") for (const link of resolved) {
    assessmentTrioKnownEqual(nextAppQuantity(row, "stage"), "resampled signal", path, "resampling output stage");
    assessmentTrioKnownEqual(nextAppQuantity(link.target, "stage"), "raw signal", path, "resampling input stage");
    if (assessmentTrioRelated(link.target, "raw reading", [key], profiles, rows).length) throw new Error(path + " must not turn a supplied raw input into another resampling output");
    assessmentTrioKnownEqual(nextAppQuantity(row, "channel token"), nextAppQuantity(link.target, "channel token"), path, "supplied signal channel");
  }
  if (key === "acceleration.orientation_invariant_magnitude") for (const link of resolved) assessmentTrioKnownEqual(nextAppQuantity(link.target, "stage"), "resampled signal", path, "magnitude input stage");
  validateClinicalAssignmentReferences(row, key, resolved, path, profiles, rows, tasks);
  validateClinicalModelReferences(row, key, resolved, path, profiles, rows);
}
function validateAssessmentTrioReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string,
  profiles: StudyMethodProfile[], rows: SampledQuantityObservationRecord[], tasks: TaskOccurrenceRecord[]) {
  if (row.source_work_id === caughtMomentWork) validateCaughtMomentReferences(row, key, resolved, path, profiles, rows);
  else if (row.source_work_id === phqMarkersWork) validatePhqMarkersReferences(row, key, resolved, path, profiles, rows);
  else if (row.source_work_id === clinicalEpisodesWork) validateClinicalEpisodesReferences(row, key, resolved, path, profiles, rows, tasks);
}

