function tailFourWorkFor(key: string, work: string): string | undefined {
  if (tailFourDefinitions[work]?.[key]) return work;
  return tailFourUniqueKeys.includes(key) ? Object.keys(tailFourDefinitions).find(source => tailFourDefinitions[source]?.[key]) : undefined;
}
function tailFourDefinitionMatches(setting: MethodSettingAssertion | undefined, content: unknown, work: string, key: string): boolean {
  const expected = tailFourDefinitions[work]?.[key];
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  return !!expected && setting?.source_work_id === work && setting.method_setting_role === expected.role && setting.method_target_layer === expected.target
    && sourceDefinitionTupleMatches(content, expected.sourceRole, expected.sourceTarget) && canonicalJson(body) === canonicalJson(expected.definition);
}
function matchesTailFourTaskDefinition(setting: MethodSettingAssertion | undefined, content: unknown, kind: DisclosedTaskDefinitionKind, sourceWorkId: string): boolean | undefined {
  const key = String(setting?.method_parameter_key), work = tailFourWorkFor(key, sourceWorkId);
  if (!work || !tailFourTaskKinds[work]?.[key]) return undefined;
  return sourceWorkId === work && tailFourTaskKinds[work][key].includes(kind) && tailFourDefinitionMatches(setting, content, work, key);
}
function validateTailFourTaskValue(row: Record<string, unknown>, owner: StudyMethodProfile, kind: "response" | "criterion", path: string) {
  const key = String(owner.method_settings.find(setting => setting.method_setting_id === row[kind === "response" ? "questionnaire_setting_reference" : "criterion_setting_reference"])?.method_parameter_key);
  if (!tailFourTaskKinds[owner.source_work_id]?.[key]) return;
  const token = row[kind === "response" ? "response_value_json" : "assessment_value_json"];
  const value: unknown = typeof token === "string" ? JSON.parse(token) : null;
  if (owner.source_work_id === coronaHealthWork) {
    if (!["SingleChoice", "MultipleChoice", "Scale", "Knob", "text input"].includes(String(row.observed_property))) throw new Error(path + " must retain a disclosed questionnaire response form");
    return; // The release does not establish one universal answer serializer or scale.
  }
  if (owner.source_work_id === dailyValidityWork) {
    if (key === "diary.night_phone_profile_item") {
      if (row.observed_property !== "night phone profile" || value != null && (typeof value !== "string" || !["turned off", "on and silent/no sound or vibration", "on regular profile with sound or vibration"].includes(value))) throw new Error(path + " must retain the disclosed night-phone-profile answer");
      return;
    }
    const fields = key.includes("screen_time") ? ["screen time hours", "screen time minutes"] : ["phone checks"];
    const properties = key.includes("typical") ? ["school day", "non-school day"].flatMap(day => fields.map(field => day + " " + field)) : fields;
    if (!properties.includes(String(row.observed_property))) throw new Error(path + " must retain the disclosed daily or school/non-school typical report scope");
    assessmentTrioScalar(value, path);
    if (typeof value === "number" && (value < 0 || key.includes("phone_check") && !Number.isInteger(value))) throw new Error(path + " has an invalid supplied phone-use estimate");
    return;
  }
  if (owner.source_work_id === placesActivitiesWork) {
    if (key === "diary.activity_options") {
      if (row.observed_property !== "activity type" || value != null && (typeof value !== "string" || !["eat", "sleep", "work", "exercise", "social", "relaxation"].includes(value))) throw new Error(path + " must retain a disclosed offered activity");
    } else if (key === "diary.other_free_text_allowed") {
      if (row.observed_property !== "other activity text" || value != null && typeof value !== "string") throw new Error(path + " must retain supplied other-activity text separately from a chores recode");
    } else if (["place_type.vocabulary", "place_type.four_coder_merge"].includes(key)) {
      if (value != null && typeof value !== "string") throw new Error(path + " must retain a supplied place type without inventing the unavailable codebook");
    } else {
      const dimensions = requireDefined(requireDefined(tailFourDefinitions[placesActivitiesWork], FIXED_KEY)["place_characteristic.retained_dimensions"], FIXED_KEY).definition as string[];
      if (!dimensions.includes(String(row.criterion_label))) throw new Error(path + " must retain a disclosed place-characteristic dimension");
      assessmentTrioScalar(value, path);
      if (typeof value === "number" && (!Number.isInteger(value) || value < 1 || value > 7)) throw new Error(path + " has an invalid supplied seven-point coder rating");
    }
    return;
  }
  if (key === "quality.questionnaire_conflict_validation") {
    if (value != null && typeof value !== "boolean") throw new Error(path + " must retain an independently supplied questionnaire-validation decision");
    return;
  }
  assessmentTrioScalar(value, path);
  if (kind === "response") return; // Printed nightly/past-week wording and unreported raw answer encoding are retained.
  const maximum = key === "outcome.questionnaire_score_range" ? 18 : ["diary.score.sleep_medicine", "diary.score.trouble_item_encoding"].includes(key) ? 1 : key === "diary.score.wakefulness_frequency" ? 2 : 3;
  if (typeof value === "number" && (!Number.isInteger(value) || value < 0 || value > maximum)) throw new Error(path + " has an invalid independently supplied SleepMiner component or total");
}
function isTailFourPooledObservation(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined): boolean {
  const spec = tailFourSampleSpecs[String(owner?.source_work_id)]?.[String(setting?.method_parameter_key)];
  return !!spec?.optionalParticipant && setting?.source_work_id === owner?.source_work_id && row.observed_entity_kind === "participant_group";
}
function tailFourObservationShape(owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown) {
  const key = String(setting?.method_parameter_key), work = tailFourWorkFor(key, String(owner?.source_work_id));
  const spec = work ? tailFourSampleSpecs[work]?.[key] : undefined;
  if (!work || !spec) return undefined;
  const matches = (name: string) => {
    const expected = tailFourDefinitions[work]?.[name], locals = owner?.method_settings.filter(setting => setting.method_parameter_key === name) ?? [], local = locals[0];
    if (!expected || owner?.source_work_id !== work || locals.length !== 1 || local === undefined || local.source_work_id !== work) return false;
    return tailFourDefinitionMatches(local, JSON.parse(String(local.method_value_json)) as unknown, work, name)
      && canonicalJson(definitionFor(expected.role, expected.target, local.method_setting_id, expected.sourceTarget, expected.sourceRole)) === canonicalJson(expected.definition);
  };
  return { compatible: matches(key) && (spec.companions ?? []).every(matches), entity: spec.entity ?? "participant", properties: spec.properties,
    unit: undefined, unitsByProperty: spec.units, work, key, spec,
    memberKind: spec.members ? "application" : undefined,
    memberProperties: spec.members ? ["block number", "packageName", "completeFGServiceUseTime", "completeUseTime", "dailyValues"] : undefined };
}
function validateTailFourQuantity(value: unknown, property: string, shape: ReturnType<typeof tailFourObservationShape>, path: string) {
  if (!shape || value == null) return;
  const { spec } = shape;
  if (spec.members && ["block number", "packageName", "completeFGServiceUseTime", "completeUseTime", "dailyValues"].includes(property)) {
    if (["packageName", "dailyValues"].includes(property)) {
      if (typeof value !== "string") throw new Error(path + " must retain a package or unresolved serialized dailyValues token");
    } else {
      assessmentTrioScalar(value, path);
      if (typeof value === "number" && (value < 0 || property === "block number" && (!Number.isInteger(value) || value < 1 || value > 5))) throw new Error(path + " has an invalid supplied app block or duration");
    }
    return;
  }
  const categories = spec.categories?.[property];
  if (categories && (typeof value !== "string" || !categories.includes(value))) throw new Error(path + " must retain a disclosed source category");
  if (spec.stringVectors?.includes(property)) {
    if (!Array.isArray(value) || value.some(item => item != null && (typeof item !== "string" || !item.trim()))) throw new Error(path + " must retain supplied component identities");
    return;
  }
  if (spec.vectors?.includes(property)) {
    if (!Array.isArray(value) || value.some(item => item != null && (typeof item !== "number" || !Number.isFinite(item)))) throw new Error(path + " must retain supplied finite component values");
    return;
  }
  if (spec.booleans?.includes(property)) {
    if (typeof value !== "boolean") throw new Error(path + " must retain an independent normalized decision, not recode numeric values");
    return;
  }
  if (spec.texts?.includes(property) && typeof value !== "string") throw new Error(path + " must retain a supplied opaque token/text");
  assessmentTrioScalar(value, path);
  if (typeof value !== "number") return;
  const range = spec.ranges?.[property];
  if (range && (value < range[0] || value > range[1]) || spec.integers?.includes(property) && !Number.isInteger(value)
    || spec.counts?.includes(property) && (!Number.isInteger(value) || value < 0) || spec.nonnegative?.includes(property) && value < 0) throw new Error(path + " has an invalid supplied source quantity");
  if (shape.work === dailyValidityWork && shape.key === "reconstruction.short_off_bridge" && property === "supplied off-run duration" && value > 3) throw new Error(path + " contradicts the source up-to-three-second bridge");
  if (shape.work === placesActivitiesWork && shape.key === "location.top_places_for_coding" && property === "supplied place rank" && (value < 1 || value > 10)) throw new Error(path + " contradicts the source top-ten coding selection");
}
function validateTailFourTaskOwner(row: SampledQuantityObservationRecord, shape: NonNullable<ReturnType<typeof tailFourObservationShape>>, tasks: TaskOccurrenceRecord[], profiles: StudyMethodProfile[], path: string) {
  if (!Object.hasOwn(row, "task_occurrence_reference")) return;
  const taskKind = shape.spec.task;
  if (!taskKind) throw new Error(path + " must not manufacture a questionnaire owner for this source observation");
  if (row.task_occurrence_reference == null) return;
  const task = tasks.find(task => task.task_occurrence_id === row.task_occurrence_reference && task.method_profile_id === row.method_profile_id
    && task.source_work_id === row.source_work_id && task.participant_id === row.participant_id && (task.device_id ?? null) === (row.device_id ?? null));
  const owner = requireDefined(profiles.find(profile => profile.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const keys = task ? [...(task.task_questionnaire_responses ?? []).map(response => response.questionnaire_setting_reference), ...(task.criterion_assessments ?? []).map(criterion => criterion.criterion_setting_reference)]
    .map(reference => String(owner.method_settings.find(setting => setting.method_setting_id === reference)?.method_parameter_key)) : [];
  const allowed: Record<string, string[]> = {
    "night profile": ["diary.night_phone_profile_item"],
    "daily report": ["diary.daily_screen_time_item", "diary.daily_phone_check_item"],
    "typical report": ["diary.typical_screen_time_item", "diary.typical_phone_check_item"],
    "Corona completion": ["diary.question_types"],
    "activity diary": ["diary.activity_options", "diary.other_free_text_allowed"],
    "place coder": ["place_type.vocabulary", "place_characteristic.rating_scale"],
    "place author": ["place_type.four_coder_merge"],
    "sleep diary": [...Object.keys(requireDefined(tailFourTaskKinds[sleepPredictionWork], FIXED_KEY)).filter(key => key.startsWith("diary.item.")), "outcome.questionnaire_score_range"],
  };
  if (!task || !keys.some(key => allowed[taskKind]?.includes(key))) throw new Error(path + " must refer to an actual compatible source questionnaire or coding completion");
  if (shape.spec.task === "place coder" && task.assessor_id != null && !task.assessor_id.trim()) throw new Error(path + " has an invalid supplied coder identity");
}
function validateTailFourObservation(row: SampledQuantityObservationRecord, shape: ReturnType<typeof tailFourObservationShape>, tasks: TaskOccurrenceRecord[], profiles: StudyMethodProfile[], path: string) {
  if (Object.hasOwn(row, "denotes_interval")) {
    if (!shape?.compatible || !shape.spec.interval) throw new Error(path + ".denotes_interval is incompatible with this source observation");
    if (row.denotes_interval != null) {
      const interval = parseUsageInterval(row.denotes_interval, path + ".denotes_interval");
      if (typeof interval.duration_seconds === "number" && interval.duration_seconds < 0) throw new Error(path + ".denotes_interval.duration_seconds must be nonnegative");
    }
  }
  if (!shape) return;
  validateTailFourTaskOwner(row, shape, tasks, profiles, path);
  if (Object.hasOwn(row, "source_event_time_token") && !shape.spec.eventTime) throw new Error(path + " must not recast a supplied summary as a raw event");
  if (shape.spec.optionalParticipant && (row.participant_id != null || row.device_id != null)) throw new Error(path + " must retain a group subject, not a manufactured individual participant/device");
  for (const quantity of row.quantities ?? []) if (Object.hasOwn(quantity, "quantity_qualifier")) throw new Error(path + " must retain supplied scope in its named source quantities");
  for (const [namesProperty, valuesProperty] of [["channel identities", "channel readings"], ["feature identities", "feature values"]] as const) {
    const names = nextAppQuantity(row, namesProperty), values = nextAppQuantity(row, valuesProperty);
    if (Array.isArray(names) && new Set(names.filter(name => name != null)).size !== names.filter(name => name != null).length) throw new Error(path + " duplicates a known supplied component identity");
    if (Array.isArray(names) && Array.isArray(values) && names.length !== values.length) throw new Error(path + " has unequal supplied component identity/value lengths");
  }
  if (shape.spec.members && row.entity_members != null) {
    if (!Array.isArray(row.entity_members)) throw new Error(path + ".entity_members must be an array or null");
    if (row.entity_members.length > 5) throw new Error(path + " exceeds the five source app blocks");
    const positions = row.entity_members.map(member => {
      const token = member.quantities?.find(quantity => quantity.observed_property === "block number")?.evidence_value_json;
      return typeof token === "string" ? JSON.parse(token) as unknown : null;
    }).filter(value => value != null);
    if (new Set(positions).size !== positions.length) throw new Error(path + " duplicates a known app block number");
  }
}
function dailyValiditySessionBoundaries(row: Record<string, unknown>, setting: MethodSettingAssertion, profiles: StudyMethodProfile[], path: string): { starts: string[]; ends: string[] } | undefined {
  if (setting.method_parameter_key !== "reconstruction.screen_on_session" || row.source_work_id !== dailyValidityWork && !tailFourUniqueKeys.includes("reconstruction.screen_on_session")) return undefined;
  const owner = profiles.find(profile => profile.method_profile_id === row.method_profile_id);
  if (owner?.source_work_id !== dailyValidityWork || !tailFourDefinitionMatches(setting, JSON.parse(String(setting.method_value_json)) as unknown, dailyValidityWork, "reconstruction.screen_on_session")) throw new Error(path + " has no compatible daily-validity screen-session definition");
  if (isRecord(row.denotes_interval) && typeof row.denotes_interval.duration_seconds === "number" && row.denotes_interval.duration_seconds < 0) throw new Error(path + " has a negative supplied screen-session duration");
  return { starts: ["screen-on"], ends: ["screen-off"] };
}
function validateDailyValiditySessionLabel(row: Record<string, unknown>, label: Record<string, unknown>, setting: MethodSettingAssertion | undefined, path: string): boolean {
  if (row.source_work_id !== dailyValidityWork || setting?.method_parameter_key !== "feature.phone_check_definition") return false;
  if (!tailFourDefinitionMatches(setting, JSON.parse(String(setting.method_value_json)) as unknown, dailyValidityWork, "feature.phone_check_definition") || label.observed_property !== "phone check") throw new Error(path + " has no compatible daily-validity phone-check definition");
  if (!stringArray(label, "source_locators", path).length || stringArray(label, "source_locators", path).some(locator => !locator.trim())) throw new Error(path + ".source_locators must retain nonblank provenance");
  if (label.label_value_json != null) {
    if (typeof label.label_value_json !== "string") throw new Error(path + " must retain a lexical supplied phone-check label");
    const value: unknown = JSON.parse(label.label_value_json);
    if (value != null && typeof value !== "boolean") throw new Error(path + " must retain a supplied boolean phone-check classification");
    if (typeof value === "boolean" && isRecord(row.denotes_interval) && typeof row.denotes_interval.duration_seconds === "number"
      && value !== (row.denotes_interval.duration_seconds <= 15)) throw new Error(path + " contradicts the known supplied session duration and at-most-15-second phone-check label");
  }
  if (label.questionnaire_response_references != null && (!Array.isArray(label.questionnaire_response_references) || label.questionnaire_response_references.length)) throw new Error(path + " phone-check classification is not a subjective report");
  return true;
}

