function tailFourReferenceRuleFor(work: string, key: string): ((key: string, role: string) => SampledObservationReferenceRule | undefined) | undefined {
  const rules = tailFourReferenceRules[work]?.[key];
  return rules ? (_key, role) => rules[role] : undefined;
}
function tailFourKnownQuantityMatches(row: SampledQuantityObservationRecord, target: SampledQuantityObservationRecord, property: string, path: string) {
  const left = nextAppQuantity(row, property), right = nextAppQuantity(target, property);
  if (left != null && right != null && canonicalJson(left) !== canonicalJson(right)) throw new Error(path + " contradicts the known supplied " + property);
}
function validateTailFourPlaceReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string, tasks: TaskOccurrenceRecord[]) {
  for (const { target } of resolved) {
    if (row.observed_entity_kind === "place" && target.observed_entity_kind === "place" && row.observed_entity_token != null && target.observed_entity_token != null && row.observed_entity_token !== target.observed_entity_token) throw new Error(path + " must retain the same supplied place identity");
    tailFourKnownQuantityMatches(row, target, "dimension", path);
  }
  if (["place_type.four_coder_merge", "place_characteristic.coder_aggregation"].includes(key)) {
    if (resolved.length > 4) throw new Error(path + " exceeds the four independent source coders");
    const assessorIds = resolved.map(({ target }) => tasks.find(task => task.task_occurrence_id === target.task_occurrence_reference && task.method_profile_id === target.method_profile_id
      && task.source_work_id === target.source_work_id && task.participant_id === target.participant_id && (task.device_id ?? null) === (target.device_id ?? null))?.assessor_id).filter(id => id != null);
    if (new Set(assessorIds).size !== assessorIds.length) throw new Error(path + " repeats a known coder instead of independent coder evidence");
  }
  if (key === "aggregation.per_user_context_average") {
    const kind = nextAppQuantity(row, "context kind");
    if (kind != null && (typeof kind !== "string" || resolved.some(link => link.role !== kind + " context"))) throw new Error(path + " contradicts its known activity/place/characteristic context kind");
    for (const { target } of resolved) tailFourKnownQuantityMatches(row, target, "supplied characteristic category", path);
  }
  if (key === "reporting.point_and_bar_summary") for (const { target } of resolved) {
    tailFourKnownQuantityMatches(row, target, "context kind", path);
    tailFourKnownQuantityMatches(row, target, "context token", path);
    tailFourKnownQuantityMatches(row, target, "measure", path);
    tailFourKnownQuantityMatches(row, target, "supplied characteristic category", path);
  }
}
function validateTailFourResolvedReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string, tasks: TaskOccurrenceRecord[]) {
  if (row.source_work_id === placesActivitiesWork) {
    validateTailFourPlaceReferences(row, key, resolved, path, tasks);
    return;
  }
  if (row.source_work_id === coronaHealthWork) {
    for (const { target } of resolved) if (row.task_occurrence_reference != null && target.task_occurrence_reference != null && row.task_occurrence_reference !== target.task_occurrence_reference) throw new Error(path + " crosses two explicitly supplied questionnaire submissions");
    return; // No comparison of begin/collection/end/GPS lexical clocks or one-day assertion.
  }
  if (row.source_work_id === dailyValidityWork) {
    for (const { role, target } of resolved) {
      if (role === "day missingness") tailFourKnownQuantityMatches(row, target, "day token", path);
      if (role === "discrepancy input" || role === "weighted typical estimate") tailFourKnownQuantityMatches(row, target, "measure", path);
      const expectedState = role === "repaired unknown state" ? "screen-unknown" : ["preceding on bound", "following on bound"].includes(role) ? "screen-on" : undefined;
      const suppliedState = nextAppQuantity(target, "screen status");
      if (expectedState && suppliedState != null && suppliedState !== expectedState) throw new Error(path + " contradicts its known supplied screen-state support");
      if (key === "reconstruction.short_off_bridge" && role === "off member") {
        const state = nextAppQuantity(target, "screen status");
        if (state != null && state !== "screen-off") throw new Error(path + " must retain off members, not bridge unknown or on units");
      }
    }
    return;
  }
  if (row.source_work_id === sleepPredictionWork) {
    // Only identical explicitly supplied day identities are compared. A previous
    // day's token is never parsed, decremented, equated to a night token, or UTC-normalized.
    for (const { role, target } of resolved) if (role !== "same-subject previous quality") tailFourKnownQuantityMatches(row, target, "day token", path);
  }
}

function sampledMemberShape(shapes: ({ memberKind?: string; memberProperties?: string[] } | undefined)[]) {
  return { memberKind: shapes.find(shape => shape?.memberKind !== undefined)?.memberKind,
    memberProperties: shapes.find(shape => shape?.memberProperties !== undefined)?.memberProperties };
}
function scalarSampledObservationShape(row: Record<string, unknown>, path: string, profiles: StudyMethodProfile[], owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  definitionFor: (role: string, target: string, reference?: unknown, sourceTarget?: string, sourceRole?: string) => unknown,
  classroom: ReturnType<typeof classroomObservationShape>, cohortSummary: ReturnType<typeof cohortAppSummaryObservationShape>) {
  return cohortSummary ?? classroom ?? atteliaObservationShape(owner, setting, definitionFor) ?? dynamicSecurityObservationShape(row, owner, setting, definitionFor) ?? timeKillingObservationShape(row, owner, setting, definitionFor) ?? backDeviceObservationShape(owner, setting, definitionFor)
    ?? nestedSessionObservationShape(row, owner, setting, definitionFor) ?? smsFeatureObservationShape(row, owner, setting, definitionFor)
    ?? changObservationShape(row, path, profiles, owner, setting)
    ?? mercatiObservationShape(row, owner, setting, definitionFor)
    ?? signalPowerObservationShape(owner, setting, definitionFor)
    ?? depressionTrafficObservationShape(owner, setting, definitionFor)
    ?? trafficObservationShape(row, owner, setting, definitionFor)
    ?? falakiObservationShape(row, owner, setting, definitionFor)
    ?? energyRawObservationShape(row, owner, setting, definitionFor)
    ?? boredomObservationShape(row, owner, setting, definitionFor)
    ?? apnomsObservationShape(row, owner, setting, definitionFor)
    ?? appInterruptionObservationShape(row, path, profiles, owner, setting, definitionFor);
}

