function prefminerDefinitionMatches(setting: MethodSettingAssertion | undefined, content: unknown): boolean {
  const expected = prefminerDefinitions[String(setting?.method_parameter_key)];
  const body = isRecord(content) && Object.hasOwn(content, "definition") ? content.definition : content;
  return !!expected && setting?.source_work_id === prefminerWork && setting.method_setting_role === expected.role && setting.method_target_layer === expected.target
    && (sourceDefinitionTupleMatches(content, expected.sourceRole, expected.sourceTarget)
      || qualifiedSourceDefinitionTupleMatches(content, expected.sourceRole, expected.sourceTarget))
    && canonicalJson(body) === canonicalJson(expected.definition);
}
function matchesPrefminerTaskDefinition(setting: MethodSettingAssertion | undefined, content: unknown, kind: DisclosedTaskDefinitionKind, sourceWorkId: string): boolean | undefined {
  if (!["deployment.user_acceptance_rule_lifecycle", "diary.exit_questionnaire"].includes(String(setting?.method_parameter_key))) return undefined;
  return sourceWorkId === prefminerWork && kind === "response" && prefminerDefinitionMatches(setting, content);
}
function validatePrefminerTaskResponse(row: Record<string, unknown>, owner: StudyMethodProfile, path: string) {
  if (owner.source_work_id !== prefminerWork) return;
  const setting = owner.method_settings.find(setting => setting.method_setting_id === row.questionnaire_setting_reference);
  const key = String(setting?.method_parameter_key), token = row.response_value_json;
  const value: unknown = typeof token === "string" ? JSON.parse(token) : undefined;
  if (key === "deployment.user_acceptance_rule_lifecycle") {
    if (row.observed_property !== "rule proposal decision") throw new Error(path + " must identify the supplied rule-proposal decision");
    if (value != null && (typeof value !== "string" || !["Yes", "Never", "Not Now"].includes(value))) throw new Error(path + " must retain Yes, Never or Not Now, not binary item acceptance");
  } else if (key === "diary.exit_questionnaire") {
    const items = (requireDefined(prefminerDefinitions[key], FIXED_KEY).definition as { items: {id:string;text:string}[] }).items;
    const item = items.find(item => item.id === row.observed_property);
    if (!item || row.questionnaire_item_label != null && row.questionnaire_item_label !== item.text) throw new Error(path + " must retain one of the three source exit questions");
    assessmentTrioScalar(value, path);
    if (typeof value === "number" && (!Number.isInteger(value) || value < 1 || value > 5)) throw new Error(path + " must retain a supplied 1..5 exit response");
  }
}
function prefminerObservationShape(row: Record<string, unknown>, owner: StudyMethodProfile | undefined, setting: MethodSettingAssertion | undefined,
  profiles: StudyMethodProfile[], path: string) {
  const key = String(setting?.method_parameter_key), spec = prefminerSampleSpecs[key];
  // These exact keys are unique in the frozen corpus. Recognition is terminal even
  // when a forged source/body attempts the generic sampled-definition fallback.
  if (!spec) return undefined;
  const entity = spec.entities?.includes(String(row.observed_entity_kind)) ? String(row.observed_entity_kind) : spec.entity;
  const optionalHuman = entity === "participant_group" || entity === "device";
  const matches = (name: string) => {
    const expected = prefminerDefinitions[name], locals = owner?.method_settings.filter(setting => setting.method_parameter_key === name) ?? [], local = locals[0];
    if (!expected || owner?.source_work_id !== prefminerWork || locals.length !== 1 || local === undefined) return false;
    if (!prefminerDefinitionMatches(local, JSON.parse(String(local.method_value_json)) as unknown)) return false;
    // Reuse the owner validator, but do not feed these qualified older envelopes
    // through the stricter all-tuples wrapper path or invent absent source fields.
    validateProfileRecordOwner({ ...row, method_setting_reference: local.method_setting_id }, path, profiles, expected.role, expected.target, !optionalHuman);
    return true;
  };
  return { compatible: matches(key) && (spec.companions ?? []).every(matches), entity, properties: spec.properties,
    unit: undefined, unitsByProperty: spec.units, key, spec };
}
function validatePrefminerQuantity(value: unknown, property: string, shape: ReturnType<typeof prefminerObservationShape>, path: string) {
  if (!shape || value == null) return;
  const spec = shape.spec, choices = spec.categories?.[property];
  if (choices) {
    if (typeof value !== "string" || !choices.includes(value)) throw new Error(path + " must retain a disclosed PrefMiner category");
    return;
  }
  if (spec.booleans?.includes(property)) {
    if (typeof value !== "boolean") throw new Error(path + " must retain a supplied boolean without recoding a missing observation");
    return;
  }
  if (spec.strings?.includes(property)) {
    if (!Array.isArray(value) || value.some(item => item !== null && typeof item !== "string")) throw new Error(path + " must retain supplied term/keyword/day identities");
    return;
  }
  if (spec.vectors?.includes(property)) {
    if (!Array.isArray(value) || value.some(item => item !== null && (typeof item !== "number" || !Number.isFinite(item) || item < 0))) throw new Error(path + " must retain supplied finite nonnegative term frequencies");
    return;
  }
  if (spec.texts?.includes(property)) {
    if (typeof value !== "string") throw new Error(path + " must retain supplied text, not an inferred encoding");
    return;
  }
  assessmentTrioScalar(value, path);
  if (typeof value !== "number") return;
  if (spec.counts?.includes(property) && (!Number.isInteger(value) || value < 0)
    || spec.nonnegative?.includes(property) && value < 0
    || spec.probabilities?.includes(property) && (value < 0 || value > 1)
    || spec.percent?.includes(property) && (value < 0 || value > 100)) throw new Error(path + " has an invalid independently supplied count/measure");
  if (shape.key === "report.exit_questionnaire_results" && property === "mean response" && (value < 1 || value > 5)) throw new Error(path + " must retain a supplied exit-scale mean in 1..5");
}
function validatePrefminerObservation(row: SampledQuantityObservationRecord, shape: ReturnType<typeof prefminerObservationShape>, tasks: TaskOccurrenceRecord[], profiles: StudyMethodProfile[], path: string) {
  if (!shape) return;
  const q = (property: string) => nextAppQuantity(row, property), {spec,key} = shape;
  if (shape.entity === "participant_group") {
    if (row.participant_id != null || row.device_id != null) throw new Error(path + " must not assign pooled PrefMiner results to one known person or device");
    if (typeof q("population scope") !== "string" || !String(q("population scope")).trim()) throw new Error(path + " requires a supplied population description, not an invented original group identity");
  }
  if (shape.entity === "device" && (row.participant_id != null || typeof row.device_id !== "string" || !row.device_id.trim())) throw new Error(path + " requires a device-only PrefMiner resource owner");
  if (Object.hasOwn(row, "source_event_time_token") && !spec.event) throw new Error(path + ".source_event_time_token is not a disclosed raw-arrival role for this source definition");
  if (Object.hasOwn(row, "task_occurrence_reference")) {
    if (!spec.task) throw new Error(path + ".task_occurrence_reference is incompatible with this PrefMiner observation");
    if (q("lifecycle stage") != null && q("lifecycle stage") !== "proposal") throw new Error(path + " must keep consent completion on the proposal, not the independent rule state");
    if (row.task_occurrence_reference != null) {
      const task = tasks.find(task => task.task_occurrence_id === row.task_occurrence_reference && task.method_profile_id === row.method_profile_id
        && task.source_work_id === row.source_work_id && task.participant_id === row.participant_id && (task.device_id ?? null) === (row.device_id ?? null));
      const owner = profiles.find(profile => profile.method_profile_id === row.method_profile_id);
      const responses = task?.task_questionnaire_responses?.filter(response => owner?.method_settings.find(setting => setting.method_setting_id === response.questionnaire_setting_reference)?.method_parameter_key === spec.task) ?? [];
      if (responses.length !== 1) throw new Error(path + " must resolve to one unambiguous supplied rule-consent response");
    }
  }
  if (spec.paired) {
    const identities = q(spec.paired[0]), values = q(spec.paired[1]);
    if (Array.isArray(identities) && Array.isArray(values) && identities.length !== values.length) throw new Error(path + " must preserve supplied term/frequency pairing");
    if (Array.isArray(identities) && new Set(identities.filter(value => value != null)).size !== identities.filter(value => value != null).length) throw new Error(path + " cannot assign duplicate known term columns");
  }
  if (key === "association.rule_mining_algorithm") {
    const arm = q("feature arm");
    const allowed: Record<string,string[]> = {AR1:[],AR2:["activity"],AR3:["arrival time category"],AR4:["location"],AR5:["activity","arrival time category","location"]};
    if (typeof arm === "string" && ["activity","arrival time category","location"].some(property => q(property) != null && !allowed[arm]?.includes(property))) throw new Error(path + " has a known antecedent outside its supplied AR feature set");
  }
  if (key === "deployment.user_acceptance_rule_lifecycle") {
    if (q("within first 15 study days") === true && q("manual rule creation allowed") === true) throw new Error(path + " contradicts the source first-15-study-days manual-rule restriction");
    const stage = q("lifecycle stage"), stateFields = ["active","blacklisted","re-proposed"], availabilityFields = ["manual rule creation allowed","within first 15 study days"];
    if (stage === "proposal" && [...stateFields,...availabilityFields].some(property => q(property) != null)
      || stage === "rule state" && availabilityFields.some(property => q(property) != null)
      || stage === "manual-rule availability" && stateFields.some(property => q(property) != null)) throw new Error(path + " mixes a known proposal, rule state or manual-rule availability meaning");
  }
  if (key === "deployment.AR4_daily_charging_gate" && q("mining performed") === true && (q("charging") === false || q("phone in use") === true)) throw new Error(path + " contradicts the known charging/nonuse mining gate");
  // No title processing, TF/rule/metric arithmetic, calendar indexing, classifier
  // matching, consent recoding, rule activation or automatic filtering is performed.
}

