function validatePrefminerResolvedReferences(row: SampledQuantityObservationRecord, key: string, resolved: ResolvedSampledObservationReference[], path: string,
  rows: SampledQuantityObservationRecord[], profiles: StudyMethodProfile[]) {
  const q = (property: string) => nextAppQuantity(row, property);
  const links = (target: SampledQuantityObservationRecord, role: string, keys: string[]) => assessmentTrioRelated(target, role, keys, profiles, rows);
  const explicitRules = (target: SampledQuantityObservationRecord) => [
    ...links(target, "rule", ["association.rule_mining_algorithm"]),
    ...links(target, "represented rule", ["association.rule_mining_algorithm"]),
    ...links(target, "rule presentation", ["library.rule_keyword_representation"])
      .flatMap(presentation => links(presentation, "represented rule", ["association.rule_mining_algorithm"])),
  ];
  const explicitRule = (target: SampledQuantityObservationRecord) => explicitRules(target)[0];
  if (row.observed_entity_kind === "application") {
    const knownApps = new Set([row, ...resolved.map(link => link.target)]
      .filter(target => target.observed_entity_kind === "application" && target.observed_entity_token != null)
      .map(target => target.observed_entity_token));
    if (knownApps.size > 1) throw new Error(path + " contradicts the supplied originating-app partition");
  }
  const rule = resolved.find(link => link.role === "rule")?.target;
  if (key === "deployment.user_acceptance_rule_lifecycle") {
    const stage = q("lifecycle stage");
    if (stage === "manual-rule availability" && resolved.length) throw new Error(path + " cannot turn an application-level manual-rule restriction into a known proposal/rule link");
    const knownRules = new Set([...(rule ? [rule] : []), ...resolved.flatMap(({target}) => explicitRules(target))]);
    if (knownRules.size > 1) throw new Error(path + " names different supplied rules through its presentation or proposal");
    for (const {role,target} of resolved) {
      if (["prior proposal","consent proposal"].includes(role)) {
        const targetStage = nextAppQuantity(target,"lifecycle stage");
        if (targetStage != null && targetStage !== "proposal") throw new Error(path + " must preserve a known proposal target, not a rule-state record");
        if (stage != null && stage !== (role === "prior proposal" ? "proposal" : "rule state")) throw new Error(path + " has a proposal relationship on an incompatible lifecycle stage");
      }
    }
    // An explicitly supplied prior-proposal relation is acyclic, but no ordering
    // is inferred from timestamps, labels or a mining-pass index.
    const seen = new Set<SampledQuantityObservationRecord>([row]);
    let previous = links(row,"prior proposal",[key])[0];
    while (previous) {
      if (seen.has(previous)) throw new Error(path + " contains a cycle in supplied prior-proposal relationships");
      seen.add(previous);
      for (const known of explicitRules(previous)) knownRules.add(known);
      if (knownRules.size > 1) throw new Error(path + " names different supplied rules through its presentation or proposal");
      previous = links(previous,"prior proposal",[key])[0];
    }
  }
  if (key === "deployment.notification_filter_output") {
    const state = resolved.find(link => link.role === "supplied active state")?.target;
    if (state) {
      const stage = nextAppQuantity(state,"lifecycle stage"), stateRule = explicitRule(state);
      if (stage != null && stage !== "rule state") throw new Error(path + " must keep active-rule state distinct from a proposal");
      if (nextAppQuantity(state,"active") === false) throw new Error(path + " cannot identify a known inactive rule as its supplied active state");
      if (rule && stateRule && rule !== stateRule) throw new Error(path + " links a filter to another supplied rule's state");
    }
  }
  if (key === "analysis.five_feature_combinations") {
    const notification = resolved.find(link => link.role === "notification")?.target;
    const actual = resolved.find(link => link.role === "actual response")?.target;
    const actualNotification = actual && links(actual,"notification",["notification.title_input_and_privacy_boundary"])[0];
    if (notification && actualNotification && notification !== actualNotification) throw new Error(path + " links prediction and actual response for different supplied notifications");
    if (actual && nextAppQuantity(actual,"source response") === "handled on another device") throw new Error(path + " cannot include an explicitly other-device response in retrospective analysis");
    const ownArm = q("feature arm"), ruleArm = rule && nextAppQuantity(rule,"feature arm");
    if (ownArm != null && ruleArm != null && ownArm !== ruleArm) throw new Error(path + " contradicts its supplied rule feature arm");
  }
  if (key === "association.rule_mining_algorithm") {
    const iteration = resolved.find(link => link.role === "mining iteration")?.target;
    const iterationKey = iteration && profiles.find(profile => profile.method_profile_id === iteration.method_profile_id)?.method_settings.find(setting => setting.method_setting_id === iteration.method_setting_reference)?.method_parameter_key;
    if (iterationKey === "deployment.AR4_daily_charging_gate" && (q("feature arm") != null && q("feature arm") !== "AR4"
      || q("activity") != null || q("arrival time category") != null)) throw new Error(path + " contradicts the deployed AR4 feature scope");
  }
  if (key === "analysis.cross_validation") {
    const training = new Set(resolved.filter(link => link.role === "training notification").map(link => link.target));
    if (resolved.some(link => link.role === "test notification" && training.has(link.target))) throw new Error(path + " cannot use one supplied notification as both training and test in the same fold");
  }
  // Partial/null membership stays unknown. Do not reconstruct retraining identity,
  // blacklist matching, consent effects, time ordering or filtering eligibility.
}

