function appPeriodDefinitionSpec(row: Record<string, unknown>, setting: MethodSettingAssertion | undefined) {
  return appPeriodDefinitions[String(row.source_work_id)]?.[String(setting?.method_parameter_key)];
}
function matchesAppPeriodDefinition(row: Record<string, unknown>, setting: MethodSettingAssertion | undefined, content: unknown): boolean {
  const spec = appPeriodDefinitionSpec(row, setting);
  if (!spec || !setting || setting.source_work_id !== row.source_work_id
    || setting.method_setting_role !== spec.role || setting.method_target_layer !== spec.target) return false;
  const wrapped = isRecord(content) && Object.hasOwn(content, "definition");
  const body = wrapped ? content.definition : content;
  return (sourceDefinitionTupleMatches(content, spec.sourceRole, spec.sourceTarget)
    || qualifiedSourceDefinitionTupleMatches(content, spec.sourceRole, spec.sourceTarget))
    && canonicalJson(body) === canonicalJson(spec.definition)
    && (!wrapped || !Object.hasOwn(content, "source_stage") || content.source_stage === spec.stage)
    && (spec.printedItems === undefined || wrapped && canonicalJson(content.printed_items) === canonicalJson(spec.printedItems));
}
function requireAppPeriodDefinitions(row: Record<string, unknown>, profiles: StudyMethodProfile[], keys: readonly string[], path: string): void {
  const owner = profiles.find(p => p.method_profile_id === row.method_profile_id);
  for (const key of keys) {
    const settings = owner?.method_settings.filter(s => s.method_parameter_key === key) ?? [];
    const setting = settings[0], spec = appPeriodDefinitionSpec(row, setting);
    if (settings.length !== 1 || setting === undefined || !spec) throw new Error(path + " requires one compatible local app-period definition: " + key);
    validateProfileRecordOwner({ ...row, method_setting_reference: setting.method_setting_id }, path, profiles, spec.role, spec.target);
    if (!matchesAppPeriodDefinition(row, setting, JSON.parse(String(setting.method_value_json)))) throw new Error(path + " has an incompatible app-period definition: " + key);
  }
}
function matchesAppPeriodTaskDefinition(setting: MethodSettingAssertion | undefined, content: unknown, kind: DisclosedTaskDefinitionKind, work: string): boolean | undefined {
  if (!["benchmark.ues_measure", "benchmark.bes_selection"].includes(String(setting?.method_parameter_key))) return undefined;
  return work === mathurPeriodWork && matchesAppPeriodDefinition({ source_work_id: work }, setting, content)
    && (setting?.method_parameter_key === "benchmark.ues_measure" ? kind === "response" : kind === "criterion");
}
