function appPeriodSessionBoundaries(row: Record<string, unknown>, setting: MethodSettingAssertion, profiles: StudyMethodProfile[], path: string): { starts: string[]; ends: string[] } | undefined {
  const key = String(setting.method_parameter_key);
  if (!["sessionlogger.screen_session_bounds", "quantapp.context_feature_anchor", "session.partition", "session.application_chain_constructor"].includes(key)) return undefined;
  const spec = appPeriodDefinitionSpec(row, setting);
  if (!spec) throw new Error(path + " has no compatible source-specific app-period session unit");
  requireAppPeriodDefinitions(row, profiles, [key], path);
  if (key === "quantapp.context_feature_anchor") {
    requireAppPeriodDefinitions(row, profiles, ["quantapp.sensor_schedule"], path);
    // QuantApp states screen-on/session start, but no independently disclosed end;
    // SessionLogger's unlock gate and <=5-second merge are NOT transferred.
    return { starts: ["screen-on"], ends: [] };
  }
  if (key === "session.application_chain_constructor") {
    requireAppPeriodDefinitions(row, profiles, ["episode.application_session_definition"], path);
    return { starts: [], ends: [] }; // >30s standby rule is documentary, not executed.
  }
  const keys = key === "session.partition" ? hinikerSessionPolicyKeys : mathurSessionPolicyKeys;
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const policies = recordsOf(owner.session_construction_policies).filter(policy => policy.session_input_layer === "raw_record"
    && policy.session_output_layer === "device_session" && recordsOf(policy.method_settings).some(member => member.method_setting_id === row.method_setting_reference)), policy = policies[0];
  if (policies.length !== 1 || policy === undefined) throw new Error(path + " requires one unambiguous complete app-period session policy");
  const members = recordsOf(policy.method_settings).map(member => owner.method_settings.find(s => s.method_setting_id === member.method_setting_id)?.method_parameter_key);
  if (members.length !== keys.length || new Set(members).size !== keys.length || keys.some(part => !members.includes(part))) throw new Error(path + " has an incomplete app-period session policy");
  requireAppPeriodDefinitions(row, profiles, keys, path);
  return key === "session.partition"
    ? { starts: [], ends: ["lock", "screen_dark", "system_or_launcher_idle_gte_30_seconds"] }
    : { starts: ["screen-on"], ends: ["screen-off"] };
}
