function validateAppPeriodSessionQuantity(row: Record<string, unknown>, quantity: Record<string, unknown>, setting: MethodSettingAssertion | undefined, profiles: StudyMethodProfile[], path: string): boolean | undefined {
  const work = String(row.source_work_id), key = String(setting?.method_parameter_key);
  const rule = appPeriodQuantityRules[work]?.[key];
  if (!rule) return undefined;
  requireAppPeriodDefinitions({ ...row, source_locators: quantity.source_locators }, profiles, [key], path);
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const ownerKey = owner.method_settings.find(s => s.method_setting_id === row.method_setting_reference)?.method_parameter_key;
  const quantapp = ownerKey === "quantapp.context_feature_anchor";
  if (work === mathurPeriodWork) {
    if (key === "quantapp.context_feature_inventory" ? !quantapp : key === "proxy.app_bes_target" && quantapp) throw new Error(path + " has an incompatible study-stage quantity");
    requireAppPeriodDefinitions(row, profiles, quantapp ? ["quantapp.reuse_seven_app_features"] : ["sessionlogger.app_usage_period_unit"], path);
  } else if (work === hinikerPeriodWork) {
    requireAppPeriodDefinitions(row, profiles, ["window.session_sequence", "window.esm_partition", "feature.inventory_40", "app.category_vocabulary"], path);
    if (key === "feature.category_duration_20" && quantity.observation_category != null) {
      const categories = requireDefined(requireDefined(appPeriodDefinitions[work], FIXED_KEY)["app.category_vocabulary"], FIXED_KEY).definition as string[];
      if (typeof quantity.observation_category !== "string" || !categories.includes(quantity.observation_category)) throw new Error(path + " has an unknown source category");
    }
  }
  const property = quantity.observed_property, unit = rule.units?.[String(property)] ?? rule.unit;
  if (quantity.quantity_scope !== rule.scope || typeof property !== "string" || !rule.properties.includes(property)
    || (quantity.evidence_unit != null && quantity.evidence_unit !== unit)) throw new Error(path + " has an incompatible app-period quantity scope/property/unit");
  if (typeof quantity.evidence_value_json === "string") {
    const value: unknown = JSON.parse(quantity.evidence_value_json);
    if (value !== null && typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") throw new Error(path + " must retain an independent supplied scalar value");
    if (typeof value === "number" && !Number.isFinite(value)) throw new Error(path + " has an invalid supplied number");
    if (typeof value === "boolean" && !(work === mathurPeriodWork && key === "quantapp.context_feature_inventory" && ["isWeekend", "isCharging", "Proximity"].includes(property))) throw new Error(path + " has no disclosed boolean feature");
    if (work === mathurPeriodWork && key === "quantapp.context_feature_inventory") {
      const range = ({ BatteryLevel: [0, 100], DayOfWeek: [0, 6], HourOfDay: [0, 23] } as Record<string, readonly [number, number]>)[property];
      if (range && typeof value === "number" && (value < range[0] || value > range[1] || property !== "BatteryLevel" && !Number.isInteger(value))) throw new Error(path + " contradicts the disclosed numeric feature range");
    }
  }
  return true;
}
function validateAppPeriodSessionLabel(row: Record<string, unknown>, label: Record<string, unknown>, setting: MethodSettingAssertion | undefined, profiles: StudyMethodProfile[], path: string): boolean {
  const keys = ["proxy.per_user_median_label", "quantapp.proxy_app_labels", "quantapp.duration_weighted_session_label", "diary.binary_label"];
  const key = String(setting?.method_parameter_key);
  if (!keys.includes(key)) return false;
  requireAppPeriodDefinitions({ ...row, source_locators: label.source_locators }, profiles, [key], path);
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  const ownerKey = owner.method_settings.find(s => s.method_setting_id === row.method_setting_reference)?.method_parameter_key;
  const stage = key === "proxy.per_user_median_label" ? ownerKey === "sessionlogger.screen_session_bounds"
    : key === "diary.binary_label" ? ownerKey === "session.partition" : ownerKey === "quantapp.context_feature_anchor";
  const property = ({ "proxy.per_user_median_label": "EEG-derived app-period engagement class", "quantapp.proxy_app_labels": "RF-proxy app-period engagement class",
    "quantapp.duration_weighted_session_label": "duration-weighted session engagement class", "diary.binary_label": "instrumental/ritualistic phone-use class" } as Record<string, string>)[key];
  if (!stage || label.observed_property !== property) throw new Error(path + " has an incompatible study-stage or label scope");
  if (label.label_value_json != null) {
    if (typeof label.label_value_json !== "string") throw new Error(path + ".label_value_json must be lexical JSON or null");
    const value: unknown = JSON.parse(label.label_value_json);
    const labels = key === "diary.binary_label" ? ["instrumental", "ritualistic"] : ["High Engagement", "Low Engagement"];
    if (value !== null && (typeof value !== "string" || !labels.includes(value))) throw new Error(path + " has no disclosed engagement/usage class");
  }
  return true;
}
function validateAppPeriodSessionResponse(row: Record<string, unknown>, response: Record<string, unknown>, setting: MethodSettingAssertion | undefined, profiles: StudyMethodProfile[], path: string): boolean {
  const key = String(setting?.method_parameter_key);
  if (!["diary.prompt_text", "diary.response_options"].includes(key)) return false;
  requireAppPeriodDefinitions({ ...row, source_locators: response.source_locators }, profiles, ["diary.prompt_text", "diary.response_options"], path);
  const owner = requireDefined(profiles.find(p => p.method_profile_id === row.method_profile_id), ROW_PROFILE);
  if (owner.method_settings.find(s => s.method_setting_id === row.method_setting_reference)?.method_parameter_key !== "session.partition") throw new Error(path + " requires its own Hiniker session owner");
  if (response.questionnaire_item_label != null && response.questionnaire_item_label !== requireDefined(requireDefined(appPeriodDefinitions[hinikerPeriodWork], FIXED_KEY)["diary.prompt_text"], FIXED_KEY).definition) throw new Error(path + " contradicts the disclosed phone-use question");
  if (response.response_value_json != null) {
    if (typeof response.response_value_json !== "string") throw new Error(path + ".response_value_json must be lexical JSON or null");
    const value: unknown = JSON.parse(response.response_value_json);
    const options = requireDefined(requireDefined(appPeriodDefinitions[hinikerPeriodWork], FIXED_KEY)["diary.response_options"], FIXED_KEY).definition as string[];
    if (value !== null && (typeof value !== "string" || !options.includes(value))) throw new Error(path + " has no disclosed phone-use response option");
  }
  return true;
}
function validateSessionEvidenceReferences(row: Record<string, unknown>, path: string): void {
  const actions = recordsOf(row.session_actions), responses = recordsOf(row.session_questionnaire_responses);
  const actionIds = new Set(actions.map(action => String(action.task_action_id))), responseIds = new Set(responses.map(response => String(response.questionnaire_response_id)));
  const validate = (record: Record<string, unknown>, field: string, ids: Set<string>, itemPath: string): string[] => {
    if (record[field] == null) return [];
    if (!Array.isArray(record[field])) throw new Error(itemPath + "." + field + " must be an array or null");
    const refs = stringArray(record, field, itemPath);
    if (new Set(refs).size !== refs.length || refs.some(ref => !ref.trim() || !ids.has(ref))) throw new Error(itemPath + "." + field + " must resolve uniquely within the containing session");
    return refs;
  };
  for (const field of ["session_quantities", "session_labels"]) for (const [i, record] of recordsOf(row[field]).entries()) {
    const itemPath = path + "." + field + "[" + i + "]";
    const refs = validate(record, "support_task_action_references", actionIds, itemPath);
    validate(record, "questionnaire_response_references", responseIds, itemPath);
    if (field === "session_quantities" && typeof record.app_identifier === "string") {
      const supported = actions.filter(action => refs.includes(String(action.task_action_id)));
      if (supported.some(action => action.app_identifier != null && action.app_identifier !== record.app_identifier)) throw new Error(itemPath + " contradicts a known supported app-period identity");
    }
  }
}
