function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function recordsOf(value: unknown): Record<string, unknown>[] {
  return Array.isArray(value)
    ? value.filter((item): item is Record<string, unknown> => isRecord(item))
    : [];
}

function requiredString(source: Record<string, unknown>, key: string, path: string): string {
  const value = source[key];
  if (typeof value !== "string" || !value) throw new Error(`${path}.${key} must be a non-empty string`);
  return value;
}

function stringArray(source: Record<string, unknown>, key: string, path: string): string[] {
  const value = source[key] ?? [];
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    throw new Error(`${path}.${key} must be a string array`);
  }
  return value.filter((item): item is string => typeof item === "string");
}

function rejectUnknown(source: Record<string, unknown>, allowed: Set<string>, path: string): void {
  const unknown = Object.keys(source).filter((key) => !allowed.has(key));
  if (unknown.length) throw new Error(`${path} contains unknown fields: ${unknown.join(", ")}`);
}

function parseMethodOperations(value: unknown, settingKeys: ReadonlySet<string>, settingsById: ReadonlyMap<string, MethodSettingAssertion>): Record<string, unknown>[] | undefined {
  if (value === undefined || value === null) return undefined;
  if (!Array.isArray(value)) throw new Error("method_profile.method_operations must be an array");
  const dependencies = new Map<string, string[]>();
  const operations = value.map((candidate, index) => {
    const path = `method_profile.method_operations[${index}]`;
    if (!isRecord(candidate)) throw new Error(`${path} must be an object`);
    rejectUnknown(candidate, operationFields, path);
    for (const key of operationStringFields) {
      if (candidate[key] != null && typeof candidate[key] !== "string") {
        throw new Error(`${path}.${key} must be a string or null`);
      }
    }
    for (const key of operationArrayFields) stringArray(candidate, key, path);
    for (const [key, allowed] of [
      ["grouping_basis", ["declared_group_membership", "field_equality", "raw_string_concatenation"]],
      ["selection_rule", ["FIRST", "LAST", "DISCARD_SUMMARY_IF_NON_SUMMARY_EXISTS", "RETAIN_SUMMARIES_IF_PRESENT_ELSE_ALL"]],
      ["event_payload_association", ["gesture_to_most_recent_paired_snapshot"]],
      ["sequence_encoding_rule", SEQUENCE_ENCODING_RULE_VALUES],
    ] as const) {
      if (candidate[key] !== undefined && !allowed.some((entry) => entry === candidate[key])) {
        throw new Error(`${path}.${key} is unknown`);
      }
    }
    for (const key of operationBooleanFields) {
      if (candidate[key] != null && typeof candidate[key] !== "boolean") {
        throw new Error(`${path}.${key} must be a boolean or null`);
      }
    }
    const requiredPayloads = stringArray(candidate, "required_event_payload_roles", path);
    const optionalPayloads = stringArray(candidate, "optional_event_payload_roles", path);
    for (const key of ["required_event_payload_roles", "optional_event_payload_roles"]) {
      const roles = stringArray(candidate, key, path);
      if (new Set(roles).size !== roles.length || roles.some((role) => !["screenshot", "view_hierarchy", "gesture"].includes(role))) {
        throw new Error(`${path}.${key} contains duplicate or unknown payload roles`);
      }
    }
    if (optionalPayloads.some((role) => requiredPayloads.includes(role))) {
      throw new Error(`${path}.optional_event_payload_roles overlaps required event payloads`);
    }
    const hasPayload = (role: string) => requiredPayloads.includes(role) || optionalPayloads.includes(role);
    if (candidate.event_payload_association !== undefined &&
      (!["screenshot", "view_hierarchy"].every((role) => requiredPayloads.includes(role)) || !hasPayload("gesture"))) {
      throw new Error(`${path}.event_payload_association requires the paired screenshot/hierarchy and gesture roles`);
    }
    const id = requiredString(candidate, "operation_id", path);
    if (dependencies.has(id)) throw new Error(`method_profile.method_operations contains duplicate ID: ${id}`);
    dependencies.set(id, stringArray(candidate, "depends_on", path));
    for (const key of stringArray(candidate, "configuration_dependencies", path)) {
      if (!settingKeys.has(key)) throw new Error(`${path} has unknown configuration dependency: ${key}`);
    }
    return candidate;
  });
  const visited = new Set<string>();
  const visiting = new Set<string>();
  const upstream = new Map<string, Set<string>>();
  const visit = (id: string): void => {
    if (visiting.has(id)) throw new Error(`method_profile.method_operations contains dependency cycle at ${id}`);
    if (visited.has(id)) return;
    visiting.add(id);
    const ancestors = new Set<string>();
    for (const dependency of dependencies.get(id) ?? []) {
      if (!dependencies.has(dependency)) throw new Error(`method_profile.method_operations has unknown dependency: ${dependency}`);
      visit(dependency);
      ancestors.add(dependency);
      for (const ancestor of upstream.get(dependency) ?? []) ancestors.add(ancestor);
    }
    upstream.set(id, ancestors);
    visiting.delete(id);
    visited.add(id);
  };
  for (const id of dependencies.keys()) visit(id);
  for (const [index, operation] of operations.entries()) {
    if (sequenceEncodingFields.some((key) => Object.hasOwn(operation, key))) {
      const path = `method_profile.method_operations[${index}]`;
      requiredString(operation, "sequence_encoding_rule", path);
      const scopes = stringArray(operation, "sequence_scope_operation_ids", path);
      const identities = stringArray(operation, "sequence_identity_setting_ids", path);
      const first = requiredString(operation, "sequence_first_symbol_setting_id", path);
      const repeat = requiredString(operation, "sequence_repeat_symbol_setting_id", path);
      if (!scopes.length || new Set(scopes).size !== scopes.length
        || scopes.some((id) => !upstream.get(String(operation.operation_id))?.has(id))
        || !identities.length || new Set(identities).size !== identities.length || identities.some((id) => !settingsById.has(id))
        || !settingsById.has(first) || !settingsById.has(repeat) || first === repeat
        || groupedSelectionFields.some((key) => Object.hasOwn(operation, key))) {
        throw new Error(`${path} has invalid partition-local sequence references or mixes encoding with grouped selection`);
      }
      let firstSymbol: unknown;
      let repeatSymbol: unknown;
      try {
        firstSymbol = JSON.parse(String(requireDefined(settingsById.get(first), "an id checked with settingsById.has() resolves").method_value_json)) as unknown;
        repeatSymbol = JSON.parse(String(requireDefined(settingsById.get(repeat), "an id checked with settingsById.has() resolves").method_value_json)) as unknown;
      } catch {
        throw new Error(`${path} requires literal sequence symbols as valid JSON strings`);
      }
      if (typeof firstSymbol !== "string" || !firstSymbol.length || typeof repeatSymbol !== "string"
        || !repeatSymbol.length || firstSymbol === repeatSymbol) {
        throw new Error(`${path} requires distinct non-empty literal sequence symbols`);
      }
    }
    if (!groupedSelectionFields.some((key) => operation[key] != null)) continue;
    const path = `method_profile.method_operations[${index}]`;
    const basis = requiredString(operation, "grouping_basis", path);
    requiredString(operation, "selection_rule", path);
    const scopes = stringArray(operation, "group_scope_operation_ids", path);
    if (!scopes.length) throw new Error(`${path}.group_scope_operation_ids must name an upstream partition`);
    for (const scope of scopes) {
      if (!upstream.get(String(operation.operation_id))?.has(scope)) throw new Error(`${path}.group_scope_operation_ids has non-upstream scope: ${scope}`);
    }
    const keys = stringArray(operation, "equality_key_setting_ids", path);
    if (basis === "field_equality" && !keys.length) throw new Error(`${path}.equality_key_setting_ids requires equality fields`);
    if (basis === "declared_group_membership" && keys.length) throw new Error(`${path}.equality_key_setting_ids must not invent equality fields for declared groups`);
    for (const key of keys) {
      if (!settingsById.has(key)) throw new Error(`${path}.equality_key_setting_ids has unknown equality field: ${key}`);
    }
    const operands = stringArray(operation, "concatenated_key_setting_ids", path);
    const defaults = stringArray(operation, "empty_if_absent_key_setting_ids", path);
    if (basis === "raw_string_concatenation") {
      if (keys.length || operands.length < 2 || operands.some((id) => !settingsById.has(id))) {
        throw new Error(`${path}.concatenated_key_setting_ids requires at least two profile-local operands and no equality fields`);
      }
      if (new Set(defaults).size !== defaults.length || defaults.some((id) => !operands.includes(id))) {
        throw new Error(`${path}.empty_if_absent_key_setting_ids must be a unique subset of concatenated operands`);
      }
    } else if (operands.length || defaults.length) {
      throw new Error(`${path}.concatenated_key_setting_ids and empty_if_absent_key_setting_ids require raw_string_concatenation`);
    }
  }
  return operations;
}

function snakeToCamel(value: string): string {
  return value.replace(/_([a-z0-9])/g, (_, character: string) => character.toUpperCase());
}

function equal(left: unknown, right: unknown): boolean {
  return JSON.stringify(left) === JSON.stringify(right);
}

function resolveMethodProfileOutputBinding(
  profile: StudyMethodProfile,
  setting: MethodSettingAssertion,
): { bindings: MethodProfileOutputBinding[]; blocker?: MethodProfileBlocker } {
  const registered = methodProfileOutputBindingForSetting(setting.method_setting_id);
  const registeredProfile = methodProfileOutputBindingProfileIdentityForSetting(setting.method_setting_id);
  const declaresOutput = setting.chronicle_output_kind !== undefined
    || setting.chronicle_output_column !== undefined
    || setting.source_output_position !== undefined;
  if (!registered && !declaresOutput) return { bindings: [] };
  let sourceField: unknown;
  try {
    sourceField = JSON.parse(String(setting.method_value_json));
  } catch {
    sourceField = undefined;
  }
  const candidate = {
    settingId: setting.method_setting_id,
    outputKind: setting.chronicle_output_kind,
    sourceField,
    sourcePosition: setting.source_output_position,
    canonicalField: setting.chronicle_output_column,
    conformanceFixtureId: setting.conformance_fixture_id,
    conformanceResultDigest: setting.conformance_result_digest,
  };
  if (registered && registeredProfile
    && registeredProfile.method_profile_id === profile.method_profile_id
    && registeredProfile.source_work_id === profile.source_work_id
    && registeredProfile.source_method_variant_id === profile.source_method_variant_id
    && registeredProfile.method_profile_version === profile.method_profile_version
    && canonicalJson(candidate) === canonicalJson(registered)) {
    return { bindings: [registered] };
  }
  return {
    bindings: [],
    blocker: {
      settingId: setting.method_setting_id,
      code: "missing_conformance",
      detail: "source output mapping does not exactly match the generated method-profile registry",
    },
  };
}

function sanitizePatchedOptions(
  baseline: BrowserProcessingOptions,
  patch: Record<string, unknown>,
): BrowserProcessingOptions {
  const hasUsageSelection = "processAppUsage" in patch || "processScreenUsage" in patch;
  return sanitizeOptions({
    ...baseline,
    ...(hasUsageSelection ? { processAppUsage: false, processScreenUsage: false } : {}),
    ...patch,
  });
}

const sessionConstructionPolicyFields = new Set([
  "session_construction_policy_id",
  "session_input_layer",
  "session_output_layer",
  "reconstruction_strategy",
  "method_settings",
  "source_locators",
]);

function parseSessionConstructionPolicies(value: unknown, settings: MethodSettingAssertion[]): Record<string, unknown>[] | undefined {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) throw new Error("method_profile.session_construction_policies must be an array");
  const ids = new Set<string>();
  const settingsById = new Map(settings.map((setting) => [setting.method_setting_id, setting]));
  return value.map((policy, index) => {
    const path = `method_profile.session_construction_policies[${index}]`;
    if (!isRecord(policy)) throw new Error(`${path} must be an object`);
    rejectUnknown(policy, sessionConstructionPolicyFields, path);
    const id = requiredString(policy, "session_construction_policy_id", path);
    if (ids.has(id)) throw new Error(`${path} has duplicate policy ID`);
    ids.add(id);
    for (const key of ["session_input_layer", "session_output_layer"]) {
      if (!methodTargetLayers.has(requiredString(policy, key, path))) throw new Error(`${path}.${key} is unknown`);
    }
    if (policy.reconstruction_strategy !== undefined) requiredString(policy, "reconstruction_strategy", path);
    if (policy.source_locators !== undefined && (!Array.isArray(policy.source_locators)
      || stringArray(policy, "source_locators", path).some((locator) => !locator.trim()))) throw new Error(`${path}.source_locators must be a string array`);
    if (policy.method_settings !== undefined) {
      if (!Array.isArray(policy.method_settings)) throw new Error(`${path}.method_settings must be an array`);
      const memberIds = new Set<string>();
      for (const member of policy.method_settings) {
        if (!isRecord(member)) throw new Error(`${path} has invalid policy member`);
        const memberId = requiredString(member, "method_setting_id", path);
        const canonical = settingsById.get(memberId);
        if (memberIds.has(memberId) || !canonical || canonicalJson(member) !== canonicalJson(canonical)) throw new Error(`${path} has duplicate, foreign or changed policy member`);
        if (canonical.method_setting_role === "reconstruction" && canonical.method_target_layer !== policy.session_output_layer) throw new Error(`${path} has a constructor/output target mismatch`);
        memberIds.add(memberId);
      }
    }
    return policy;
  });
}
